window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200326-10","meetingId":"r02-cm03","date":"2020年3月26日","dateIso":"2020-03-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","topics":[{"id":"topic-01","title":"開議時間","agenda":"開議時間","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"局長よりご説明がありましたが、厚生委員会におけます第２３号議案の指定管理者の指定について、私からおわびと訂正、そしてお願いをさせていただきたいと思います。従来、福祉施設には株式会社はなじまないというスタンスをとっておりまして、この第２３号議案につきましては反対とすべきところを、誤って賛成としてしまいました。ここでおわびをし、訂正をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"教育委員会教育長の任命同意について、反対させていただきたいと思います。理由は、品川区の教育行政は抜本的に見直しが必要だと思うからです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":13405,"voices":67}},{"id":"r02-20200327-6","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"区民委員会","time":"午前１０時５５分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"第２８号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第２８号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"幾つかあるのですが、まず、融資あっせんの強化ということで、もう既にたくさん相談が来ていると思うのですけれども、現段階で、通常よりもどのぐらい増えているか、数字をお示しいただければと、まず思います。","respondent":"山崎商業・ものづくり課長","answer":"今、３月２日に例の国のほうの４号認定が追加されまして、同日から延長窓口を開始し、約１カ月経過しようとしております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"ありがとうございました。大変な数になっているので頑張っていただきたいと思いますけれども、それから、よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"済みません。保証金の助成などにかかわって社労士の体制を整えていただいたというのは非常に素早い対応で、すばらしいことだと拝聴していたのですけれども、この社労士の代行費用の助成まで面倒を見られているというのは本当にすばらしいなと思って伺っていたのですが、この代行費用の助成というのは何％ぐらい、どのぐらいの割合で助成されているのでしょうか。お伺いいたします。","respondent":"山崎商業・ものづくり課長","answer":"通常、社労士の会社の、いろいろな内容を契約をしてお仕事をしていただいているところですが、今回の場合、このコロナの国の補助金に対しての申請の代行ですとか、もろもろの業務というようなところですので、区としましては。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"どんどん進めていただきたいと思います。それから、やはり、もう１つお伺いいたします。お伺いいたしますというか要望になるのかもしれませんけれども、やはり、利子補給、それからこういう雇用調整助成金や、休業補償ですか、学校の休業に伴う、それに対する社労士の体制を整えられた、あるいは経営のコンサルティング体制を整えられたというのは本当にすばらしいと思うのですけれども。これを伺います。","respondent":"山崎商業・ものづくり課長","answer":"それぞれのエリアに創業支援センターなどはまだありますので、いろいろな動向を見て、経営者の方がお忙しいことの手間暇を省くための仕掛けなのですが、武蔵小山だけなのかというようなお声がありましたら。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"今後もどうなるかわからない。国だけではなくて、地方自治体である東京都が自粛を要請するようになっている。品川区はそういうことをまだ行っていないけれども、これから本当にどうなるかわからないし、私たちも協力しなければならない事態で、そうして感染を何とか抑えていかなければいけないような事態になっていると思うのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"済みません。固定費。そうですね。固定費ですね。家賃だ、地代だ、次、光熱費だ、いろいろ固定費というのが考えられると思います。あるいは、イベントなどの中止に伴う必要経費などがあります。そういうものの直接助成、そういうこともいろいろ工夫していただけるのだと思います。この工夫というものも考えていただきたいと私は思うのですけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"リーマン・ショックのときの経済の混乱した状況の際に、一番利用されたのが、そのときは５号認定という認定でしたけれども、経営安定化資金というのがフル活動して、中堅企業の諸活動を支援したということもありますので、それを４号も併用してという形のもので、区としましては。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、課長がおっしゃいましたけれども、その状況、より深刻な状況になったらということでもおっしゃってくれたと思うのですけれども、本当にそういう状況を見ながら、私は小池都知事の宣言というか要請というのは１つのそういう節目だったのかなと思うのですけれども、東京都で患者さんが増えてということでもありましたし、１つの変化が見えてきたかなと私は思ったもので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"もろもろ伺いたいことがあるので、順不同でお伺いしていきます。今後、今回の補正に限らず、さらに追加追加でいろいろな事業、もちろん、コロナの感染の拡大の状況によって変わってくるかなとは思うのですけれども、今後さらに追加追加で予算を組む予定がある事業であるとかはどのようなものがあるのか、まずはそちらをお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"それは印象の話で、適正に必要な資金需要に応えるという、スピード感をもって対応する内容としましては、適正に区としてはご提案させていただいているかなというふうに判断しているところです。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"次のお話をお伺いしながら、今のお話に関してもう１回質問します。はもちろん、貸し付けの規模の部分が、結局、国のほうから指針が示されていると思うのですけれども、全く先が読めない中で、いつになったら売り上げが上がるだろうとか、そういった部分のめどが立たない中で、どういった基準で結局その信用保証協会のほうで貸し付けを、上限額を決めているのかどうか、そこの部分が気になるのですね。","respondent":"山崎商業・ものづくり課長","answer":"そうしますと、そこにコマの空きができたりというようなこともあって、そうしたところを柔軟に対応しているというのが現状です。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう間に合わないというところに関してですね。やはり今回、２億円増額になったのは、コロナ対策のためであるかどうかは、私は伺い損ねているのですけれども、さらにこれを追加で、昨年度、さらに追加なさったではないですか。今年度の２億円ではなくて、もう少し、今回の件があるので追加をしたらいかがかなと思うのですけれども、その辺に関してご所見を伺いたいです。以上、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"国のほうからもらっているのは医療機関であったりとか、そういったところが優先に配られているので、まだ一般的な企業であるとか、国民に配られるものというのはまだまだ少ないと思うので、品川区のそういった事業者に対して、足りない、どうしても必要だというところに対して、商業・ものづくり課として、例えば区でストックしているもの、先日の予特のほうでも。","respondent":"山崎商業・ものづくり課長","answer":"商店街の中の飲食をサービス提供する側としての、一番基本というのは、安心・安全のもとにおいしく、親しんでいただくような雰囲気をお店としてつくるからこそ、お客様も来ていただくという意味では、今。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問・要望","question":"国や東京都も、この中小企業対策というものに関しましては、予算をつけて、普通の予算でつけて助成はしているかと思うのですけれども、区がそれを、区のところに相談に来たときに、ワンストップでしっかりと連携がとれてできているのかどうかというところと、あとは、やはりハローワークとか、日本政策金融公庫、そういったところにもご相談があるかと思うのですが、もしそちらのほうがわかっていたら。","respondent":"山崎商業・ものづくり課長","answer":"こちら、いつまでのものという期限を設定したということではなく、来年度予算に計上したということですので、令和２年度の予算で予定をしている事業ということで考えれば、来年度、年度については少なくともということかなというふうに考えていただいていいと考えています。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それで、今まではそんなに相談がないというのが、そこまでじゃなかったというのが、もう今逼迫して、皆さんすぐにすぐにというような形で来て、相談員の方々も本当に大変なのではないか、ご苦労されているとは思うのですけれども、そういったところで、相談員が大変なところで報酬などが幾らで、これはこれまでと変わっていないような設定なのかというのを教えていただきたいのと、あとは。","respondent":"山崎商業・ものづくり課長","answer":"そうした予約制を敷いていますから、カウンターに来た状況では、それほど混雑した、過密な、いわゆるキーワードになっている３密の状態という空間ではありませんが、相談コーナーの入り口には、コロナ対策実施中で。","id":"exchange-013"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当にこの新型コロナウイルス、収束がまだ見えない中で、経営者も本当に必死で、いろいろな声を聞いておりますので、ぜひスピード感のあるご対応と、それから、状況によっては助成の延長といいますか、そういったものも視野に入れながらということと、あとは、今申し上げたとおり、相談員の健康を守るためにも、例えばブースに来た方々というか、ブースの安全性を確保するためにも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"参考までに、融資あっせんに申請をされた企業の業種ですね。どのような業種の方が来られているのか。そこで、個別の案件について、例えば、まずはごめんなさい。どういう業種なのかというところをまず確認します。","respondent":"山崎商業・ものづくり課長","answer":"いろいろなサービス業で、こういった時期に催事ですとか催し物が行われて、そこに品物を届けるような形の事業者さん、例えば、お花屋さんでありますとか、お菓子屋さんでありますとか、商店街の中に位置している個人事業主の方の相談がまず一番多いなというのが特徴です。","id":"exchange-015"},{"speaker":"こんの副委員長","kind":"質問","question":"イメージ的にそのように思っておりました。そうしたときに、やはり個人事業主で、お一人でされているところなどは、なかなか書類がきちんとそろわなかったり、あるいは不備があったり、あるいは用意が困難だったり、そうしたことが考えられますし、そうした場合の相談員の相談者に対する対応はどういうふうにしていただいているのかというところをお聞きしたいのですが。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、今回、相談員のほうも、品川区のことをご理解がまだ、日が浅い相談員もいらっしゃって、区の特性のなどを踏まえて、相談員のレベルアップを図りつつも、初めて融資の窓口に来て、相談員の説明が難しすぎて理解が困難であったとか、そうした、初めて来られた方。","id":"exchange-016"},{"speaker":"こんの副委員長","kind":"質問","question":"これは、切りかえと同時にするのか、もう、今の時点で、４月以降はもう受けられないのという、不安を持っていらっしゃる方もいらっしゃるので、早目早目のご案内というのが必要かなというふうに思いました。ダウンロードするご案内であったり、あるいは申請書であったり、そうしたものの細かい更新作業を早目にされたほうがいいかなというふうに思いますけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そうですね。４月１日はもうすぐですので、おっしゃった趣旨で対応させていただければということを考えています。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":23852,"voices":53}},{"id":"r02-20200327-7","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"厚生委員会","time":"午前１０時５５分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","topics":[{"id":"topic-01","title":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから感染症予防費２,３５５万円のところなのですけれども、今、３か月で２０人くらいの入院患者ということで想定されたということなのですが、今、日々すごく感染者が、昨日は４７人で、その前が４１人ということで、これからもどんどん増えてくるのかなという予想がされるのではないかと思うのですけれども、そこら辺のところで、これをさらに上回るような状況になったときには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＰＣＲ検査を受けた件数というのは、公表できないということでしたか。それは後でも結構です。専門家会議の中でもそのように書かれているので、ここのところは改める必要があるのではないかと思ったのですけれども、そこのご見解をお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"補正ということなのですけれども、専門家会議の中では、保健所が大規模なクラスター対策に専念できる人員と予算の投入をすることなどが必要だということでも書かれていたのですが、そういう点では、今も相談の窓口を保健師たちが、日常業務がすごく大変な中で、プラスでされているというところで、これからまた大規模なオーバーシュートと言われるような状況も懸念されているという中で。","respondent":"鷹箸保健予防課長","answer":"重症化リスクのある人は早目に受診をですが、その点については、ご本人が判断されるというよりも、基本的にはご高齢者の方も、あとは基礎疾患のある方も、かかりつけ医がいらっしゃると思いますので、かかりつけ医の判断のもとに、早目の受診が必要と考えられた場合には。","id":"exchange-003"},{"speaker":"あべ委員","kind":"提案","question":"この間の対応について、関係の皆様、本当にお疲れさまです。なので、予算措置が必要かどうかは別として、妊婦に対して、どういう対応をしていったらいいのか、あるいはどういう注意があったらいいのかということを取り出して、これを広報することはできないかというご相談といいますか、ご提案です。急に具体的なことで難しいかもしれませんが。","respondent":"鷹箸保健予防課長","answer":"妊婦に対して特別な感染予防があるかというと、そこは難しい部分があると思いますので、不要不急の外出を避けるというところが一番の基本かと思います。","id":"exchange-004"},{"speaker":"あべ委員","kind":"意見","question":"だからこそなのです。本人がわかっていても、職場の人たちが知らなければ、結局それが認められない。だから、広報というのは周りの人にしてほしいということなのです。ぜひご家族ですとか、特に職場の方にもわかるために、区民全体に、妊婦もこうなのだと、重症リスクを抱えた人たちなのだということを、わかってほしいということを知らせてほしいという、これはお願いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"介護の現場とか医療の現場に、マスクを区で配布していただいて、すごくありがたかったという声をお聞きしているのですけれども、それもメールで出したら、区から素早く持ってきていただいてというので、すごくありがたかったということだったのですが、今回、保育のほうは、５０万円を限度に出ているではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いや、医療と介護の現場でのそういう対応というところでは、ここに係るかなと思ったのですけれども、それは総務ということになるのですか。いないですからね。では、それは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、ここの補正のところで、医療廃棄物処理と従事職員用防護用具の中身についても教えていただきたいと思います。それからもう一つ、すごくこの問題は啓発が大事だと思うのですけれども、啓発というところでは、どんな取り組みを考えられているのかについてもお聞かせいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"啓発は今のところ、広報とホームページと、あと学校が休校になったところで、学校などでも個別に生徒たちに配っていただいているということは知っているのですけれども、目の前の感染疑いの方、感染不安の方、あとは実際の患者の対応に追われている状況でございまして、逆に今後。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問・要望","question":"今、詳細を聞かせていただきましたので、賛成をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3560#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10230,"voices":41}},{"id":"r02-20200327-9","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"文教委員会","time":"午前１０時５５分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","topics":[{"id":"topic-01","title":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"主な対象のものが説明されましたけれども、ほかのものであっても、感染拡大防止対策物品として対象になるのは、どこまでになるのかというか、どういったものになるのかというところでお聞きしたいと思います。期間といいますか、いつ購入したものが対象になるのか。支払いの方法はどういったタイミングか、手続なども含めて伺いたいと思います。","respondent":"大澤保育支援課長","answer":"購入物品の内訳ですが、具体的には先ほど挙げた物品を想定しておりますが、そのほかに感染症対策、感染防止のためということであれば、その都度、協議ということになろうかと考えています。購入に際しましては、４月１日からの購入品が対象になります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"対象について、その都度協議ということでしたので、ぜひ幅広く、対策で買ったものについては認めていただきたいと思います。ペーパータオルですとか、一時的な水を飲む場合は紙コップを買ったりということも聞いておりますので、そういったものでも、ぜひ対応していっていただきたいと思います。ですので、今まで買ってきたものも含めて対象にすべきだと思うのですけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"対象は４月１日からの購入にします。既に３月中に２万５,０００枚のマスクを各園に配付しておりますので、３月中の物品については、おおむねそれで賄えていると考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後、マスクですとか消毒液、ほかにも必要なものがありましたら、配付をしていっていただきたいと思いますけれども、いかがでしょうか。そういったものが不足しているかどうかということを、各園などの状況を把握していただいて、手配をしていただきたいと思いますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"今後も各園には、国から直接配付ということも聞いております。この状況がいつまで続くか、今は不透明な状況ですので、各園の状況については、区でもしっかりと把握をしていきたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういった手だてを講じていただきたいと思います。こうした残業代、時間延長された部分についても、ぜひ補助していただきたいと思いますけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"現在のところ、人件費の援助は考えておりません。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"児童センターの再開というのが検討されていましたが、議題の中にその他というのがないので、ここで聞くしかないかなと思いまして、伺いたいのですけれども、今後どのように考えていらっしゃるのか。予算特別委員会の総括質疑でもお聞きしましたけれども、学力テストの４月の実施。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"今後、学校が再開された場合には、実際、そのまま区のものはやるという話でしたが、国のほうは延期をしているわけでして、やはり今回の休校で授業が遅れてしまっているというところで、区でも学力テストを中止、少なくとも延期にしていくべきではないかと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったことも含めて、ぜひ考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"今回、私立保育園・幼稚園や認証保育所の感染症対策なのですけれども、小学校・中学校というのはどのようなことになっているのでしょうか。","respondent":"有馬庶務課長","answer":"小学校・中学校については、総務費にて、同じように感染拡大防止対策物品の購入というのがあります。こちらで学校のほうは手当てしていくという形になっております。","id":"exchange-008"},{"speaker":"塚本委員","kind":"確認","question":"一応、確認ですけれども、地域型保育事業にも１,１５０万円を計上していますけれども、２３園ということで、これは家庭的保育事業とか、そういったものを一切含むのかどうかというところを確認したいということ。認可保育園と地域型保育事業とは定員とかが全然違ってきますけれども、その辺りの上限の考え方というのはどのようになっているか、確認させてください。","respondent":"大澤保育支援課長","answer":"家庭的保育事業も含めまして、上限を１園５０万円で計上しております。","id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"わからないのですけれども、かなり格差というか、規模の違いがあるので、５０万円で大きな保育園では足りるのかとか、そういうところについての今後の推移によって、この辺りの考え方というのは柔軟に対応するというところは、どのように思っていらっしゃいますか。","respondent":"大澤保育支援課長","answer":"感染の拡大がいつまで長引くかということによると思うのですけれども、長期的になった場合は、再度予算を組まなければいけない事態になるのではないかとは考えておりまして、その場合は、改めてご提案したいと考えています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。その分、家にいるので、各家庭において、お昼を給食で賄われていたところが、家庭からの支出になっているというところでの相差というか、負担を見ていただいてほしいという。今後、国でどのような、あるいは、都でどんな話が出てきて、対応するか、その辺りはよく注視していただいて、区としても考えるべきところがあれば、ということでお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"確認","question":"先ほどの支払いのことで、一時的には園が立て替えるということだと思うのですけれども、領収書等を出してから、実際に支払われるまで、どれぐらいの時間というか、日にちを見込んでいらっしゃるのでしょうか。それだけ確認させてください。","respondent":"大澤保育支援課長","answer":"一律に日付を区切って領収書等を提出していただく場合と、５０万円の上限に達した時点で提出していただく場合と、両方があるかと思っているのですけれども、翌月または翌々月の運営費と一緒に支払うというのが通常のやり方ですので、それに沿ってやりたいとは思っております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"言い忘れました。今、出ていないので、対象にならないのかなと思うのですが、子どもたちは同じ子どもなので、こうした新型コロナウイルス感染症の感染防止という意味では、認可外であっても必要なところなのかなと私も考えまして、悩んだのですが、少なくとも区が助成をしている認可外については、同じ補助をしていくべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"区から認可外への補助というのは、今はしていませんので、補助金についても区がやる考えはございませんが、国のほうから認可外には対象として、同じスキームで補助があると聞いておりますので、おそらくそちらで網羅できると考えています。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"細かいところで確認なのですけれども、期間のところについて、４月１日からの購入分が対象ということだったのですけれども、終わりというか、いつまでというのは、現状での方針というか、そういったことはありますか。","respondent":"大澤保育支援課長","answer":"現在のところは、年度内中と考えております。","id":"exchange-014"},{"speaker":"横山委員","kind":"確認","question":"確認させていただきました。まだ、これからどのような形になるかもわかりませんし、国と都、そして区で、それぞれ役割分担をしながら進めていくものだとは思うのですけれども、例えば５０万円の購入費があったとしても、規模によったりですとか、あとは、マスクであったり消毒液などはなかなか購入が難しい部分もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=4996#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":5477,"voices":50}},{"id":"r02-20200327-5","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"総務委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"総論的な話になるのですけれども、今回の補正予算が対象とする時期といいますか、これは多分新型コロナウイルス感染症のこれからの状況を鑑みてやっていくと思うのですが、大体どの程度の時期を鑑みた結果この予算を立てたのでしょうか。","respondent":"品川財政課長","answer":"期間としては、とにかく４月から６月補正までの間を想定しての、基本的な考えとしてはそういう対応と考えております。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"例えば品川区で運営されています水族館とか健康センター等ありますけれども、そういったところも今軒並み収益が下降していると思うのですが、そういったことの補償といいますか助成といいますか、そういったものは計上がされておるのでしょうか。","respondent":"品川財政課長","answer":"今回の補正予算の中では具体的な計上はございませんが、水族館等、３月にこのやむを得ない状況により休館することになりましたので、基本的に３月分につきましては今年度予算の予備費という形で対応しています。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういうところで、品川区では融資のあっ旋を行っておりますけれども、そもそも論、無利子で借りたとしてもそれを返すことができない、その能力がもうないのだという話も聞いております。そういったところにもやはり区のほうでも本当に助けを必要としている事業者に手を差し伸べる形をとっていただきたいと思いますが、ぜひお考えを聞かせてください。","respondent":"品川財政課長","answer":"ということで、今回も融資等補正予算を上げているところですが、無利子でもなかなか返し切れないというようなところが今委員からお話がありましたけれども、今回、経営のアドバイス等、そういった費用も補正予算で対応するような形で計上しておりますので。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"これまでも区の施設はもちろん病院や私立の保育所もマスクは配られているというお話を伺っております。それも含めて数とどのように使うのかということと、検温器なのですけれども、東京都庁では来庁される方に検温をし、確認をした上で施設内に入る、そういう対応を既に行っておるのですが、品川区としてはどのような対応をするのか伺いたいと思います。","respondent":"立川総務課長","answer":"区としての検温器の対応ですが、検温器が現在入手できないという状況ですので、入手でき次第、出入り口でのチェック等を実施したいと考えているところです。消毒液につきましても同様です。検温器につきましては、区の出先施設を中心に配布したいと考えているところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"マスクと消毒液は、高齢者、障害者、子育て施設、学校、医療機関などなど対応していきたいということですけれども、民生費のほうで保育園に対して園で購入する新型コロナウイルス感染症の対応について上限５０万円で補助をするというのが示されておりますが、そういう意味では、保育園以外の、例えば介護施設、医療施設。","respondent":"立川総務課長、品川財政課長","answer":"納入関係についてご説明いたします。現状、見積もりをもらいたいと言いましても、納期のめどが立たないということで、事業者のほうも具体的な対応ができないという状況です。ほかの介護施設等につきましては、当然備蓄しているところとか、そういった部分から必要に応じて臨機応変に対応していかなければいけないと、そのように考えております。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"保育園のほうでは、園独自で購入したものに上限５０万円の補助をするということは積極的な意味があると思います。伺いたいのは、区単独でやるかどうかは別にしても、少なくとも国に対して、また都に対しても直接支援、これを品川区として求めていただきたいと思いますが、いかがでしょうか。","respondent":"品川財政課長","answer":"マスクの件については、基本的には今回計上しております危機管理経費の部分で、先ほどと答弁が重なりますけれども、臨機応変にその辺は対応していきたいと考えております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"少なくとも政府や東京都が呼びかけている自粛だったり、夜間の外出を控えましょうなどを担保する意味でも、事業主や個人に対して直接支援、これは必要だと思いますので、改めて求めておきたいと思います。今度の日曜日は日曜開庁するということがあらかじめ決まっておるのですけれども、それについてはどのように対応するのかご説明いただきたいと思います。","respondent":"黒田人事課長、立川総務課長","answer":"日曜開庁につきましても同様の考えでおりますので、今後例えば急遽外出禁止ということになれば、また庁舎をどうするかということになりますが、現時点では庁舎機能、人員配置については現行でというところで想定しています。日曜開庁について、お答えいたします。予定どおり開庁する予定です。ただ、問い合わせ等も多数考えられますので、そうした場合郵送等をご案内していきたいと思っています。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど行われた各所管の説明をもう少し詳しく聞きたいと思います。各所管のところに踏み込むので、ご説明ができない部分もあるかもしれないのですけれども、伺います。現在新型コロナウイルス感染症対応に追われて本来の保育ができない状況にあるという声も報道で上がっております。遠くから来ている保育士も来られなくなってしまったといった報道もあります。そこからお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"現在この制度自体に、事業者が経営悪化してしまって休業手当などが出せなかった、もう既に出せていない状況が起きてしまっているといった報道もあったと思うのですけれども、区内でもその状況があったのかという部分がもしわかればというのと、そういうケースもこの補正予算でどうにか対応できるものなのかといった部分についてお答えいただきたいのですが、いかがですか。","respondent":"品川財政課長","answer":"その中には当然人件費という形も含まれていると考えてもらって結構かと思います。こういう融資をやることによりまして、従業員に対して給料が払えるとかそういう形も出てくるかと考えております。それから、国の制度のほうでも補助の内容が十分あります。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"今回の補正予算で計上されている相談窓口のほうにとにかく相談をしてもらうという形が一番いいということでしょうか。その辺を確認させてください。","respondent":"品川財政課長","answer":"相談窓口も通常よりも各ブースを大体倍ぐらいに今回の補正予算で上げて対応していこうと考えています。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、そういった方たちに情報が届くように、待つだけではなく発信を強めていただきたいということを要望します。そして、話は変わりまして、電話相談センター開設経費が今回の補正予算で計上されているのですけれども、この電話相談センターというのは部屋で設置されるのですか。これこそテレワークとかの考え方はあるのかといった部分も含めてお知らせください。","respondent":"品川財政課長","answer":"電話相談センターは現在も開設をしておりまして、現状４人体制でやっているところなのですけれども、今回の補正予算で人員増強もしまして対応していきたいと考えております。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"区でどうこうできる話ではないし、市中にはお店にも全然出回っていないので大変だと思いますがお願いします。これは東京が人口が一番密集しているから本当に危険な場所だと思うし、品川区は人口が増えている。ですから、今は本当に融資でも何でもいいから、何とか残るように、また雇用がそこで回復できるように私は区のほうで相談に乗っていただいて、万全な体制を、支援をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"先ほどの補正予算が４月から６月が大体の目安という形でいっているのですけれども、来月になると学校が始まるのですよね。今学校のガイドラインが出てきたときに、マスク着用というふうになっているのです。今回教育費が入っていないので、おやと思ったのですけれども、巷にはマスクがないのでどうするのという話になるので、そこは区として対処をしていかなければいけないだろうと。","respondent":"品川財政課長","answer":"今回の新型コロナウイルス感染症対策の部分について、危機管理経費の項目については、基本的には区有施設を考えておりますので、当然学校も含んだ形で考えております。この中で、とにかく対応し切れるものは全て対応していくと、このような考えでおります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"予算確保なのですけれども、歳入のところですが、まず基金繰入金。それはどういうふうなタイミングを考えているのかということが一つ。そうなった場合に、６月補正で間に合うのか、例えば途中の臨時議会なども、例えば５月に臨時会がありますけれども、そこも含めて臨時でやらなければならない事態になるかもしれないという思いはあるのですが、その上程の仕方をまずお聞きしたい。","respondent":"品川財政課長","answer":"それはそれとしまして、やはり対応をとにかくスピーディーにやっていくというのが区としての考えですので、まず歳出のほうの予算を固めて、あと歳入はどのように来るかというところはまた補正予算等の時期に合わせて調整をしていきたいと考えております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"歳出のほうを先に考えてという話があったのは、もちろん迅速に対応していかなければならないというのは当然なのですが、区としてどういう方向で使うかということをもう少しはっきりしておいたほうがいいと思うのです。そうなってくると、またそこでも余裕ではないですが、ある程度使えるお金が出てくる可能性もあるので、その考え方はいかがでしょうか。","respondent":"品川財政課長","answer":"当然新型コロナウイルス感染症対策のほうについては補正予算等で対応していきますので、そこについては十分予算を確保してと、このように考えています。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"基金の有効的な、今回はダイレクトに使用するということになろうかと思うのです。半年で終わるのか１年かかってしまうのか、短くて済むのかというのは全く見えないところなのですけれども、やはり産業振興等々の支援にしても２通り考えておくべきだと思っていて、１つは緊急にお金を出さなければいけないという方法もあれば、あとは長く続くなと。これは意見で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"具体的に確認をさせていただきたいのですが、感染拡大防止対策物品購入で、高齢者施設、障害者施設、学校、医療、現場等々のお話があって、まさに感染拡大防止で必要だということでマスク、消毒液、検温器で１６１万枚、１万２００本等々があって、これは先ほど来お話があるとおり、予算をつけてしっかり対応していこうというところだと思うのですが。","respondent":"立川総務課長","answer":"入手見込みですが、委員のご案内のとおり大変厳しいということになっております。在庫につきましては、最新の状況ですが、マスクにつきましてはおおよそ１７万枚、消毒液につきましては約２,５００本です。日々数字が変わっております。おおよそその程度です。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうすると１７万枚は本当に足らない数なのだなというのを改めて今思ったのですが、そうすると優先順位をつけてなのか、１７万枚をどう使おうかみたいな話にもなってくるのかなと思ったのですが、その辺については何か対応をして、ここが優先みたいなのが考え方としてあるのかどうか、それこそ命にかかわるようなところがまずは大事なのかなとも思ったのですが。","respondent":"立川総務課長","answer":"とりあえず職員数分１枚ずつしか配布されないので、毎日使って毎日洗って毎日乾燥させてということがどこまで耐えられるのかわからないのですけれども、当然マスクがない状況におかれましては、そういった自助努力が必要かと考えているところです。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"一つ忘れていたのですが、保育園などへの補助の上限５０万円の根拠について、５０万円で足りるのかなという趣旨でその辺について考え方を教えてください。","respondent":"品川財政課長","answer":"この上限５０万円というのは、考え方はなかなか難しいところもありますが、マスク等の購入、それから各園の人数等も換算した形で大体この程度であろうということでやっているものですので、なかなか明確な基準というのは立てにくいのですけれども。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"大倉委員のほうから細かい部分の確認が出たのですが、それを踏まえてもう一回確認ですけれども、これは一個人の方も含めてそうなのですけれども、購入先については、区として発注するときにマスク、消毒液、検温器という大きいくくりがありますけれども、いろいろなところにアプローチをかけてなかなか厳しいという現実がある中で、いろいろなところに見積もりをまずもらっているのか。","respondent":"立川総務課長","answer":"マスク、消毒液に関しましては、衛生用品ということで、これまでも入札等を実施しておりますので、入札に参加している事業者に問い合わせをするというのがまず基本になります。それ以外には、個別に売り込みというような話も来ているところではあります。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"確認","question":"逆に言うと、ありますよ、売れますよという業者があったときに、どこの縦の縛りがあるのですか。積極的に営業に来ていただいて、どうぞどうぞ、これだけあるのだから使ってください、買ってください、大変ですよねというところがある場合、それは可能なのかどうか、確認させてください。","respondent":"立川総務課長","answer":"基本的に、いわゆる契約のルールというのがありますけれども、こういった非常時ですので、その辺は柔軟に対応したいと考えているところです。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"確認","question":"わかりました。それはすごく大事な部分かと思ったので。それからあと西本委員のところでやりとりがあって今大倉委員のほうで確認したときに、マスクの数１６１万枚は職員用だったのですけれども、先ほど西本委員のほうからは、子どもたちにつけないとまずいよね、いや、子どもたちにも考えているとある中で、大人用マスク、子ども用マスクでサイズ感が違うと思うのです。そこの確認をお願いします。","respondent":"立川総務課長","answer":"マスクの種類ですが、基本的に不織布マスクという、一般的にサージカルマスクというふうに言われているものですけれども、今回の見積もりについてはそちらを考えているところです。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"例えば、品川区の中でも３Ｄプリンタを持っていて、それで設計が可能かどうかと、課題もあるとは思うのですけれども、試験的に３Ｄプリンタを活用して、やってみるということとか、あとは布製のマスク、ガーゼだとか性質はいろいろあると思うのですけれども、例えば、障害者の授産施設とか、そういう型紙等があるわけですから、そういうのをつくってもらって、一定以上の必要なところについては、それでもし。","respondent":"立川総務課長","answer":"ですから、マスクありきという考え方をこの非常時は少し変えていただく必要があるのかということを思いつつ、３Ｄプリンタの活用、またいわゆる布製マスク等の手作りとかですけれども、この辺につきましては関係するところと協議いたしまして。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"確認","question":"総合審査で細かいところまで入り過ぎてもあれなのですけれども、購入がなかなか困難だというところで、一番大事な現場に行きつくというところの対策を区としてどうしていくかというところにおいては、当然質の担保、性能、いろいろな形で国会でやられたようにエビデンス、エビデンスとやられるところもあると思うのだけれども、そういうのもきちんと確認していただきながらだと思うのですが、その可能性。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"今本当にマスクが入手できないのにどうするのだといういろいろな不満が爆発している状況なので、それは早急に教育委員会と、もう来月のことなので、話し合っていただきたいというのが一つ。それからもう一つ、マスクなのですけれども、これも細かい話で、言うべきかどうか迷ったのですが、コロナウイルスは大きさが１０ミクロンなのです。このマスクは５ミクロンなのです。布製は大体１００ミクロンなのです。","respondent":"品川財政課長","answer":"ただ、どうしても用意できないような方の場合については、当然何か区のほうで用意をすると、そういう意味を込めて在庫で対応するという形で答弁をしておりますので、お間違えないようにしていただきたいと思います。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にこの緊急事態なので、ただこういう指針が出ている以上は、マスクというのは親にしてみれば本当に近々の心配事の一つです。なので、早急に教育委員会と話をして進めていただきたいと思います。基本は親御さんが準備することだろうと思います。でも、現実そうではないわけだから、それをやはり区として何かしらの形をしていっていただきたいという思いがありますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"賛成しますが、一言だけ述べさせていただきたいと思います。感染拡大に向けた検査体制の強化や病棟の確保、そのための財政支援、それから政府や東京都が外出規制を要請しているわけですから、それを補償する意味からも、中小企業への直接支援や医療施設、介護施設、障害者施設の直接支援など思い切った対応が必要だと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19710,"voices":73}},{"id":"r02-20200327-10","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"議会運営委員会","time":"午後 ２時５５分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5352#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1006,"voices":8}},{"id":"r02-20200415-10","meetingId":"r02-cm04","date":"2020年4月15日","dateIso":"2020-04-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"２つの特別委員会の設置を求めます。１つ目は行財政改革特別委員会です。調査事項につきましては、５項目挙げます。１つ目が、区有施設、公有地等の活用について。もう一つは、オリンピック・パラリンピック推進特別委員会の設置を改めて求めるものです。備考としましては、プレのイベントなどを積極的に続けるということを求めるために、調査項目を挙げします。これも引き続き求めるものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"特別委員会については２つ、行財政改革特別委員会とオリンピック・パラリンピック推進特別委員会の２つを、前年度と同様に求めていきたいと考えています。行財政改革のほうでは、庁舎のあり方に関することということで、これからまた、区の庁舎が新しく建て替えが行われるという前年度の委員会内容に引き続き、庁舎建て替えに関することを取り上げていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"新妻委員","kind":"提案","question":"公明党は、行財政改革、新型コロナウイルス感染症等対策、オリンピック・パラリンピック、この３つの特別委員会を提案します。１つ目の行財政改革につきましては、４点。庁舎のあり方に関すること、区有施設・公有地等活用に関すること、財源確保に関すること、働き方改革に関することの４項目です。これは、１年延びました東京大会の対応も含めてです。この３特別委員会を提案いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"日本共産党としては、４つの特別委員会の設置を提案したいと思います。１つ目は、羽田新ルート対策特別委員会。２点目は、新型コロナウイルス感染症対策特別委員会。３つ目は、品川区庁舎建て替え対策特別委員会ということで、現状の課題、庁舎基本構想、計画地、広町開発、議会棟についてです。最後に４つ目として、防災対策特別委員会です。地震、風水害、要援護者対応、気候変動対策、以上であります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"品改は、特別委員会設置には反対です。ならば、５つの常任委員会の審議時間を増やし、集中的に議論をするべきだと思います。そして、ほかの調査事項について、皆さんの話をお聞きしましたが、今、一番問題になっているのは、新型コロナウイルスが区民の命と健康、そしてご商売が倒産するかどうかという時期なのです。意見だけ言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本多委員","kind":"意見","question":"今の項目を見ていますと、庁舎のあり方などが入っているのですけれども、先ほどの議題にもありましたように、品川区庁舎機能検討委員会という委員会が設置をされるということで、議会からも４名委員が選出されるということなので、こちらの検討委員会に重きを置いたほうがいいのかなと思います。すみません、それだけ言わせていただいて、一旦終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"渡部委員","kind":"提案","question":"今の本多委員からもありましたけれども、私どもは庁舎のあり方に関することというのを提案させていただいていたのですが、先ほどの議題のとおり、今回、議員選出のメンバー４人を入れての検討会議が立ち上がるということで、また議会で別口でやるというのも、おかしな話になるのかなというところも感じますので、この部分に関しては、提案を取り下げるといいましょうか、あり方に関することというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"提案","question":"共産党としては４つの特別委員会を提案させていただいたところでありますが、まず庁舎のあり方についてですけれども、検討会があり、その報告も受けつつ、議会で議論を深めていくという点では、いろいろな役割があるのではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"新妻委員","kind":"提案","question":"ただいま、数と名称等ということでお話がありました。各会派のお話を伺わせていただきました。今回、公明党からは３つの委員会ということで提案をさせていただきましたが、それぞれ自民・無所属・子ども未来からも、危機管理等々も含めて入っております。コロナウイルスも出ております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"新妻委員と似たような感じなのですけれども、危機管理という言葉の中で、自・無が出していましたけれども、危機管理は行革の中で、総務委員会的なところもあるかなと思っていたのですけれども、行財政改革として、危機管理に関することということで出ていらっしゃるので、コロナ対策という点では、ここに入れたらどうかなと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"行革の中では、ほかの会派とのいろいろな絡みを考えていくと、うちで環境と出しているのですけれども、自・無の中で、オリパラで「開催を契機とした環境の取り組み」と出ているところで、そこに一緒にしてしまってもいいかなと思う。ですから環境を、リサイクルも含めた上で、オリパラに移すことも、自民党としては了解します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どちらがいいのかという。ただ、確認したいのは、もし先ほど鈴木真澄委員がおっしゃったようにオリパラのほうに入った場合には、オリパラに関連しての環境ということなのか、それとも環境一般という形で、行革の視点も入ってしまうかもしれませんけれども、そういうところで、そのようにしていただきたいということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これを契機としてということで、一つにはなるけれども、オリンピックだけにとらわれないでやっていただきたいという発想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"先ほど大倉委員からも説明させていただいて、私たちも環境問題を取り上げるに当たって、行革なのか、オリパラなのかという中で、オリンピックの開催自体に、環境に配慮したとか、環境というキーワードがオリンピック憲章にも出てくる中で、であれば、これを契機としたという意味合いで使っているだけで、オリンピックに関連した環境にとらわれずに、この先、ある意味、これのレガシーとしてでも捉えて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"行革とオリパラでという仕切りになりました。オリパラですけれども、やはり区民や障害者のスポーツ振興へ、現状の課題や対応策をオリンピック・パラリンピックという節目の中で、どう進めていくか、対応していくかという視点も大事ではないかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"本多委員","kind":"提案","question":"もともと環境ということで、行革のほうに提案したのですが、鈴木真澄委員が言うように、まとめるのは大事なので、項目をオリンピック・パラリンピックのほうに入れていただければと思いますが、環境とリサイクルで、別項目で求めていたのですが、一つにまとめて、例えば環境とリサイクル、あと、先ほど言ったようにプラスチックも大切ですし、集団回収も大切なので、一くくりでもいいのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"やはり環境と位置づけるのであれば、ＣＯ２など温室効果ガスを、どう減らしていくのかと。行政計画が定められて、毎年発表されておりますけれども、一言で言えば、ＣＯ２削減の視点は欠かせないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"財源確保についても同じような観点で、さまざまな税外収入的なものも含めて、横断的にやりたいという思いがありますので、できれば入れていただきたいという趣旨で、皆様のご意見をいただければ、繰り返しになってしまいますが、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"提案","question":"もう一つ、さっき本多委員からもお話させていただいたように、水族館が来年３０周年ということで、運営計画だけ、今何をやっているとか、そういうことではなくて、今後の計画ということについては、行革の中で詰めたらどうかということがうちの提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的には保健予防課長になるのでしょうけれども、危機管理とともに、保健所と言ったらいいのでしょうか、いずれにしても、コロナについては保健所の対応なくして進みませんので、どう位置づけられたらいいのかと具体的に言えないところは申しわけないのですけれども、いずれにしても保健所の視点が大事だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"そういう中で、先ほどほかの委員からもご提案あったように、これは行革のほうに、危機管理という中で、ただ、コロナウイルスは、先ほど委員長からもありましたけれども、仕切りの問題はあるのですが、総務課が今のところ取りまとめて、総務部でやっていますので、危機管理の中では、コロナウイルスを外すということではなくて、コロナウイルスを入れた上で、全庁的対応を問うという形では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"おまとめいただき、ありがとうあります。そして、ここの中では特に、品川区の新型コロナウイルス感染症対策本部が立ち上がっていると思いますので、しっかりとそこを受けとめて、この行革の中で議論をしていくということを、一つここにとどめていただければと思いますが、いかがでしょうか。それと、働き方改革に関してです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"オリンピック・パラリンピックのほうの２番、３番、４番のところに備考がないのですけれども、会派に戻って説明等も、どんなことなのかと聞かれたりするので、ここら辺がわかる範囲で、もしざっくりとあればお聞きしたいと思うのですが、特に３番のアリーナ計画というのは、今、庁舎の建て替えと一緒に話されている広町敷地内に建つアリーナ計画のことなのかとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"提案","question":"基本的に、そういう感覚です。既にいろいろ出ている中で、それも関係してくるのではないかということで、提案させてもらっています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-02","title":"新型コロナウイルス感染症の拡大防止に向けた対策等","agenda":"新型コロナウイルス感染症の拡大防止に向けた対策等","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これとはまた別というか、議会運営の話で要望というか、会派の中で話し合ったことで、今おっしゃったように、収束がまだまだ見えないという中で、ここの本会議とか委員会での取り扱いについては、今は公開の原則があって、傍聴ということが必要であるということなので、なかなかテレワーク的なものは難しいという中で、そのほかの諸会議についても同じ取り扱いになっているのですけれども、今後は。","respondent":"渡辺議長","answer":"やはり議会運営は議会運営委員会が中心になること。そしてそれぞれの委員会委員長と相談をする。丁寧に準備段階、相談という形が増えるかもしれませんが、諮っていきたいと思っています。現在も肝に銘じておりますが、意識して取り組みたいと思います。","id":"exchange-025"}]},{"id":"topic-03","title":"その他の(1)政務活動のあらましおよび年度収支報告書等の公開","agenda":"その他の(1)政務活動のあらましおよび年度収支報告書等の公開","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、国の支援、東京都の支援、休業補償等ありましたが、まだまだ私は不足していると思いますし、このままいけば、５月の後半では職を失う国民の方も、それから中小零細企業、そして小規模企業などは、私は倒産や廃業が進むと思います。品川区はせっかく一生懸命、１,０００億円という基金を蓄えていただいているのですから、それならば、その１割でもコロナ対策に回すような活用を、区に進言する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須貝委員","kind":"提案","question":"そしてまた、今日もテレビで言っていましたが、区議会においても、皆さんが大変な状況ならば、我々区議会議員の歳費の削減、２割から３割削減するという提案をしなかったら、区民の皆さんからして、事業をやっている皆さんからして、区議会は何をしているのだと、私は言われても仕方がないことだと思います。それだけ、もし皆さんでご意見があったら、言っていただけたらありがたいと思います。","respondent":"渡辺議長","answer":"既に多くの議員が、繰り返しますが、政策の提案、要望を、個人もそうですし、会派としても多くがされている。先ほどのような認識があることを大変反省して、議長職として議員に呼びかけていきたいと思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"刻々と状況が変わっているのです。そのときに言った提言と、今現在とは全然違うと思います。現実がどんどん実態も見えてきている中で、区民が今、どんな立場なのか、商売をやっている人はどんな立場なのかというのが、そして医療現場の大変さが、すごく明確に我々の目に飛び込んできているわけではないですか。","respondent":"渡辺議長","answer":"ぜひ須貝議員もお願いいたします。今、事務局一元化で、区とやりとりをきれいな形で行えていますので、ただ要望するのではなく具体的に、非常に有効な要望をぜひお出しいただければ幸いです。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5354#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":21825,"voices":86}},{"id":"r02-20200420-6","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"区民委員会","time":"午後 １時００分～午後 １時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","agenda":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２の（３）の雇用環境安定化事業助成金の雇用調整助成金のところなのですけれども、今、実績がないというお話だったのですが、これは相談もないのですか。","respondent":"遠藤商業・ものづくり課長","answer":"２の（１）の社会保険労務士相談窓口で設置しておりますので、ここでは話を受けていたり、あるいは電話で、この雇用調整助成金はどうですかという話は聞くのですが、私どもはまだ持ち合わせていないようなところがありまして、話は伺うけれどもという状況です。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"社会保険労務士の相談窓口なのですけれども、混み具合はいかがなものなのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"先週からシルバー人材センターを通じまして、各事業所にチラシを配付したので、一斉にどっと来た感じでして、今ですと、今月いっぱいがちょうど埋まっている状況です。来月でしたらまだ、来月の早い段階で予約を取っていただけるという状況です。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"同じく、１番の経営相談のほうなのですけれども、これの混み具合をお聞きしたいのですが、要するに、相談に実際に乗れるのは、３月の段階、前回の区民委員会で聞いたときは、たしか２週間か３週間お待ちになっているという話だったと思うのですが、現在ではどのぐらいの感じになっているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"４月から中小企業診断士の相談ブースを３つ増やしたところでありまして、今ですと、３週間まではかからない、大体２週間ぐらいでご相談は受けることができるかなという状況です。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"他方で、日本政策金融公庫の融資があります。そこでは必ずしも相談の段階で門前払いされることはないというお話も伺っているのです。だからがっかりしたという話を伺ったのですけれども、そこら辺は国と歩調を合わせて何とかならないのかなと、私はそのお話を伺ったときに思ったのですが、国と歩調を合わせるような考え方はできないものでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"それを受けて、今こういう滞納状況ですので、使える融資という部分では、対応できるのかなと思いますので、もしよろしければ、その旨をお話しいただいた上で、お電話でも頂戴できれば、こちらの診断士で対応したいと考えております。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから融資にしても、利子補給とか信用保証料を直接支援しているわけです。そのためには、よりみんなに自粛を求めなければいけない段階になってきた。そういう状況の中で、品川区もそろそろ、幾ら何でもいろいろ考えていいのではないかと私は思うのですけれども、品川区として何かお考えでしょうか。考えていただきたいと思いますが、どうでしょうか、伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"その一方で、そこの当該自治体が、都道府県がなかなか動きがなかったやに見えて、それで各市町村とかでも動いている部分があるのかなとは考えているところですが、今後、国とか都のいろいろな支援を見ながら、区で何かすることが必要であれば。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいと思います。商業・ものづくり課長から、新型コロナウイルス感染症対策支援に係るチラシ送付のご案内というのが、区民の方に送られているかなと思うのですけれども、これは対象がどういった方で、どのぐらいの範囲でお配りというか、ご案内されているのかというのを教えていただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"配ったのも、おそらく２万ちょっとぐらいという形では聞いているのですが、まだ先週ぐらいから始めて、先週中には配られたかと思うのですが、すみません、まだ実際に全部配られたかは把握できていません。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問","question":"事業所ということですけれども、これは全ての事業所を対象としているのか、それともある程度、何か対象区分とか、そういうのがあるのか、それを教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらで把握しているところにつきましては、全てお送りするです。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"経営相談・融資あっ旋窓口の対応ですが、先ほどおくの委員からも聞きましたけれども、シートで遮断したり、人数を少なくしたり、３０分で８件の対応をしてくれたり、いろいろご尽力いただいて本当に感謝しておりますが、やはり人が集まるということに対して敏感な時代であって、窓口支援を、わざわざそういうところに行くというよりは、今はインターネットといいますか。","respondent":"遠藤商業・ものづくり課長","answer":"なかなかそこの部分、５００円を返すのは難しいところがありますが、商店街連合会でやられているＴＡＫＥＯＵＴ ＭＡＰは、区で積極的にこちらを支援していくことを考えておりまして、区のホームページ、それから広報紙などに載せて。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"最後に、テレワーク助成の話でしたけれども、厚生労働省はシンクライアント端末のパソコンというのは経費として認めるが、それ以外のパソコンであったり、タブレットであったり、スマホというのは、助成として認めていないとか、助成も国によって、都によって、区によって、いろいろと違うと思うのですけれども、品川区としては、パソコンは２台買っていいとか、いろいろありますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"おくの委員","kind":"意見","question":"すみません。さっきの雇用調整助成金の実績がないというところなのですけれども、国の準備が整っていないからという、なぜ実績がないかというところがよく分からなかったので、ご説明願えればありがたいのですが、お願いできますか。","respondent":"遠藤商業・ものづくり課長","answer":"雇用調整助成金の相談の部分はあるのですけれども、その後の社労士の費用の助成を使ってさらに雇用調整金の申請という形になろうかと思いますけれども、そこの部分ではないというところでございまして、すみません、説明が不十分でした。","id":"exchange-010"},{"speaker":"こんの副委員長","kind":"質問","question":"概要とか手続とかが出ると東京都のホームページでも出てはいるのですけれども、これに関連する品川区の手続の窓口というか、手続上、何か品川区でしなければいけないことがあるのかというのが一つと、なかったときでも、この協力金についての手続などが、また各個店にお知らせとかというのは区からされるのかというところをお聞きしたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの周知方法という部分ですが、私どもの産業ニュースを、大体５月の中旬ぐらいに各事業所に配りますので、そこに載せられればというところは考えているところですが、ぎりぎりな部分がありますので、ほかの方法等を検討させていただければと考えています。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"支援の窓口がいろいろ、どんどん増えてくるではないですか。そういった中で、ホームページを見れば分かるのに、問合せが多いというのが現状あるのです。ああいう仕組みといいますか、システムみたいなのを構築してあげると、すごく丁寧で分かりやすいのだけれども、そもそもホームページが分からない人向けだと難しいとは思うのですが、そういうのがあると、すごく丁寧かなと思いました。","respondent":"遠藤商業・ものづくり課長","answer":"問合せに対してのＡＩとか、ああいうチャットボットを使っての返信という形かと思いますけれども、多分そういう部分であれば、使う業者の方は、すぐ分かっていいのかなという部分がある一方で、こちらの融資の部分にちょこちょこ変わる部分がありますので。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2864#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":12465,"voices":60}},{"id":"r02-20200420-7","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"厚生委員会","time":"午後 １時００分～午後 ２時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)を先に行います。 (3)新型コロナウイルス感染症の対応","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)を先に行います。 (3)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に感謝と敬意を申し上げたいと思います。それで、改めてお伺いさせていただきたいのですが、４月から相談件数がさらに一気に増えているという状況なのではないかと思うのですけれども、相談件数がトータルで３,５４９人というのが、４月１５日までの累計であるのですが、その中で帰国者・接触者外来に紹介した件数と、そのうちＰＣＲ検査が行われた件数についてお聞かせいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"入院の必要な人のベッドの確保はできているのかというところですけれども、これは判断が難しいところかと思いますが、おかげさまで４月１３日から東京都で一括調整をしてくれている結果、我々が日々電話をして、重症な人をお願いしますといったことではなく。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４月１５日に厚生労働省から都道府県や特別区に対して、地域外来・検査センターの医師会等への運営委託等についてという事務連絡が出されていると思うのですけれども、この辺については私たちも、共産党としても質問を出したときに、医師会など専門家を入れた対策会議も必要なのではないかということと、また発熱外来とかの設置の検討も必要なのではないかと言ったときに。","respondent":"鷹箸保健予防課長","answer":"と申しますのは、単に設置すればいいだけではなくて、設置した後は、従事される先生方が感染してはいけませんし、動線の確保も含め、また、今やっていただいている外来では、先ほどお話ししたように肺炎の有無を、検査の際は確実に確認した上で検査をしておりますので。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医師会の先生方と対策会議みたいな、検討会みたいなものというのは、発熱外来だけというか、今回出されていることについてだけ検討するということでやっているのでしょうか。それとも、対策会議みたいなものは定期的にというか、医師会の先生たちとの連携がどうなっているのかということについてもお聞かせください。","respondent":"鷹箸保健予防課長","answer":"その内容は、決して発熱外来というだけではなく、一方で、ちょっとお熱があるというだけで、どこでも受診できないという患者がたくさん出ている状況がありますので、そういった方々の受診の方法ですとか、そういったものについても今、協議を進めているところになります。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そうしましたら、４月１５日の厚労省からの事務連絡で、各自治体がこの連絡を受けて、すごく動いている状況というのが報道されているところなのですけれども、区としては、地域外来・検査センターの設置の見通しといいますか、いつ頃までにこんな形でとかというのは、全く見通しが協議の段階で出ていないのか、それともいつ頃までには結論を出すとか、そこら辺の見通しについて、最後にお聞かせください。","respondent":"鷹箸保健予防課長","answer":"今ご説明したとおり、品川区においては、それほどお待たせしているという認識は持っていないところから、地域外来・検査センターという形での外来の設置が必要かどうかも含めて、現在協議を進めているところになります。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検査のことについては、日本が検査の数があまりに少ないというところで、どれだけ市中感染が広がっているかという実態が見えないことが、医療崩壊にもつながっているという指摘がされている中で、検査体制をしっかり整えて、より多くの疑いのある人が検査をできるという体制は、私は必要だと思っていますので、地域外来・検査センターは、これだけ厚労省が事務連絡も出しているというところですし、東京都。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"は保健部門の皆様方、本当に１月、２月から、ずっと長丁場でこの問題に当たってくださって、心から感謝いたします。その上で、３点ほどお伺いしたいと思います。区として、陽性になった方のその次、つまり、検査の後の場を整えるというところも議題に上っているかどうかというのを、まず教えてください。","respondent":"鷹箸保健予防課長","answer":"後半のほうは聞き取れたのですが、初めのほうの、検体を採るだけではない連携がという意味がよく分からなかったので、もう一度お願いいたします。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"私が知る限りでは、２３区中１０区ぐらいで今、いろいろな独自の動きが始まっているかなと。そこの多くは、検体を採取する場を設けるという形での、行政と医師会と言ったらいいのでしょうか、行政の動きかなと思っているのですけれども、品川区がそういうやり方をするのでないというのであれば、どういう方向で今、検討されているのかということをお伺いしたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"いえいえ、違う。だから、そういうことをやらないのであれば、どういうことをやるのですかということを、オープンクエスチョンとして聞いています。","respondent":"鷹箸保健予防課長","answer":"今は全て病院でやっていただいていますので、例えばその日、夜に具合が悪くなっても、その病院にきちんと対応していただくというところを担保されています。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"２３区の報道などで、いろいろな区がこういうセンターを始めますということを聞くと、では品川区はどうなっているのでしょうかとよく聞かれるのです。今、どういう段階にあるのでしょうかと。その辺、品川区はこうなのですよというのが、何かあるといいのですけれども、難しいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"２点目に入ります。妊娠された方へのフォローなのですけれども、妊娠した方、妊婦に対するサービスというのが見えにくくなっていると感じています。今、妊婦は一体、どこにどのように相談をしたらいいのか、あるいは相談の窓口を明らかにして、それを周知していただきたいと思うのですけれども、今だったら、妊婦はどうしたらいいのですか。教えていただいていいですか。","respondent":"高山健康課長","answer":"今、保健センター所長はこの場におりませんけれども、基本的には対面での事業ができないということもありますので、資料にありますように、保健師が必要に応じて個別に電話や訪問などをすることで、フォローさせていただいているところです。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"育児パッケージについては、東京都がプラス上乗せでタクシー券等々を乗せるということを、既に公表しておりまして、そうすると、既に区でもらっている人はどうなるのかなとか、この期間にもらえないのかなとか、いろいろそれも疑問があるようなので、そういったことも併せて、今、妊娠が判明している方、それから妊娠していて妊娠届を出していない方への周知をぜひお願いしたいのですが、いかがでしょうか。","respondent":"高山健康課長","answer":"そのほか、とうきょうママパパ応援事業などに交付されておりますタクシー券などの上乗せ事業につきましても、まだ詳細は区に来ておりませんので、そうしたものが来ましたら、もらえる、もらえないの間に不利益などがないように。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後になります。保健部門として、区の他の部署に対して、保健の見地から、感染防止の見地から、何か指導というか、助言というか、そういうことはなさっているのでしょうか。","respondent":"鷹箸保健予防課長","answer":"区の施設、それから区内の区立公園、都立公園もありますけれども、基本的にその中での方針というのは、本部会議で詰めて決めて、あとは各部での判断に任されるところがありますが、都立の公園であれば都から出された方針、区立の公園であれば、都の方針に準じて区で決めて。","id":"exchange-012"},{"speaker":"あべ委員","kind":"意見","question":"例えば公園を使える、使えないとか、その中の大型遊具を使う、使わないというのは、自治体によってかなり対応が分かれているかと思うのですが、今のご説明の、都の基準で皆さん一律でそういうことだと、自治体によって違うということは出てこないと思うのですが。","respondent":"鷹箸保健予防課長","answer":"そこまでの遊具の使い方の差ですとか、その辺までは、申し訳ありませんが、保健所として把握しておりませんで、公園あるいは児童遊園といったようなものについても、都の考え方にのっとって使っていると私のほうでは理解していたところですので、違いがあるとすれば。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"その判断というのは、感染症学的と言ったらいいのでしょうか、それは感覚的なものではなくて、知識に裏づけられた判断をしていただきたいと思いますので、そこはぜひアドバイスをしていただければと思います。これを最後の要望にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"に戻りまして、(1)品川区立西大井福祉園","agenda":"に戻りまして、(1)品川区立西大井福祉園","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４月１日から始められているということなのですけれども、このように定数が変更になったというのは、相談事業所とか、そういう関係するところへの周知というのがどうなっているのかということを、１点お聞かせいただきたいのと、生活介護と就労Ｂの報酬という点では、どう違うのか。事業所に入る報酬というか、そういうところではそんなに変化のないものなのかどうか、その点だけお聞かせください。","respondent":"松山障害者福祉課長","answer":"２点目の報酬の違いについてですけれども、今回とりあえず、生活介護と就労継続支援Ｂ型のそれぞれの報酬単価というのは、もちろんありますけれども、報酬の内容というよりは、利用者の実態に合わせて定員を変えたものですので、特に報酬の面からということは。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは区立なので、指定管理ということですので、当然報酬が変わったら、それに合わせての委託料というか、そういうのも変わるのかなと思って聞いたところなのですけれども、そういう点では、事業者にマイナスになるようなことのないように、配慮はお願いしておきたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"これは利用者の方の高齢化に伴って、このような変更をしたということで、ということは逆に言えば、変更しても、利用されている方は基本的に同じ方が利用していると考えてよろしいのでしょうか。確認です。","respondent":"松山障害者福祉課長","answer":"利用されている方は、就労継続支援Ｂ型の方が生活介護をご希望されてということなのですが、状態といたしましては、生活介護の状態であったというところで、西大井福祉園の中での事業の所管を変えたということになります。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"確認ですが、これまで就労Ｂで使われていた方が、いられなくなってとか、そういうことではないということでよろしいですか。","respondent":"松山障害者福祉課長","answer":"そういうことではないです。","id":"exchange-018"}]},{"id":"topic-03","title":"障害福祉計画策定のための基礎調査の結果","agenda":"障害福祉計画策定のための基礎調査の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと同時に、障害別に、どんな要望だったりとか、どんな状況だったりとか、どんな困り事だったりとかというのが分かるような形にすべきではないかと、たしか言ったような気がするのですけれども、そういうことに対しても、クロス集計もしっかりとやっていくというご答弁だったと思うのです。７ページのところ。６年前は障害者別につくっていたので、そのように今回も改めていただきたいというのが一つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は改めて……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"質問していますから、聞いていてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"クロス集計は、年齢や性別、地域などをクロスして、よりデータを深掘りしていくもの。そういうものがクロス集計だと思いますので、今回のアンケートのまとめに対しても、ぜひクロス集計をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前回はアンケートのまとめという形で、クロス集計をしたものが出されてきたのですけれども、ではこういうものは、これからまた改めて出てくるということで考えていいのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"策定委員会において、必要なものについてはクロス集計をしまして、分析しながら計画に反映をするということで考えております。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"言葉は悪いですけれども、こういう手を抜いたようなグラフで出してくるというのは、どうなのかなと本当に思います。委託の仕方で、相談とかはされたのでしょうか。トータルだけだったら、次の分析につながらないものをつくって、印刷して冊子にしてしまうというのは、もったいない気がするのですけれども、そこら辺はどうお考えでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"それを用いまして、クロス集計はいかようにもできるような形になっております。資料のまとめとしては、それぞれのクロス集計をしたものを全て表しますと、膨大な量になりますので、今回はアンケートの質問内容に沿いまして集計をしたです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"確認","question":"そうしたら、確認しますけれども、ここにプリントしていただいた二百数十枚のページのものというのは、あくまでも内部資料として、ここでお出しいただいているだけで、これはあくまでも検討委員会の中だけで使われる資料であって、特にこんな表紙をつけたりすることもなく、この状態で検討されると考えて、あくまでも内部の生データと考えてよろしいですか。","respondent":"築山障害者施策推進担当課長","answer":"こちらは計画策定に当たって使わせていただくデータです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"生データということであれば、ここの中に書かれたものが、自由意見が全て載せられているのでしょうか。そこのところを伺いたい。","respondent":"築山障害者施策推進担当課長","answer":"自由意見については、全て載せているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところは改めて確認していただきたいのが１点です。それをお答えいただきたいと思います。全部載せたかどうかの確認はされているかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこのところは、前回のものとこれを比べて発注するというか、そこら辺のところはされたのでしょうか。それであれば、もう一回しっかりとしたものを、この厚生委員会に報告すべきだし、生データといっても、本当に誤解を招くような、間違った集計の仕方なのではないかと思うようなものを、このまま出されるということに関しては、問題とは感じられなかったのか、その点についても伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、その報告書に沿ってまとめたということなのですけれども、障害者を全部ひっくるめてグラフにするというやり方は、おかしいのではないですかと伺っているのです。その点については、ご覧になられてどうだったのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"こちらも同じ回答になりますけれども、データで頂いておりますので、策定委員会において、必要に応じた分析をしながらとなってまいります。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"クロス集計もしっかりとしたものを、この委員会の中でも報告していただけますでしょうか。それで、このまま、私はどこに出るか分からないのですけれども、このようなやり方というのは、本当に誤解を招く中身になってしまうと思いますので、ここのところは訂正した形で、障害者別のグラフにするなどの訂正をした上で、出していただきたいと思うのですけれども、最後にこの点をお伺いします。","respondent":"築山障害者施策推進担当課長","answer":"この後、今年１年をかけまして策定委員会を開催してまいりますので、その中で、途中で報告できるものがあれば、ご報告をすると考えております。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それと、発達障害のところも、障害児のところを見ますと、手帳を持っていないというところに、多分集計されてきてしまっているのではないかと思うのですけれども、やはり要望の多いところですし、教育の面でも、教育委員会にもこういう見える形で出ていれば、大きなサンプルになると思いますので、そうした別立てのほうを、難病、医療的ケア、そして発達障害というのを出していただきたいと思うのですが。","respondent":"築山障害者施策推進担当課長","answer":"調査結果をどのように反映していくかにつきましては、策定委員会において検討してまいります。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"その策定委員会ですけれども、メンバーはどのようになっていたのでしょうか。自立支援協議会とかでも、当事者の方の意見をぜひ反映してほしいということで、今も要望がある中ですので、３年間の障害福祉計画をつくる会議体ですので、当事者を多く入れた会議体にしていただきたいと思うのですけれども、メンバーは何人ぐらいで、どんな方が入るのか、伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"現在の予定ですけれども、学識経験者の方、それから保健医療関係ということで医師会を想定しております。それから、福祉の関係の区内の事業者等を想定しております。教育関係のところでいきますと、特別支援学校を想定しております。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3562#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":25335,"voices":118}},{"id":"r02-20200420-8","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"建設委員会","time":"午後 １時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)から(7)を先に行います。 初めに、(4)特定空家等の認定","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)から(7)を先に行います。 初めに、(4)特定空家等の認定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれの件で情報提供が住民からあったということですが、近隣住民からどのような声が寄せられたのか伺います。特定空家等に認定されて、これから法に基づく措置を順次実施と、一番下にありますけれども、具体的にはどのような措置がなされ、解決に向かっていくのかも伺います。","respondent":"森住宅課長","answer":"基本的には、すぐに命令、代執行ということよりも、所有者とコンタクトが取れておりますので、それぞれ情報を頂きながら、こちらからも必要な情報等を提供しながら進めていければと考えております。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、すみません。助言、指導、勧告なのだけれども、先ほど固定資産税という話がありました。特に第７号は、これぐらいの床面積で、昭和３２年ぐらいの築年だと、固定資産税は多分ほとんどかかっていないと思うのです。そうすると、１０年たっても何万円です。だから、そこら辺のところをどうお考えになっているのかだけ教えてほしい。","respondent":"森住宅課長","answer":"本年度につきましては、新たに令和２年度予算で、民間の事業者に委託を考えておりまして、その中で直接、福祉でいうアウトリーチではないですけれども、そういったところで所有者のほうに伺って、例えば、売却するとこのぐらいの相場ですとか。","id":"exchange-002"},{"speaker":"松本委員","kind":"質問","question":"品川区の過去の事例を調べると、代執行まで行った事例があるということで、この理由はたしか家屋に近接とか、通学路沿いとか、そういった事由があったかと思うのですけれども、今回のこの３件については、そのあたりはどうなっていますでしょうか。","respondent":"森住宅課長","answer":"状態の悪いものとして３件をまずは特定空家等として認定したです。例えば崩れたりすると周りへの影響が大きいものもありますので、今後一生懸命取り組んでいければと考えております。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"おそらく対応は取られているかと思います。周辺に、例えば、崩れてどうにかなるというのを予防する措置というか、周知も含めて、そういったところはどうなっていますでしょうか。","respondent":"森住宅課長","answer":"審議会の中でも、委員にそれぞれ見ていただきまして、コーンの設置、そういったものも今後進めていこうと考えております。周辺の公共施設といいましょうか、保育園だとかには注意して登園なりお散歩に出かけてというようなことは周知をし、お願いをしています。","id":"exchange-004"}]},{"id":"topic-02","title":"分譲マンションの管理状況届出制度","agenda":"分譲マンションの管理状況届出制度","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"中身について幾つかお伺いしますけれども、まず、届出内容の真偽はどう確かめるのかというのが１点目と、２点目として、届出の強制力はどこまであるのか、罰則はあるのか、届け出なかった場合はどうなるのかということです。それと、届出事項には、管理費の有無、修繕積立金の有無などがありますけれども、どこまでチェックするのでしょうか。伺います。","respondent":"森住宅課長","answer":"それとどう比べてというのはあるかもしれませんけれども、そういったものをそれぞれ各区、あるいは区内の分譲マンションで突き合わせをしながら、必要な助言はできたらと考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"１点目の届出内容の真偽は、どう確かめるのかという質問をしたので、改めてお伺いします。それと、今の説明の中で少し触れられたかもしれませんけれども、届出内容を確認して必要な助言等を行っていくとありますが、管理不全の状態を防いでいくというのがこの制度の目的だと思うのです。その実効性を担保する体制を、住宅課としてどう構築していくのかについて伺いたいと思います。","respondent":"森住宅課長","answer":"事務作業にあたり、派遣職員の配置も今年度から実施をしておりまして、届出に対して適正に対応できるような体制を取っていると考えております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。はこういった制度が始まるということで、結構悩んでいるところはたくさんありますよね。そういうところを糾弾するというのではなくて、一緒に問題点を共有して、一緒に寄り添って解決していくという方向でぜひこの制度を活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"しながわＥＣＯフェスティバル２０２０の開催中止","agenda":"しながわＥＣＯフェスティバル２０２０の開催中止","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことに対して、自ら区としての姿勢を示すという意味で、そのような製品の削減を今後区の事業の中で行っていく予定があるのかどうか、その辺、伺いたいと思います。","respondent":"提坂環境課長","answer":"本来、環境課が参加する予定でなかったイベントについても、環境課が参加できるかどうかということを検討して、前向きに取り組んでまいりたいと考えています。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは今のこの状況だったら中止は致し方ないけれども、これは、今まで二十何回もやってきているとなると、出てきてくださる業者の方というか、いろいろな方々も慣れている方が多いではないですか。みんな中止ばかりというのはしようがないけれども、終息が見えないから何とも言えないけれども、そういうことがあれば、一気呵成に行うとなったら、復活する可能性があるかだけ、お聞かせください。","respondent":"提坂環境課長","answer":"今回、ＥＣＯフェスティバルについては中止ですけれども、その分、ほかのイベントについては一定程度期間が過ぎた段階で、例えば、しながわ宿場まつりですとか、夢さん橋とか、そういうところにもブースを出していくとか。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。今のお話で、何でもかんでもやめるというのは私もしようがないと思っています。どうしてこういうことを言っているかというと、先が見えない中だけれども、このイベントはもう何回もやっているから、皆さん、準備もそんなに難しくないと思うのです。だから、そういうことも考えるのであれば、例えば、秋に行うイベントで、今発注しておかないと無理だというものは、この時点でやめましょうと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-04","title":"実機飛行確認における航空機騒音の精査結果","agenda":"実機飛行確認における航空機騒音の精査結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この国の資料の２つのグラフというのですか、何が違うのかが分からなかったというか、少し分かりづらいと思いませんかということで、お願いします。","respondent":"鈴木都市計画課長","answer":"その下、青のほうは、ＩＬＳ運用時、降下角３度の場合と３.４５度の場合では効果が出ましたという内容です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは私が理解できていないということなのか、もう一度教えていただきたいというのと、それとあと、水色のほうのグラフでは、何で東京都南部下水道事務所品川出張所のほうはむしろ０.２デシベル上がってしまうのですかという、そこら辺はどのように区は認識しているのでしょうか。","respondent":"鈴木都市計画課長","answer":"下水道品川出張所において、０.２デシベル上昇したということで、これは国のほうに今確認しているところですが、基本的には、データもまだ７日間ということで、これから国のほうは本格運用を開始して、測定結果を積み重ねていくと言っていますので。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺は国のデータなどもよく分析して、説明をしっかりと聞いていただきたいと思います。そのことをもって、国は今回のこの資料で騒音軽減が確認できましたという認識を示しているのですけれども、これは数字上ではそうかもしれませんが、これは実際、住民、人間の耳で聞き分けられる程度なのかどうかというのはどうなのでしょうか。実際に下がったということが、聞いていて分かる値なのかどうか。","respondent":"鈴木都市計画課長","answer":"区としては、騒音軽減に向けた取組みというのは今後も様々取り組んでいただく旨、国に強く求めていくわけですが、ただ、８０デシベルですとか、あるいは何か法律に基づいていない数字で超えた、超えないという議論よりも、やはり１つでも１デシベルでも。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"それがあたかもご説明の中で、推計値を超えていないから大丈夫みたいに取れてしまって、それはいかがなものなのだろうか。それを区として国のほうに求めておられるのかどうか、その辺について伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国が特に大井町上空で８０デシベル程度の音が予想されますということで、決定前にいろいろな説明会の中でお示ししてきた数字ですが、所管としましても、これを超えたから超えないからそれでいいのだという認識は持ってございません。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり調査のほうも、国にぜひ強く求めていただきたいと思います。かなりきめ細やかな調査が必要と思いますが、ぜひ国の責任として求めていただきたいのと、併せてやはりもし品川区民に何か被害が出たときに、数字で出なくても、疫学的調査も被害を証明する根拠になり得ます。なので、ぜひ今後区としても検討をしていただきたいと要望しておきます。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-05","title":"コミュニティバス導入に向けた検討状況","agenda":"コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"松本委員","kind":"質問","question":"例えば、荏原ルートだったら、私も武蔵小山に住んでいるので思うのですけれども、タワーマンションがかなり今建っていて、大崎や大井も平成２７年と比較すると、人口が変わっているのかと。平成２７年と比較して、現時点だと結構変わっているかと思うのですが、そのあたりというのは、今回の評価の中である程度考慮されたのかどうか、そのあたりをお願いいたします。","respondent":"鈴木都市計画課長","answer":"基本的に１１の評価指標を検証していく場合の人口ですとか、そうしたものは住民基本台帳の最新のデータで現時点のものを使っているのですが、国勢調査は平成２７年度が最新でして、どうしても人口を出すときに、(3)のところで１日あたりの利用率というのが出てくるのですが。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問・要望","question":"これから実際に試していくというところになるかと思うので、その際に少しデータと違うようなところがある場合には、そういったところも気を付けながら、引き続き検証していただければと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問・要望","question":"別紙３なのですが、３つのルートともになのか、地域の要望があるようなところには、車両の大きさ、車幅の問題、車両制限令とかでなかなか行けないというご説明もありました。そこを教えてください。","respondent":"鈴木都市計画課長","answer":"最後に、資料の運行収支ですが、これは先ほどご説明したとおり、１日あたりの利用率によって大きく増減するところもありますので、区の一定程度条件をつけて試算をしてみるとという形での提示です。必ずこうなる、こうしたいというものではございません。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。特に私が、地元で分かっているところが大井ルートだけなので、そういう声をぜひできる限り聞いていただいてということは１つ要望するのと、あと、区のほうの設定のところで、プロポーザルをこれから行っていくのですけれども、プロポーザルで、例えば、収支率というか、そういったものをバス事業者に求めるということでいいのか。","respondent":"鈴木都市計画課長","answer":"そうした赤字のままではどこの事業者も手を挙げるということはないので、その赤字をどれだけ区として補填というか、運行経費として支援しますというところの数字も、パーセンテージも、赤字を丸々毎年度、多かろうが少なかろうが。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、地域の方と話して、警察とも話して、通すことが可能だということになれば、そうなってくると、地域の方のご協力というか、これは、条件にも出てきていて、利用率の問題とかも出てくるので、そこら辺のお互いの話合いもぜひしていただいて、西大井本通りの中に入っていくようなことを地域の方とも話していただきたいということをお伝えくださいと言っていたので、それだけお伝えします。","respondent":"鈴木都市計画課長","answer":"この大井ルートの左側の地域につきまして、特に西大井本通りは、その地域の中でも比較的幅員が広いところですので、場合によっては、白線を引き直すとか、そうしたところをしっかり検討して、警視庁のほうとも、地域の声も聞きながら、協議を進めていきたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"このパブリックコメントが明日からということですけれども、先ほど来から、もうやっていますみたいな話だったのですが、明日だと思うのですけれども、導入計画ですとかルート案というのもパブリックコメントの資料として出すのかというのを聞きたいのと、あと、別紙４の今後の予定のところで、３回分の地域公共交通会議の日程も出ていますが、地域公共交通基本方針はいつぐらいに策定をするのか。","respondent":"鈴木都市計画課長","answer":"別紙４のところを見ていただきまして、スケジュールなのですが、令和２年、今年６月に第１回目の地域公共交通会議を実施予定なのですが、その中で、まず、地域公共交通基本方針については、パブリックコメントを反映した形のものをお諮りして、案という形ですが。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。それと、地域公共交通基本方針（素案）について伺います。これまでも明記するよう求めてきたのですけれども、改めてこの方針に入れるよう求めたいのですけれども、いかがでしょうか。そして、区はなぜこうした観点を入れないのか、その理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"だからといって、区のこの基本方針に、高齢者も含めた、障害のある方も含めた様々な方の交通の手段の足となるという形の視点は、当然、持っていないわけではございませんで、それはコミュニティバスを含めた民間のバス、あるいは鉄道を含めて。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは素案ですから、ぜひこれからパブリックコメントをかけて、また地域公共交通会議にかけるわけですけれども、ぜひその視点を持っていただきたいと改めて要望したいと思います。ここら辺を、素案ではこのように書いているのですが、見直しを求めたいのですけれども、求めた上で区のここについてのお考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当然ながら、導入計画ですから、その後一定程度、５年１０年というのは長過ぎますが、試行運行、本格導入した路線が定着してくれば、状況によっては、その次のルート案の検討ということも考えていくということはあろうかと思います。","id":"exchange-023"},{"speaker":"安藤委員","kind":"意見","question":"前段のところの説明は少し私は納得がいかないですけれども、機械的な廃止基準を、今から決めるというのは少し違和感があるのです。これは意見なのです。ルート案なのですけれども、ワークショップという話がありました。周知なども含めて、もう少しそれを聞きたいというのが１つと、あと、３つのルートを、ありていに言えば、幾つに絞る考えなのか。どういう基準に絞るのかというのも聞かせてください。","respondent":"鈴木都市計画課長","answer":"その１３地域は対象にするのですが、人の募集の仕方ですとか、何名程度というのは、これからしっかり検討してきたいというところで、時期については、当然ながら、プロポーザルの事業者を選定する前に、できれば６月ですとか７月。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。ワークショップがすごく大事なのかと思いました。最後にもう一つだけ、料金なのですが、シルバーパスと低廉な料金の併用、例えば、１００円ワンコインという料金にし、困っている方が気軽に利用できるようにすべきだと思うのですけれども、シルバーパスと料金との関係、１００円にしてなおかつシルバーパスの利用というのは可能なのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"車椅子の方が乗れる、あるいは誰でもが乗れるバスにはならないという形になってしまいますので、やはりそこはバリアフリー対応のバスをまず考えて、警察のほうとの協議も入り口ですので、できるだけ、ただ、そこの視点の中では、そこのエリアを走らせるために。","id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"最後のところですけれども、基本的にはということなので、私もこれから、ぜひそのようにすべきではないかと思います。そういう声も頂いています。なので、研究もして、提案もしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"ワークショップのことです。考えておくべきなのではないかと思うのですが、８月までにプロポーザルを行うということであれば、どうしてもその辺でやらなければいけない。なので、ぜひというのと、やはり対象をできるだけ広く、そこに手を挙げられるかどうかはご本人が決めることですけれども、広く募っていただきたいのですが、その辺、どのように考えておられるか、伺います。","respondent":"鈴木都市計画課長","answer":"ご指摘のとおり、ワークショップに代わるやり方を何か検討して、それをもってということもあると思うのですが、やはり対面でしっかり地域の方にいろいろな声を聞きたいという思いがありますので、そこは、スケジュールも全体的にずらしていくということになろうかと思います。","id":"exchange-027"}]},{"id":"topic-06","title":"「品川区中高層建築物等の建設に関する開発環境指導要綱」および「品川区ワンルーム形式等集合建築物に関する指導要綱」の改正","agenda":"「品川区中高層建築物等の建設に関する開発環境指導要綱」および「品川区ワンルーム形式等集合建築物に関する指導要綱」の改正","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"別紙１の一番右上の、まちづくりに寄与するエリアというところで、区や地域からの要望に合わせた機能として、「掲示板、シェアサイクルポート等」とありますけれども、ほかにはどのような、この「等」というのは、ほかに何があるのか教えてください。ですから、そこも増やすべきなのではないかという声も聞いているのですけれども、今回、それが盛り込まれていないということなのですが、これはなぜなのか。","respondent":"鈴木都市計画課長","answer":"今、中身については、検討を進めているところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"だから、それは検討していってほしいと思います。がらがらなのに維持費がかかって大変だというのは分かったのですけれども、あと、商店街の賑わいの連続性という意味も、確かに商店街で一律にセットバックみたいな、そういうのを機械的にやってしまうと何か寂しいみたいな、そういうのも理解できるのですけれども、それ以外のところの改正の理由、動機というのですか。","respondent":"鈴木都市計画課長","answer":"別紙１の３の景観に配慮したエリアとまちづくりに寄与するエリアについては、基本的にこういう分けを、景観の重点地区とそれ以外のまちづくりビジョン等が策定されている地区で、対象をこういう形で今分けておりますが、考え方は一緒です。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"最後、進め方なのですけれども、結構財産に関わる問題なので、重要な改正だと思うのですけれども、要綱なので、議決するものではないです。検討は以前から行われていたということで、資料にもありますけれども、今回、建設委員会に一回報告があって、約１０日後には改正がされると。こういう今の進め方だけだとなというふうに思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、改正にあたっては、内容を見直す検討にあたっては、いろいろ関係団体、建設業の団体ですとか、あるいは不動産の関係の方々とも内容について意見を交換しながら、これまで取りまとめを進めてまいりました。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"その周知期間のことを伺いたいと思うのですが、期間は６か月ですが、周知の方法というのはどのように考えられているのか、教えてください。","respondent":"鈴木都市計画課長","answer":"基本的には、区のホームページ、窓口等での周知を考えてあります。","id":"exchange-031"}]},{"id":"topic-07","title":"に戻りまして、(8)東京都高潮氾濫危険水位","agenda":"に戻りまして、(8)東京都高潮氾濫危険水位","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"区の対応のところなのですけれども、「高潮氾濫危険情報発表時の対応として、沿岸部全域の区民の避難態勢を改めて検討し」となっておりますが、検討スケジュールとか、今考えておられましたら、伺いたいと思います。","respondent":"中島防災課長","answer":"今回示されました設定水位を参考にしまして、以前、高潮による浸水想定図も東京都から示されておりますので、それらを勘案しまして、具体的なスケジュールはこれから設定するところですが、夏頃、出水期をめどに一定程度の方向性を定めまして。","id":"exchange-032"},{"speaker":"安藤委員","kind":"意見","question":"品川区全体が緑の点線の枠に入っているということですけれども、今後の区の今のところ、対応というところで、沿岸部全域の区民の避難態勢を改めて検討するとあるのですが、その対象となる地域について、現在、どういうところという想定をしているのか、もう少しお聞かせください。","respondent":"中島防災課長","answer":"つきましては、昨年、全戸配布させていただいた防災地図には、大きく目黒川の流域でありますとか、区の東側、そういうところの範囲が広範囲にわたりますので、そちらのほうを広範囲に検討する必要があると考えています。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。私が不勉強なのですが、高潮氾濫危険水位になったときに、水門というのは連動して閉めるとか、どういう状況になったら水門は閉めるのですか。不勉強ですみません。危険水位になって水門を閉めるのか、開けておくのか、ここら辺がよく分からないのです。今、台風というお話だったのだけれども、そこら辺のところがよく分からないので、教えてください。","respondent":"藤田防災まちづくり部長","answer":"通常の高潮注意報とか、その辺が出たときに際しても、その後の状況等を勘案しながら港湾局が対応しておりますので、おそらくそういう形になろうかと考えています。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"区でもこれぐらいだとわかったとき、連携をとって閉めようというのは、そういう区の判断で閉められるときもあるのか、それとも全て都の港湾局なのか。どうしてそういうことを言うかというと、手動は生きているのかと。都が閉めてくれなければ、ずっとそのまま開けっ放しなのか、そこら辺がよく分からなかったので、もう少し教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"長くなってしまってすいません。変な話、何でかといったら、グラウンドを広げられるではないかという話を何度もしたのだけれども、ここは水門があるから、その通路なので、この５ｍぐらいのところは広げられないという話を何度もしていたと思うのだけれども、そうすると、変わらずあれは水門用の通路として確保しなくてはならないという理解で変わっていないということでいいのですか。","respondent":"藤田防災まちづくり部長","answer":"基本的には、海岸保全区域等の管理のための通路ですので、何かあったときにはやはり入れなければいけないですから、その辺について、港湾局のほうと調整をする中で、可能な範囲での整備というのはできるかもしれませんけれども、基本的には、通常の車が入るとか。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4288#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":41228,"voices":140}},{"id":"r02-20200420-9","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"文教委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"令和２年度学級編制","agenda":"令和２年度学級編制","exchanges":[{"speaker":"横山委員","kind":"確認","question":"すみません、ちょっと簡単に。第二延山小学校の１年生と２年生で色が違うのですけれども、内容はほぼ同じということでよろしいのでしょうか。確認だけお願いします。","respondent":"篠田学務課長","answer":"２年生に関しましては、国の基準でいけば４０名ですけれども、都では加配を認めていてクラスを増やせる部分になっているのですが、それはできないという形で、取り扱いは若干違うということで色分けがされているです。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"確認","question":"２つあって、１つは、今の三木小学校や鈴ケ森小学校や小山小学校みたいに、いろいろな事情でクラス数がこうなったということを保護者の方にどれぐらいお伝えしているのかということです。校長先生のほうから説明されているのかもしれませんが、その辺りの確認です。東京都のほうで手当てをしていただいているのか、それとも区の独自の方なのか、そこだけ確認させてください。","respondent":"篠田学務課長","answer":"要は、お子さんの数が多くなっていることについては必ず言及はされているものというふうに考えております。それから、三木小学校の場合ですけれども、基本的には区の固有教員を充てるという前提で対応をしているものです。","id":"exchange-002"}]},{"id":"topic-02","title":"令和２年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","agenda":"令和２年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"なかなかお尋ねする機会がないので、すみません、年度の初めなので。区の固有教員の方で副校長先生になられた方がいらっしゃるのですが、校長先生になられるというところのいろいろなルールとか、そういうところの交渉といいますか、その辺りの進み具合はどのようになっているか。簡単で結構ですので、お願いします。","respondent":"工藤指導課長","answer":"お尋ねの区固有教員の副校長職から校長職への登用ですが、条例等の整備等が必要になる案件です。現在、私どものほうでは、文部科学省への問合せなどを行いながら、法的な根拠も含めまして、調査をしています。調査研究の上、そういう制度については設けるべく検討しています。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"そういった条例を設けるべく検討していただけるということなので、区の固有教員の方が校長先生になれる道筋をぜひお願いしたいと思います。品川区のためにも、お子さんたちにとっても重要なことだと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-03","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１つ目が、頼れるご家族などがおらず、ご両親が感染した際の児童・生徒への対応は、現在どのようになっていますでしょうか。２点目が、学校再開後の対応についてお伺いします。３点目、連合行事、運動会、学芸会、展覧会の中止、実施困難について、判断の根拠を確認させてください。６点目、これで最後です。毎年実施している家庭訪問の対応についての検討状況はいかがでしょうか。","respondent":"有馬庶務課長、矢部教育総合支援センター長、篠田学務課長","answer":"１点目の頼れる親がいない児童・生徒への対応です。今現在、そこについては大きな課題かというふうに思っています。４点目の個別のお子さんの対応ですけれども、適応指導教室においては、臨時休業に合わせて、今、休室中ですけれども、職員がそれぞれ何人か対応して。ただ、そういった見据えた形で国が方針を出してきましたので、今後どういう対応をしていくかについては、今、検討を進めているところです。先ほどの家庭訪問の件につきましては、やはり個別に必要のある家庭については、電話連絡もそうですが。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"今、校庭開放は実施されていないという状況だと思うのですけれども、校庭開放をして、校庭でお子さんたちを遊ばせる、公園というところに１か所に集中させないというようなことも１つとして考えられなくはないのかと思っているのですけれども、その点、ご見解はいかがでしょうか。","respondent":"有馬庶務課長","answer":"一歩も出るなというのはなかなか難しいかもしれないですけれども、それぞれが密にならないようなところは工夫して、各家庭でも対応していただくということも必要なのではないかというふうには思っているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"せめて公園で遊ぶにしても、今、ご指摘いただいているのは、マスクを全然していないでお子さんたちが集まって遊んでいるということで、それも非常に懸念しているところなのですけれども、基本、ご家庭で過ごすということを第一にお伝えいただくと同時に、どうしても公園とかで遊ぶ場合は、マスクの着用を義務づけるというか、励行してくださいというお願いを、ぜひ周知徹底。","respondent":"矢部教育総合支援センター長","answer":"先ほどの庶務課長の答弁に付け加えますと、外に出かけていくということはなかなか難しいのですが、家の前などは活動ができますので、縄跳びカードなどを配付していますから、その縄跳びで体力をつける、心の健康も維持しているということを聞いてあります。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった活用なども視野に入れながら、検討状況というか、どういうお考えで今後取り組もうとされているのかというところをお聞きしたいのが１点。そのような中で、そういう再開後の感染防止対策として検討しなければいけないことがきっとあるのだと思うのですけれども、そういうことについて、今どのようなお考えというか、状況なのか、教えていただければというところでお願いいたします。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"それ以外の学校については、一人ひとりにお配りしていないのですけれども、ｅライブラリという形の、要は、ネット環境の中にクラウドのほうでコンテンツがあって、子どもたちにＩＤを渡しまして。３点目の今後の見通しですけれども、教育総合支援センターとしましては、段階を追って、すぐに今までどおりの授業が再開されるとは考えておりませんので、例えば登校日が１週間に１回、または２日に１回は来るというような段階を追って。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"最初に簡単に確認させていただきたいのですが、今回、休校の延長ということで５月６日まで休校するということの判断の根拠といいますか、東京都から要請されたというところは説明されましたけれども、ほかに区独自で考えたこととか、考慮したことなどがあったら伺いたいと思います。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"休業の延長の件ですけれども、基本的には、３月末の段階では、まだ学校をやっていけるかどうかというところを検討していた状況がありました。校庭開放以外のところで、以前に取り組んでいたのは、学校図書館の開放とか、学校でできるところではそういうことをやっていましたけれども。我慢という一方で、私は、今できること、家でできることを考えるという意識改革も必要かと思っています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"実施していくべきだと私は思うのですけれども。実際、文京区では、１食５００円ということで３月から補助が実施されているということとか、豊島区でも３月からやっているということですので、品川区でもぜひ実施していただきたいのですが、いかがでしょうか。関連して、以前お聞きした給食業者への補償の問題です。それは今、どうなっているのか。補償してほしいのですが、いかがでしょうか。","respondent":"篠田学務課長","answer":"ですので、例えば、事業者のほうで３月分の食材で何か負担になるようなことがあったということがあれば、そちらの部分はきちんと補償ができるということで、手続き上の細かな説明も出てきましたので、そういったことで各事業者のほうで今連絡をとって。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"就学援助のところでは、ほかの区で実施されているところがあるので、これから研究するということなのかもしれませんが、そういった事例も調査していただいて、ぜひ実施できるようにしていただきたいと思います。もし何かあれば、ご答弁いただければと思います。業者に対して区として何か支援をしていくべきだと思うのですけれども、お考えを伺いたいと思います。","respondent":"篠田学務課長","answer":"ただ、その枠組みをどう考えていくかというのは、またこれは区としての全体の整理の中で、教育部門で出すべきなのか、それともほかの部分で出すべきなのか、出せるかどうかといった観点も含めて検討していかなければいけないのかと考えていますので、何らか対応できるかどうか。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"就学援助もぜひ全体のスキームもにらみながら検討して、実施していけるようにしていただきたいと思います。次の質問ですが、学校には非常勤職員の方、ＡＬＴですとか、ＳＳＳ、介助員や学習支援員という形でいらっしゃると思うのですけれども、そういった方たちが、今、どうなっていらっしゃるのか。休業されているとすれば、その休業への補償がされているのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"そこは都の教職員の勤務と何ら変わらないという状況があります。ただ、指導課におきまして、例えば、習熟度別学習指導助手は会計年度任用職員ではございませんので、ご指摘いただいているように、勤務するという実態がない場合にお支払いできないです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしなければそういった業種の方々もどんどん仕事を辞めなければならないことになっていく、そういうことにつながってくると思うので、そういった支援をぜひしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"国あるいは都からの何らかの指示等、また、何か対応があれば、それは検討していきたいというふうには考えてあります。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、ちょっと私の認識が違ったのか。そうすると、先ほど例示した介助員とか学習支援員とか、そういった方たちは、みんな会計年度任用職員ということでよろしいのですか。区が委託して頼んでいるところもありますね。学習支援員もそうだったか、学校司書とか、そういった方たちはどうなっていらっしゃるのですか。","respondent":"有馬庶務課長","answer":"例えば、委託をしている会社から介助員が来たりするというところの補償については、その会社のほうにその人が本来支払われるべきものを補償するということで、厚生労働省でそれを補填するという仕組みがあるので、それはその事業者がそちらのほうを通じて補填するという形が。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、教員の勤務の状況で、原則自宅勤務ということをお聞きしました。一方で、勤務なので、何か起きたときにはやはり通常の勤務と同じように事故等のことがありますので、その点についての先生方への徹底といいますか、もちろんそのようないろいろなことをやられる先生方はいらっしゃらないと思いますけれども、その点についても改めて確認させていただきたいと思います。","respondent":"工藤指導課長","answer":"朝と帰りといいますか、例えば８時１５分と５時という段階では必ず学校に連絡を入れるのですが、学校によっては、その途中、お昼休憩に入るところも１２時に一旦連絡を入れるなどの工夫をしながら。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"確認","question":"ありがとうございました。勤務の状況をどう確認するかということもお伺いしようと思ったのですが、今、いただきました。そうすると、恐らく副校長先生のところに連絡するということになると思うのですが、先生方の数が多いと、その対応はすごく大変だと思うのですが、そこだけ確認を。","respondent":"工藤指導課長","answer":"いつ、誰が、誰先生の報告を受けたということを、簡単な記録なのですけれども、文書で残すような形で工夫していますので、そういったことで勤務の実態を把握するということで行ってあります。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"１点だけ。入学式と始業式の実施方法について、徹底した感染対策がとられていたことに対して、ご尽力に感謝いたします。引き続き、感染拡大防止の優先順位をできる限り上げていただいた上で、現在の法整備ですとか、体制、いろいろな制約の中でいろいろとご検討いただいていると思うのですけれども、様々なケースを想定しながら対応を検討していただきたいのですが、一言だけお願いします。","respondent":"有馬庶務課長","answer":"ここも大事だと思っていますので、そこはしっかり。家庭のほうにも学校からもいろいろな、マスクをすることをやっていますし、学校が再開するにあたっても、できるだけ３密を避けることは徹底して、学校と連携しながらやっていきたいと思います。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"最初に、利用状況を聞こうと思ったのですが、認可保育園のほうは、今、９０％近くの方が自粛をされているということでしたので、正確に８０何％というものがあれば伺いたいと思います。区立園だけではなく私立園も含めて、保育園で感染者が出た中で、その後の経過観察といいますか、濃厚接触者の方も含めてどういう状況になっていらっしゃるのか、伺いたいと思います。","respondent":"立木保育課長、崎村子ども育成課長、若生保育支援課長","answer":"利用率ですけれども、本日の登園状況ですと、８８％の方が自粛ということで、１２％の園児が登園しているという状況になってあります。すまいるスクールの利用状況ですが、緊急事態宣言が４月７日に発令されまして、先ほど申し上げたような対応をしたのが４月９日からになります。私立の認可保育園等の状況ですけれども、４月に入ってから緊急事態宣言が出る前の８日までの段階での利用率に関しましては約７割程度で。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"経過観察の中では、新たに発症している方がいないということだったので、少し安心いたしました。利用も大体８割が自粛されていて、すまいるスクールが３１４人というのが何割かというのは伺えなかったのですが、全体がたしか結構いらっしゃったと思うので、３００人余というのは相当自粛されているのかなというふうな印象を受けました。いかがでしょうか。","respondent":"立木保育課長、崎村子ども育成課長","answer":"ただ、これはもしかしたら園のほうでの説明で、先ほど申し上げた保護者の方どちらかがご自宅にいらっしゃる場合には自粛をお願いしますという形で強くお願いしている部分がありますので。それが今回の緊急事態宣言を受けた対応ということで、例年に比べますと１０分の１程度の利用率になっているというところで把握しています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"休園と休業の補償のところで、事業者に対して協力の申し入れをしたということですが、事業者に協力してほしいということで出したということですね。分かりました。そういったことも含めて、世田谷区でしたか、ほかの自治体ではガイドラインをつくったということもあったと思うのですが、区でも対応のガイドラインを作っていくべきではないかというふうに思うのですけれども、いかがでしょうか。","respondent":"立木保育課長","answer":"そういったほかの区の事例等を参考にさせていただきまして、検討してまいりたいと思います。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"この認証保育所の補助を受けるにあたってのほかの要件というのはないのですね。利用者の方が申請をすれば日割り計算でそれを受けられるということで、それだけの単純な要件だけでいいのかというところを確認させていただきたいと思います。保育士などを含めて、従事者への心のケアも必要かというふうに思うのですけれども、そういった相談窓口の設置ですとか、対応はどうされているのか、伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"研修等でも保育士の資質の向上等の取組を行っているところですけれども、今回の新型コロナウイルス感染症の流行の中で、かなり心身の負担が大きくなっているということも推察していますので。そういったところをまず本課のほうでしっかりと園のサポートをしていくというところで、なるべく負担をかけないような形で、何かあれば、これは区民の皆様へのものと同じなのですが。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほど教育委員会にもお伺いしたのですけれども、頼れるご家族などがおらず、ご両親が感染した際のお子さんへの対応ですが、現在どのようになっていますでしょうか。利用率等は把握していらっしゃいますでしょうか。４点目、最後ですが、お子さんたちの状況の確認について、小学校等ですと電話での対応をしているというふうに聞いておりますけれども、保育園等ではいかがでしょうか。","respondent":"崎村子ども家庭支援センター長、立木保育課長、若生保育支援課長","answer":"私からは、１点目のご両親が感染した場合のお子様への対応というところでお答えします。区立幼稚園が、今回、４月８日に入園式を予定しておりましたけれども、やはり今回は、年齢も低いので集まるのは少し延ばそうということで、一応。区立幼稚園のお話がありましたので、私立幼稚園の入園式の状況につきましては、もう既に４月６日に行ったというようなところは数園ありますが、それ以外は。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"それぞれありがとうございました。ふだんお世話になっている先生のお声を聞いたりですとか、ちょっと保育園のほうから働きかけを何かしらしていただけると、そういったときにぽろっと、最近、うちの子はこのような様子なのだよね、などということをお話しになれるきっかけにもなるかと思いますので、何か具体的な実現可能な方法でご検討いただけたらというふうに要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"今のケアのお話と関連するかもしれないのですけれども、今、家庭内でのＤＶとか虐待とかが増えているということも聞いておりますが、そうしたご相談とかはあるのでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"子ども家庭支援センターのほうにも、やはりそういったご相談をいただくことはありますので、家庭内に特に子どもがいらっしゃらない場合でも我々の部署に入ってくる場合もありますので、そういった場合には、婦人相談。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたご相談は増えているということで、ただ、まだ深刻な状況には至っていないのかとは存じますけれども、今後また自粛期間が長引けば、そうした事態も考えられますので、そこはしっかりと対応、対策を練っていただきたいと考えております。その点、今後どのような対応というか、対策をお考えなのか、ご見解を伺います。","respondent":"崎村子ども家庭支援センター長","answer":"そういった中で気になるご家庭、気になるご相談があった場合には、子ども家庭支援センターのほうに必ずご連絡くださいといったことで、ここは連携を図りながら対応していくといったところで考えてあります。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=4998#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":34894,"voices":127}},{"id":"r02-20200420-5","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"総務委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"品川区長期基本計画の策定","agenda":"品川区長期基本計画の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"品川区長期基本計画ですけれども、策定時から問題点については指摘をし、変更を求めてまいりました。それは引き続き求めていきたいと思います。質問は１点だけなのですけれども、新型コロナウイルス感染症の関係でこの計画の前提が大きく変わる中、今年は初年度になるわけですが、財政収支の見通しも随分と変わってくると思うのです。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"今回策定しました長期基本計画につきましては、基本的に施策の大きな方向性とか考え方を示す計画としておりますので、今のところ大きく改定することは想定していなかったのですけれども、委員ご指摘のとおり、新型コロナウイルス感染症の関係もありますので。","id":"exchange-001"},{"speaker":"田中委員","kind":"確認","question":"長期基本計画の本体のほうなのですけれども、品川区立児童相談所の完成予想図と（仮称）品川区立環境学習交流施設の外観イメージが描かれているのですが、これはあくまでイメージ図ですよねというのを確認したくて、特に環境学習交流施設については近隣の方と話し合って進めていくと以前伺っているのですが、いかがでしょうか。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"長期基本計画の本体のほうに描かれている児童相談所や環境学習交流施設の外観ですが、あくまでイメージということで、より分かりやすく捉えていただくために載せているものでございまして、決定ではございません。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"ちなみに、１０２ページの環境学習交流施設が外観イメージで、７３ページの児童相談所が完成予想図なのですけれども、その違いを確認させていただければと思います。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"児童相談所の完成予想図は、設計を一定やっているというところで、完成の予想については議会でもご説明しているとおりですが、ある程度内容が分かる部分が大きいというところで、完成予想図としているところでございまして、環境学習交流施設に関しては。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"１年後、２年後にこの長期基本計画を見る人がいるわけですよね。国の非常事態ではないですか。別に質問ではなくて、もし対応していただければありがたいなと。我々も区民に、こういうふうにしっかりやりましたと、緊急事態に対しても品川区は瞬時に対応していく、そういう自治体ですということを誇りを持って言えるので、できたらお願いしたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"せっかくこうやって作っているわけですから、総合実施計画が出てくるというのは分かってはいるのですけれども、より区民の人たちに理解をしていただいて、共にやっていかなければいけないというようなことを知っていただくという機会は喫緊に作っていかなければいけないと思うのですが、その方向性を教えてください。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"２点目のご質問の概要版ですが、こちらに関しては、まさに長期基本計画の本体の概要版ということで圧縮して作っている部分もありますので、短時間で概要を把握するのに非常に分かりやすいものとなっていますので、こちらに関しましても、例えば短い時間であったり。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"状況も非常に変わってくる可能性もあるので、そういう意味だと、より区民の方々の状況に応じた政策というか、長期基本計画でなければならないと思いますので、１年かけてもいいぐらいの検討をぜひお願いしたいと思いますが、いかがでしょうか。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"ワークショップや勉強会等というご提案をいただきました。私どももさまざまな機会を捉えて内容の周知は全力で行っていきたいと考えておりますので、どういった形ができるのかというのを幅広く考えながら進めていきたいと考えています。","id":"exchange-006"}]},{"id":"topic-02","title":"令和２年度 組織改正","agenda":"令和２年度 組織改正","exchanges":[{"speaker":"田中委員","kind":"質問","question":"子ども未来部の放課後サポート担当の新設なのですけれども、そこは何か課題があって新設されたと思うのですが、どのような課題から新設されたのかということが１点。そして、福祉部の障害者施策推進担当の名称変更の趣旨を知りたいです。それは今も機能しているのかということと、これからも変わらず、どんな障害の方でも相談支援を受けられる体制となっているのかということを伺いたいです。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"２点目の障害者福祉課の関係ですが、まず、委員からご指摘のありましたこれまでの相談機能はどうなるのかというところは、当然そのまま維持をして、維持をするだけではなく、施設整備は今後も急がれる課題だと考えていますが、今まで施設整備の担当がなかったので。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"子ども未来部の放課後サポート担当についてなのですけれども、組織改正の主な理由を読んだときに、教育委員会やＰＴＡとの調整となったら、教育委員会でのことなのか、すまいるスクール関係なのかとかが見えてこなくて、どういった放課後サポート担当という係なのかなという、具体的なものがちょっと分からなくて、そこら辺をもう１回教えていただけますか。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"説明が足りなくて申し訳ございません。委員ご指摘のとおり、すまいるスクールを含めて、総合的に放課後サポートをどういった形でやっていけばいいのかという検討をしています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"意見と質問をしたいと思います。意見ですけれども、人権・同和対策担当（主査）ということですが、同和行政はもうやめるべきだと思います。その狙いは何かを伺いたいと思います。区の体制を見ましても、再開発を進めるために、副区長の設置をし、今回、部長まで設置をし、この再開発推進の体制というのは一体何を狙ったものなのか、質問したいと思います。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"こちらに書かれているとおり、主に現在、都市開発課で所掌している事務について、再開発等に関して、その動き等もありますので、その辺に関して推進していくといいますか、担っていくです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"総合調整が必要だということですが、つまりは、今進められている再開発の事業数が増えているからということなのか、業務が複雑化しているからということなのか、改めて狙いは何か。こうした開発推進の区政は、私は改めるべきだと思います。狙いだけ、もう一度伺います。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"都市整備推進担当の設置の狙いとまちの動きというご質問だと思いますが、まちづくり立体化担当課長というのが存在していますが、鉄道の立体化等の動きも出てきているというところもありまして。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認させてください。庁舎計画担当が新設でできるわけですけれども、審議会もできて、それで新庁舎についてはいろいろと具体的に検討が始まるのだろうと思うのですが、要はここが事務局という形でいろいろ準備するのだろうと思うのです。情報収集がかなり必要になってくるのではないかなと思うのですけれども、そういう機能も果たす部署になりますという理解でよろしいですか。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"庁舎計画担当課長の業務の関係ですが、委員ご指摘のとおり、審議会のほうも所管をしますし、当然、庁舎の建て替えにかかわる検討をしますので、情報収集も行っていくというところです。明日の行財政改革特別委員会で、庁舎のあり方に関することが出るところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"審議会だけがというわけではなくて、もちろん審議会も１つの案という形になるかと思いますけれども、しっかり事務局の中でも、常に業務をされている方々の意見をまとめるということでも非常に有用なポジションになるのかなと期待を込めておりますので、ぜひとも自由な発想でやっていただきたいと思います。よろしくお願いします。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"(3)新型コロナウイルス感染症の対応","agenda":"(3)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"田中委員","kind":"確認","question":"今、ホームページを確認したら、感染症関連情報の中にようやく生活にお困りの方への欄ができていたのでよかったなと思ったのですけれども、区立保育園だったり、保育園の休園に関しての情報発信の部分で、名前の公表がない理由が、特定につながるかもといったそういう話もすごく分かるのですけれども、公表しないことによって、ほかの園が噂をされてしまって。","respondent":"立川総務課長","answer":"プレス発表におきまして具体的に保育園名を公表するかしないかですが、メリット・デメリット双方あると認識しています。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ここを開けば出てくるというのは分かるのですけれども、探している方が一目で分かるような記載があるといいなと思うので、そこは要望させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"それだけに、区の姿勢が問われていると思います。質問は、３点伺いたいと思います。１点目は、国に対して自粛は補償とセットで行うこと、１０万円の給付も１回限りでなく連続して実施することを、品川区として国に要望していただきたいと思いますが、いかがでしょうか。以上、３点について、本部でぜひとも検討していただきたいと思いますが、いかがでしょうか。","respondent":"立川総務課長","answer":"国に対して要望するかですが、区としましては要望する考えはございません。ただ、東京都に対してのさまざまな要望はこれまでも区長会を通じて実施してきたところですので、そういった東京都からの支援について、区長会を通しての要望はしていきたいと考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"国には要望しないが区長会として要望しているというお話だったのでしょうか。２３区の区長会で、何を誰に求めているのか、その中身も伺いたいと思います。最後に併せて、職員の在宅勤務について、どういう状況、どのようにやっているのかということを伺いたいです。出退勤の確認とか。在宅勤務は始まったばかりですが、現在の状況について報告していただきたいと思います。","respondent":"立川総務課長、榎本総務部長","answer":"例えば東京都に対してですけれども、地域医療の施策につきましては東京都が推し進めているところですので、地域医療体制の支援についての東京都の支援を充実してほしい、そういった内容について区長会を通して要望したりしています。なので、できれば書類関係、個人情報がないものでマニュアル等をきちんと読み返して準備するとか、そういうような形が一番多くなっているところです。","id":"exchange-016"},{"speaker":"小芝委員","kind":"質問・要望","question":"３月初旬ぐらいから、地域の特に飲食店を中心とした事業主の方からの相談を受けています。それはどんな相談かといいますと、支援制度についてで、先般、４月１１日の広報しながわに、区の対策として経営相談と経営変化対策資金２０２０の制度が載っていたのですけれども、実際にはそれだけではないと思うのです。そういった方々にも等しく情報を提供していただきたいと思いますが、ご見解を教えてください。","respondent":"立川総務課長","answer":"広報紙で毎回新型コロナウイルス感染症に関する記事を掲載させていただいているところですけれども、やはり中小企業者向け等の記事につきましては、これからも分かりやすく掲載していくことが必要かなと考えておりますので。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"指摘していただいて。自転車で行くのですか。近所のお医者さんに、そういうときはどうするのですかと聞いたら、救急車を呼びますというのです。テレワークをして感染予防はいいのですけれども、保健所は品川区に設置しているわけですから、庁舎全体でカバーしていかなければいけない部分もあるのではないかと思うのですが、その対応については何か考えられていることがあるのか、お聞きしたいと思います。","respondent":"立川総務課長","answer":"区民の方のご相談の場合なのですけれども、今回の４月１７日の広報しながわ臨時号でもお知らせしていますが、まず、新型コロナウイルス感染症の予防や心配な症状、対応などについての相談ということでは、午前９時から午後５時までではありますけれども。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、品川区が整理をしてあげてほしいなと。もちろんこれからいろいろ変わってくると思うので、フィックスした形は難しい部分があるかもしれないですが、今の状況だと、仮に自分が感染したときに、どういう行動を取ったらいいかというのが瞬時に分からないというのが正直なところなので、そういう迷いがないような、交通整理をぜひ区でしていただきたいと思いますが、いかがでしょうか。","respondent":"立川総務課長","answer":"区民の方への分かりやすい広報ということで、ただいまご指摘いただいた内容について、どういったふうに伝えられるか、伝えていく必要があるかということは、広報所管とも協議いたしまして、実施してまいりたいと考えているところです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"１０万円支給というのがありますが、それは、どこの所管が担当という話がこれから出てくるのでしょうか。","respondent":"立川総務課長","answer":"現在、検討を進めているところです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"そうすると、東京都でできないのですかと思うと、またさらに私の頭は飛躍して、日本は工業立国と言われているのに、いざとなったらマスクも作れない、防護服も作れない、フェイスシールドも作れない、エタノールもなかなか間に合わない。品川区も今、事業を進めていると思うのですが、これは結局止まってしまうから、当面、予定は全く立たないということなのでしょうか。","respondent":"榎本総務部長","answer":"要は学校の休校が長くなっていて、夏休み期間が今後どうなるかということになると、今から計画を立てないと、夏休み中、工事ができないということで、その辺についても企業側と十分に相談しながら、どういうふうに契約等が進められるかというのは検討しています。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"先程もちょっとご意見があったのですが、分かりやすい情報発信というところで、ホームページでも、生活でお困りの方は「区民の皆さまへ」のところで入っていますし、新型コロナウイルス感染症の融資あっ旋等も「事業者の皆さまへ」と入っているのですが、生活でお困りの方は本当に困っていて、今まさに仕事がなくなってしまって家賃を払うのも大変だというところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"各委員も当然、あえて抑えていらっしゃって、いろいろな要望とか、また、所管外のこともあるので、そのあたりもとなると多分無尽蔵になるので、また別の機会になるかと思うのですが、その中で、この所管というところも含めた確認を２点させていただきたいのですけれども、先程来出ている新型コロナウイルス感染症の広報しながわ臨時号の発行についてなのですが、これの配布方法はどういう形でされたのか。","respondent":"立川総務課長","answer":"駅等にラックが設置してありますので、そちらにも置いております。出先の施設についても、ある一定数、置いているです。新聞等をとっていない方は、広報広聴課のほうに申し込みいただきますと、直接郵送でお配りできる仕組みもありますので、そういった方法で広報しています。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"どうやればいいかというフローも当然必要でしょうし、そうしたことが分かる情報が確実に届く仕組みを、当然感染拡大防止を配慮した中で作っていただきたいというところなのです。これは要望にしたいと思います。もう１個が、先週とこの週末、報道で全国から私たちのところにも、品川区、どうしてしまったのだ、戸越銀座商店街、武蔵小山商店街、なぜかお叱りの声をいただくのです。","respondent":"立川総務課長","answer":"防災行政無線ですけれども、こちらは防災課所管なのですが、総務課のほうで１日３回やるとか、誰の声でやるか、今は機械音声でやっているところですけれども、実際、濱野区長の声で流すかどうかは別としまして、より分かりやすい。","id":"exchange-024"}]},{"id":"topic-04","title":"人権に関わる意識調査結果","agenda":"人権に関わる意識調査結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"考えると、自分のスマホと家庭にあるパソコンとインターネットカフェと、自分１人で何回もできることになってしまうのかなとちょっと疑問に思ったので、どういうふうに対策されているかということと、やはり若い世代の回答が多いということで、これ自身は必要な取組みだと考えていますので、今後も工夫してみていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"郵送で送らせていただきました用紙に、インターネットで回答する場合のあなたの番号というものを付けておりまして、それをホームページ上で入力すると、その人のページに入っていくと。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"今後の予定の部分で、庁内等に概要版および報告書を配付ということは、各所管、関わりのあるところでは、このアンケート結果がきちんと活かされるようになるのかというところをまず確認させていただきたいのと、このアンケートを見た性的マイノリティの方からは、質問内容が当事者としてちょっと傷付くものがあったといった意見もありました。そこに関してもご意見いただけたらと思います。","respondent":"島袋人権啓発課長","answer":"アンケート結果が他課との連携の事業で活かされるのかということですが、こちらに関しては、活かしていくように私たちも働きかけていく予定です。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"性的マイノリティの部分です。これからたしか性的マイノリティの方たちの交流会とかがあったと思うので、そういった場面でも、質問がどういったものになれば当事者の方たちも納得できる質問になるかといったことを聞いてもらって、作り上げていただければなと思います。","respondent":"島袋人権啓発課長","answer":"今回初めて開く予定でおります「みんなのひろば」というところですが、さまざまな団体の方から、１人ではなく、複数の方に来ていただきながら、また、区民以外の方、区内では来れないから近くの場所に行きたいという方たちのお声を聞きながら、どういったことにお困りなのかとか。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"質問内容を見ていないので、分からない状態で話をする場合があるかと思いますが、非常に気になったのが、１ページ目の「『人権尊重都市品川宣言』の認知状況」がかなり低いなということと、それから人権３法を知っているか知らないかという話なのですけれども、そもそも法律の名前が難しいということではないのかなと思うのです。例えばこれは用語の説明はされているのでしょうか。","respondent":"島袋人権啓発課長","answer":"今回皆様方にお示ししましたのは要約版ですので、本編の報告書のほうにはさまざまな用語解説、あるいは送らせていただいた回答用紙にも簡単な用語説明は付けて渡させていただいたところです。","id":"exchange-028"},{"speaker":"西本委員","kind":"意見","question":"いろいろ説明文があった上での回答だということはありますが、その説明文すら分からない人が多くなってきているのではないかという危惧があるわけです。言葉の意味合い、何のためにこれがあるのかというところのそもそも論からのスタートにしないといけないのかなと強く思いましたので、今後、ご検討いただければなという意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29349,"voices":94}},{"id":"r02-20200421-14","meetingId":"r02-cm04","date":"2020年4月21日","dateIso":"2020-04-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査の(1)庁舎のあり方に関すること","agenda":"特定事件調査の(1)庁舎のあり方に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今、説明にもあったのですけれども、庁舎機能検討委員会にあたって、庁内検討でまとめた内容をたたき台にして議論するということだったのですけれども、その庁内検討の内容としては、前回１２月の当委員会で示されたような様々な分野でのプロジェクトチームの検討、先行自治体の事例研究、民間オフィスの機能研究などでしたけれども、この庁内検討の内容というのは、当委員会には報告がないのでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"こちらは３月に全庁的にキックオフしまして、４月には人選等を進めているところではありますが、こちらも新型コロナウイルス感染症の関係がございまして、５月末に一定の検討案を取りまとめるよう依頼していたところですが、現状。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それですと、当委員会への報告というのは、次回も難しいということなのか、伺いたいと思います。それと、もし今の段階で報告できる範囲でありましたら、どんな検討になっているのかというのを教えていただければと思います。","respondent":"濱中庁舎計画担当課長","answer":"庁内検討ＰＴの進捗をお尋ねいただいたところですが、現状、ＰＴも新型コロナウイルス感染症の関係で、なかなか動いていないところでございまして、４月におきましては、まず人選と、各メンバーにおける課題の洗い出し等を行っているところでございまして、今後、収束次第、５月。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"５月２０日に行財政改革特別委員会が予定されておりますが、たたき台にするということですので、適切に議会にも、庁内での検討内容というのをご報告いただく必要があると思うのです。そこら辺を、ぜひよろしくお願いしたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"６月末で庁内ＰＴの検討案がまとまり次第、また事務局でもそちらをまとめて、庁舎機能検討委員会に上げていくという段階ですので、そちらから様々なタイミングのところで皆様方に説明する、またお伝えしていくところもあるかなと思うのですが、今はまだ検討案を。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"７団体の方でも、障害者七団体協議会の代表の方だけでなくて、障害といってもいろいろな障害、目の不自由な方や、耳の不自由な方や、あるいは体の不自由な方や、いろいろいらして、障害に応じた様々な条件なり要望なりがあると思うので、せっかくこの先５０年を見込んで庁舎の機能を検討していく以上、そういう具体的なものが出てくることが期待されるようなことで。","respondent":"濱中庁舎計画担当課長","answer":"庁内検討ＰＴの中には、福祉のワンストップ窓口というところを、福祉に関しても頑張っているＰＴもありますので、そういった中で、障害者の方の意見が出てくるものかと考えていますが、そちらにつきましても庁舎機能検討委員会で議論していただく予定ではあります。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう中で、障害者の方だけではないのですけれども、様々な要望、要求を酌み取る。それから、そこで直接にいろいろな立場の方が議論していただくことに、非常に意義があると思うのです。こういう構成だと、それが十分に活かされていないように私は思うのですけれども、そこのところをもう少しお考えになって、このメンバーに反映していただきたいと思うのですが、ご再考願うわけにはいかないのでしょうか。","respondent":"榎本総務部長","answer":"意見を集約する段階を、どの段階でやるかということなのですけれども、庁舎機能検討委員会というレベルですと、なかなか全部の意見をそこで吸い上げようというのは難しいわけですから、実際のやり方として、何らかのワークショップ方式で行うなどをしないと。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"１点、確認なのですが、区民公募の締切が１か月先に延期をされた。このことによって、スケジュールは６月から現状説明となっているのですが、公募が１か月延びたことによって、３月の終了までにこれをぎゅっと詰めた日程になったのか。それとも、１か月遅れても余裕のあるスケジュールを組んでいたのか、新型コロナウイルス感染症に関連して、このスケジュールはどのように組まれたものなのでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"それに伴いまして、公募区民の募集も１か月程度、後ろ倒しにして、幅広い区民の方にご応募いただく機会を設けたです。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"このスケジュール感で、３月までにすべての議論をし尽くせる日程で大丈夫なのですか、ということです。そこはどうなのでしょうか。大丈夫なのですか。","respondent":"濱中庁舎計画担当課長","answer":"当初、５月を第１回に、最後の第５回を２月に想定しておりましたので、全体スケジュールを１か月後ろ倒しにして、今の段階では収まるものと見ております。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。今の時点で、本当に６月が行われるかどうかというところも、まだ分からない状況ですが、庁舎のこのことについては、しっかりと議論をする時間が必要だと思うので、お尻ありきではなく、たとえ延びてでも、これをきちんと議論し尽くして進めていくということが大事なのですが、その辺りのお考えはどうなのでしょうか。","respondent":"榎本総務部長","answer":"新型コロナウイルス感染症の関係がどうなるか分かりませんけれども、例えば６月が開催できないとなれば、その分は年度を越えて、全体のスケジュール感を考えなければいけないかなと、現時点では思っています。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１２月の行財政改革特別委員会での区からの資料でも、求められる庁舎機能というところでは、ユニバーサルデザインへの配慮、また防災拠点機能を強化した庁舎、環境に配慮した庁舎、今後、長く使われる庁舎、こういったところが挙げられているので、この３人の方もいろいろな知識や経験をおもちだと思うのですけれども、さらに広げた専門家が必要なのではないかと感じました。","respondent":"濱中庁舎計画担当課長","answer":"ご提案いただきました学識経験者の人数ですが、庁舎機能検討委員会ではこちら３名の方を挙げさせていただいておりまして、次の基本構想を策定する段階におきましては、専門的な手法をもった方々の参加を検討してまいります。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"基本構想の部分で専門家を入れてくれるということなのですけれども、機能検討のところから話に加わってもらう、状況を把握してもらうということが必要なのではないかと思いますし、先ほどもありましたけれども、５０年先を見込んだ庁舎、ずっと使われる庁舎を建てていくというところですので、ぜひ幅広い専門家の皆さんの意見を入れた形で進めていただきたいと、改めて要望したいのです。","respondent":"濱中庁舎計画担当課長、榎本総務部長","answer":"１点目、専門家のことに関しましては、基本構想の策定段階で、庁舎機能検討委員会の取りまとめをもとに議論をしていきたいと考えています。補足ですけれども、検討委員会とか、こういう審議会関係の男女比率につきましては、男女共同参画のための品川区行動計画の中では４割という目標とさせていただいています。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、公募区民５名とあって、もっと増やしていただきたいという思いはあるのですが、それは置いておいて、資料にも、先ほど説明にもありましたけれども、公募時期も５月１４日が締切と延びたということです。当初、４月１６日締切ということで進めていたと思うのですけれども、ここまでに申し込んでこられた区民の方というのはどれぐらいいらっしゃるのか、分かれば教えていただきたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"公募区民の応募状況ですが、５名を超える応募があるといったところです。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"何人ぐらいかというのは分からないということなのか、そこを伺いたいです。その報告書に現庁舎の現状、課題、そして新庁舎の基本条件の項目があると思うのですけれども、いろいろ公表できないと区はおっしゃっているのですが、そうすると、この部分は公表されることになっていたということでいいでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"公募区民ですが、５名程度を超えるところで、今現在１０名程度ございまして、申込書配付のみのご連絡をしています。検討報告書ですが、こちらは所管ではないので、お答えを控えさせていただければと思います。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちは黒塗りのところも取り上げて、問題だということは言ってきたのですけれども、庁舎の機能検討のところで、現庁舎の課題や新庁舎の基本条件というのは、当然議論の中に入ってくるでしょうし、それを税金をかけて検討されているわけです。そうしてくると、しっかり税金をかけて検討したものが、ここでも出されてくるということでしょうか、ということです。","respondent":"濱中庁舎計画担当課長","answer":"庁舎機能検討委員会ですが、そちらには現状の課題等を整理しまして、お示ししていくところと考えています。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"それが出されるのは当然なのですけれども、既に検討してきた報告書には現庁舎の課題と新庁舎の基本条件というのが、黒塗りですけれども出ているわけですから、それが出されるということですか、ということです。","respondent":"榎本総務部長","answer":"今回、この庁舎機能検討委員会の中では、そういうものを含めて、ここからスタートするという形だと思っていますので、要は、一応、広町地区が候補地になっていますので、その候補地の中の条件として、まず機能としてどんなものを集めたほうがいいのか。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"意見","question":"そうなのですね。庁舎のことで、課題も基本条件も出ていたので、そこは共有されているものだとばかり思っておりました。そうしたら今後、そういう中身も含めて、きっと議論、検討されるのでしょうけれども。庁舎機能検討委員会には議員の皆さんも入るということですので、課題、そして新庁舎への基本条件というか、あり方というのは、引き続き十分議論していきたいと、私も期待したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど構成員の話で、障害者の話がありましたけれども、特に障害者施策というのは当事者が参加して作成するべきだというのは、今、非常に大きな大事な流れですし、ましてや求められる庁舎機能のところにユニバーサルデザイン等も入っているわけですから、今回の庁舎機能検討委員会という段階で、どれだけ入れるかというのはあるかもしれないのですけれども。","respondent":"濱中庁舎計画担当課長","answer":"区民意見の聴取ですが、庁舎機能検討委員会で区民意見の具体的な聴取方法や時期を検討していくことになると想定しております。他自治体の事例や、検討支援業務委託事業者のノウハウ等を活用しながら、区民意見の聴取方法を検討してまいりたいと思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"そういう意見の取り方も、庁舎機能検討委員会の中で検討してもらうということですか。なるほど。それは一つの考え方でしょうけれども、私としては、わざわざ集まってもらうわけですから、早い段階からきちんと庁舎機能検討委員会の検討の材料にすべきだと思って、早くアンケートをやってほしいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"調べていないのですか。知らないのですか。知っていれば教えてほしい。知らなければ知らないと。","respondent":"濱中庁舎計画担当課長","answer":"こちらにつきましては所管外ですので、答えられないところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"区が進めようという検討の前提条件なわけです。所管外だからといって、何かつかんでいるかどうかもお答えがなければおかしいと思うので、そこら辺だけ答えてください。","respondent":"榎本総務部長","answer":"まだ協議が続いている最中ですので、その協議の結果については、まだ所管からの報告を受けていないという段階です。","id":"exchange-019"},{"speaker":"安藤委員","kind":"確認","question":"分かりました。そのようにお答えいただければ、納得するわけですから、お願いします。庁舎機能検討委員会というのは、このＤ案を前提にする、その枠組みの中での議論を行う場なのでしょうか。先ほど、部長の答弁の中でも、そういうものだという感じもあったように聞こえたのですけれども、そこを確認したいのです。今のＤ案というのを前提にした議論を行う場所なのかどうか、伺います。","respondent":"榎本総務部長","answer":"ただ、機能としての検討なので、広町地区よりももっといい候補地が出てくるのであれば、その候補地を前提に考えるということも、一つの案だと。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民の意見をまだほとんど聴いていない段階で、これまで密室で検討してきて、先ほど言ったようなところの形まで区庁舎のあり方を決定づけるということは、区民参加のかけらもないのではないかと私は思いますので、これを前提にして議論をするべきではない、そういう会議体にはしてほしくないと思いますし、Ｄ案を前提にした検討をするという考えがもしあるのであれば。","respondent":"榎本総務部長","answer":"そうすると、なかなか庁舎の改築の検討自体が進まなくなってしまうのかなと思うのですけれども。何か具体的に想定をして、そこで機能も含めて全体像をやっていくと。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"意見ですけれども、私は今の答弁は極論だと思うのです。１６年もつとはいっても、確かに今ぐらいから区民をきちんと巻き込んで、５０年、１００年という建物ですから、検討を始めていくということが、私はあることだと思います。ただ、先ほど言ったように問題なのは、大方、区庁舎の形というのを決めてしまうと。ぜひそのことを受け止めて、検討を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、お話がありましたけれども、今回は品川区庁舎機能検討委員会の設置についてです。こういう皆さんの代表が集まって、そこでこれから検討していこうということですから、これはこれで進めていかないと、何も始まりませんので、私は粛々とやっていただきたいと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-02","title":"区有施設・公有地等活用に関すること","agenda":"区有施設・公有地等活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"事業説明会でありますけれども、いつ頃を予定しているのか、伺います。前回の報告は８月だったと思いますけれども、その後に行われた住民説明会の参加人数や、住民から出た主な意見について教えていただきたいと思います。参加者を募る方法ですとか、対象ですとか、時期はいつ頃なのかとか、これは事業説明会が行われて、設計する前にこういうことを行うという理解でよろしいですか。伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"１点目の今後の住民説明会ですが、防災関係の所管課と障害者福祉の所管課ができるだけ早めに地域に入りたいというところなのですが、今般の新型コロナウイルス感染症の事情がありますので、今後どういう見込みになるか分からないのですが、難しいかもしれないのですけれども。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ありがとうございました。説明会でも地域の方から要望を出されていたということですが、時間も経っていますので、現在の状況ですとか、あるいは説明会で出された質問や意見に対する区の考えなど、ニュースという形でもいいので、どうなったのかを知らせてほしいという声が出ています。ぜひそちらには配慮して実施していただきたいのですけれども、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"前段のご質問は、説明してから時間が経っているところですので、先ほどご答弁したとおり、各所管課もなるべく早く地域に入りたいというところもありますので、地域の方々に適切に情報を流すため、所管課を通じて対応していきたいと思います。","id":"exchange-025"}]},{"id":"topic-03","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"区組織と関連団体に関することと同様に、この件についても賛成し、そのほかの修正点もないと考えますので、この案文でお願いしたいと思います。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問・要望","question":"ちょっとだけ、細かい点なのですけれども、(3)のホームドアのことなのですが、前回２月２７日の行財政改革特別委員会で、固定式ホーム柵が東急池上線に設置されておりますが、その点に関して私は質問して、鈴木都市計画課長からご答弁いただいて、固定式ホーム柵は設置されているけれども、可動式ホームドアに替えるように、区としても要望を出しているし、それから、東京都が全体として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"意見","question":"(1)の１行目で「『鉄道駅バリアフリーに関する優先整備の考え方』に基づき、エレベーターなどワンルートだけでなく、駅の状況に応じて」ということで、いろいろなルートがあるとは思うのですけれども、エレベーターを強調したかっただけなのです。意見はそれだけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"今の石田ちひろ委員の意見なのですけれども、新馬場駅の南口等を想定されているということだと思うのですが、例えば、「エレベーターなどもワンルートだけではなく」とか、そういうことではないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"エレベーターだけではないということですか。１本のエレベーターでなくて２本造ってもという、エレベーターを造ってという意味ではないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781582?Template=document&Id=6086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":16904,"voices":93}},{"id":"r02-20200422-18","meetingId":"r02-cm04","date":"2020年4月22日","dateIso":"2020-04-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時１３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"東京２０２０大会の延期","agenda":"東京２０２０大会の延期","exchanges":[{"speaker":"つる委員","kind":"確認","question":"細かいところはこれからと理解はしていますが、東京都の取組みとして品川区も関係した学校連携観戦プログラムに関してですが、今年、夏に開催していれば、幼稚園、保育園等の年長から高校３年生までということが最初でしたけれども、そういうところで見ると、プラスの対応というところになるのかなと思うのですが、例えば今年の年中が来年だと年長になるのですけれども、こういうケースの場合。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"学校連携プログラムについての対象者ですが、今のところまだ東京都等から連絡は入っておりません。通常考えると、今の年中が上がったところなのかと思いますが、詳しいところはまだ来ておりませんので、これからの対応です。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/706411?Template=document&Id=6572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":4115,"voices":27}},{"id":"r02-20200428-10","meetingId":"r02-cm04","date":"2020年4月28日","dateIso":"2020-04-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5356#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10705,"voices":58}},{"id":"r02-20200511-10","meetingId":"r02-cm05","date":"2020年5月11日","dateIso":"2020-05-11","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"本会議・委員会の運営","agenda":"本会議・委員会の運営","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、本会議場の傍聴者の人数が２０名ということですけれども、今で７０名か６０名くらいいたと思いますけれども、もう少し増やせるのではないかなと、意見だけ述べておきたいと思います。それともう１点、今、５点にわたって説明がありましたが、文書で後ほどというか配っていただきたいと思いますので、御対応よろしくお願いいたします。","respondent":"米田区議会事務局長","answer":"今、議長のほうから御発言ありましたことが間違いなく各議員に伝わるように、文書もしくはメモ等で各会派のほうにきちんと周知をさせていただきたいと思います。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":4269,"voices":21}},{"id":"r02-20200512-6","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"区民委員会","time":"午前１０時１１分～午前１１時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","topics":[{"id":"topic-01","title":"第３３号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第３３号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今回の条例改正案を拝見しますと、下の表に明らかですけれども、３点にわたって対象者の範囲が拡大されておりまして、融資条件の緩和・拡大という意味では、私も要望してまいりましたので、非常に評価はいたしたいと思います。この３つの要件拡大はどれも重要だと思います。ですので、それぞれ拡大した理由をご説明いただければと思います。お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"据置期間１２カ月から３６カ月にさせていただいたというところです。現状、５年で５００万円の貸付をさせていただいているのですが、なかなか、今回のコロナウイルス長期化で、いわゆる通常の状態に戻るのがなかなか時間がかかるだろうというような見込みがあります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"ごめんなさい。私が３つと言いましたのは、対象者が３つ、中小企業者、それから、引き続き１年以上同一事業を営んでいる方、これを１年以内というのを廃止されましたよね。その最初の２つのことは今ご説明いただきましたので、その３つ目の売り上げ減少、これを条件にしなくなった、これも画期的なことだと思うのですよ。重要なことだと思うので、その点について、さらにご説明いただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、明らかに４月以降に落ち込むことがわかっているというような状況がありましたので、今回、５％以上減少というのを廃止させていただきまして、今後もう苦しくなるのがわかっているというところに関しましては、積極的に融資するというところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"今、理由を伺いまして、やはりとても重要な改正だと思います。それからもう１つ、これは念のための質問ですけれども、これは区独自の事業で、別に国や都からの後からの補助金を見込んだりしているような事業では、もちろんないですよね。","respondent":"遠藤商業・ものづくり課長","answer":"こちら、区の単独の事業になっておりますので、特別補助金等はついていないというところです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"前にも伺いましたけれども、融資あっ旋の実態ということで、件数や何かを少しお伺いしたいのですけれども、融資の相談に来ている方の相談の件数、それから、実際にあっ旋された件数、それから、結果として実行された件数、それとともに、相談を申し込まれてから相談までかかっている期間、あるいは、さらに申し込んでから融資までにかかった期間が今どうなっているかということを伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"そちらを持って銀行に行くというような話になろうかと思いますので、銀行では２、３週間というのが引き続きかかっているというような形で聞いております。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"今まで５００万円という枠で融資を受けていた方たちも、この２,０００万円に枠が広がったわけですから、広がりましたということをどういう形でお知らせをするのかということと、今までご相談に来た方が、５カ月の売り上げが前年より下がっていないと、というので断られた方もいるわけですよね。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな私どもから提供するような情報がありますので、個別に、また別の、前回、雇用の関係などで配らせていただいた、各事業所にチラシをたくさんつけて配らせていただいたケースがあったのですが、それをもう一度行おうかというところで検討させていただいているところです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、そこは徹底的に、融資を受ける、受けないはご本人の考えですけれども、情報だけは、いや、知らなかったとならないようにしていかないといけないと思うので、そこをもう１回、徹底的に、情報弱者をつくらないようにしていくということを教えていただきたいのと、あと、もちろん、０.２％と言っても、金融機関が０.２％ではなくて、金融機関のところの差は、区は税金でというのはわかっています。","respondent":"遠藤商業・ものづくり課長","answer":"０.２％の部分ですけれども、私どもで、利息部分に加えまして、今回、期限が長くなる、あるいは据置期間が長くなるということで、こちらにつきましても、引き続き要する費用の全額を私どものほうで対応するという部分で行わせていただいておりますので、利息につきましては。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問","question":"収入減少、この要件が廃止という形になりましたけれども、そういった中で、少し余裕のある方といいますか、少しお金に余裕のある方もお金を借りられるという、拡充してくれるのはすごくありがたいのですけれども、今現在、その窓口に相談が大変殺到しているとお聞きしている中で、本当に資金繰りに困っているという方たちの審査、振り込みというのが滞っているというのを噂で聞いたことがあるのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"先日、５月１日から郵送のほうの受付も開始させていただきまして、こちらにつきましても、郵送ですので少しタイムラグは出てきてしまいますけれども、おおむね１週間から１０日ぐらいでご本人様に返すことが、疑義がなければという形になりますが。","id":"exchange-007"},{"speaker":"湯澤委員","kind":"質問・要望","question":"仮に適用されるならされるでいいと思いますし、ぜひしてほしいと思いますし、仮にされない場合というのは、限度額が５００万円から２,０００万円になると思うのですが、改めて、例えば１,５００万円借りたいとか、そういうことも可能なのかというのを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"５００万円の融資が既に終わっている方が追加でということであれば、もちろん、その差額部分につきましては対応できるというふうに考えております。","id":"exchange-008"},{"speaker":"湯澤委員","kind":"質問","question":"そうすると、ごめんなさい。今、手続き中の方は難しいということでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私どもの融資あっ旋はもう即日に発行させて、書類上は、手続き、その場でもうすぐに発行していますので、あとは銀行とのところで、どこまで進んでいるかという部分で、後戻りできる部分なのか、もう終わってしまっている部分なのかというところで。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問・要望","question":"何点か伺いたいのですけれども、今回、売り上げ上昇の見込みが難しい事業者ということについて伺いたいのですね。そういった方々に対しての融資をかなり緩和をしてしまうと、逆に、個人に対する貸付という意味合いも強くなってしまうと思うのですね。ですので、その辺、フリーランスの方々への貸付に関してのそこの部分をご答弁いただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"税金の部分がありますので、そこはきちんと分けて、ですので、当然、個人貸付にはならないような形のもので対応させていただいているところです。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"１点目なのですけれども、ご答弁の中で、結局、緩和、審査が緩和されたかどうかという部分について、今ひとつ聞きとれなかったので伺いたいのと、あとは、３点目の個人事業主についてなのですが、開業届を出していない方は対象にならないという認識でよろしいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"改めてそれを持って、結局、銀行に行って融資を受けなくてはいけませんので、そこでは改めてそういう審査の部分、先ほどの保証協会等もありますので、そういう部分ではきちんと分けられているのかなというふうに感じているところです。","id":"exchange-011"},{"speaker":"くにば委員","kind":"意見","question":"そうですね。ですので、そこの１点目のところで、審査の緩和、そちらの部分を、事業者の方々、何とか事業を続けていくために、ぜひともお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"こんの副委員長","kind":"質問","question":"現状を少しお聞きしたいのですけれども、先ほどの質問の中で、相談件数とか、それから受理件数とか、融資が決定した件数とか、ご答弁いただいたのですが、そうすると、相談件数から見て、申請数、相差が多分、ここを計算すると１,０８８件、相差があると思うのですけれども、要は、相談に来たけれどもだめだったのか、あるいは、申請まで行かなかったのか、ご本人がやはり、ではこれは次回にしようというか。","respondent":"遠藤商業・ものづくり課長","answer":"結構、満額使われる方が多かったので、とりあえず１回は、無利子ということでとりあえず満額、現金を持っておこうというところがあったと思うのですけれども、その方が、結局、緊急事態宣言が出る前のメニューでしたので、それが出てきて。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"今、次にお聞きしようとしたことが答弁で少し出たのですけれども、要は、限度額いっぱいまで借りている人が多いのか、それとも、少しずつ改正の範囲で先を見ながら借りていく方があるのかというのを次にお聞きしようと思ったのですが、限度額いっぱいの人が多いというところで、やはり、緊急事態宣言の発令前と発令後とでは、やはりかなりお店の心配事が増えてきているのが現状見てとれますので。","respondent":"遠藤商業・ものづくり課長","answer":"今回の融資に際して、窓口の変化する部分というところですけれども、利用者にとって、支援メニューというのは幾つか、今回の緊急融資だけではなくいろいろとありますので、その辺をいろいろと組み合わせるなり、あるいは、一番有利なものをご推薦させていただいて。","id":"exchange-014"},{"speaker":"こんの副委員長","kind":"質問","question":"最後に、５月から郵送受付をされるということで、もう既にこれが始まっているという理解でよろしいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"郵送のほうは５月に入ってから受付を開始させていただきまして、大体、今、１日４０件ぐらいが届いているような状況です。こちらは当然郵送でありますけれども、なれている方となれていない方というところがあろうかと思います。","id":"exchange-015"}]},{"id":"topic-02","title":"第３２号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３２号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それに対する対策というのは、もう、区民の方からも問い合わせがあったのですけれども、電話で予約をとってと、いろいろやりようがないのかという問い合わせを今朝も受けたのですけれども、その辺がどうなっているのか、伺えればと思います。","respondent":"木村戸籍住民課長","answer":"今後も引き続き運用を見直して、なるべく、そういう意味ではご迷惑をおかけしない、スムーズに手続きができるという形で進めてまいりたいと思いますが、どうしても１日の処理件数を上回るニーズがあるものですから、今のご案内としては。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問","question":"私の理解が不十分で、マイナンバーカードを持っていないもので不十分で申しわけないのですけれども、要するに、本庁舎でないと今はできない、手続きが。それで、本庁舎の窓口へ行かないとできないで、だから電話で予約をとったり、郵送でということは、とにかくできないわけですね。だけれども、今、改善策を考えているところだという理解でよろしいわけですか。","respondent":"木村戸籍住民課長","answer":"そういう形で、１日に処理ができる件数をなるべく、今まで以上に増やしていくということと、プラス、いわゆるオンライン申請が速いというイメージが、イメージがと言いますか、そういうことで国も進めたわけなのですけれども、実際には、申請の後の振り込みまでの内部処理。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"それで、商業・ものづくり課長にお伺いしたいのですけれども、先ほど、融資あっ旋の実態ということで件数をお伺いしましたけれども、今度、新たに出てきた雇用調整助成金のほうですけれども、これの相談件数、それから、やはり相談までの期間と申請数をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"私どもでしています社会保険労務士の無料相談窓口、４月から開始させていただきましたが、そちらの件数が現在１６０件を予約で受けているところです。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"この最後に出てきた商店街支援なのですけれども、これは３つに分けて１００万円、７５万円、３７万５,０００円ということなのですけれども、それぞれ、全部で９８商店街ということなのですけれども、それぞれ幾つ商店街があるのですか。１００店舗以上の商店街、５０から９９店舗、４９店舗以下という商店街というのは。","respondent":"遠藤商業・ものづくり課長","answer":"今回の予算計上をさせていただいたところにつきましては、１００店舗以上が１０商店街、それから、５０から９９店舗の商店街が６０、残りの４９店舗以下が２８商店街という形で算出しています。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"どういう基準で計算して、こういう支援額になったのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"少しくどい言い方で申しわけありませんが、ですので、１００店舗以上のところにつきましては１万円、５０から９９店舗のところについては１万５,０００円、４９店舗以下のところに対しては１万５,０００円というような算出で、今回計上させていただいたところです。","id":"exchange-020"},{"speaker":"おくの委員","kind":"意見","question":"そうしますと、１００店舗以上のところは東京都から出ることを勘案して行ったと。は出ないから、区独自ということで行ったということで、そういう意味では、この事業自体は区独自のもので、もちろん、区や都の補助金が後から出るとかそういうことを勘案して行った事業ではないですよね。でも、１００店舗以上のところは、都から出る協力金も勘案しながら額を決めたという、そういう理解でよろしいわけですね。","respondent":"遠藤商業・ものづくり課長","answer":"１００店舗以上のところについては都のほうから別のメニューがあるというところがありますので、９９店舗以下は少し手厚くさせていただいたというところです。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問・要望","question":"結果として、この支援金額、支援ということなのですけれども、どういう使いみちを想定されているのですか。あるいは、商店街の方から、どういうことに使いたいからという要望があったのでしょうか。あったのではないかと思うのですけれども、大変なことになっていると思いますから、商店というのは。その辺、どういう使いみちを想定して出されたのかということをお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"やり方についてもいろいろあると思いますが、私どもとしては、新型コロナウイルス感染症が蔓延しないようにというところで、今回、支援金を出するところですので、例えば、商店街によっては、各個店にアルコールの消毒液を配るとか。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問・要望","question":"もし、商店街の方から具体的な要望が、これを決める前にあったのなら、例えばということでお教え願えればありがたいのですけれども、その点はいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"新型コロナウイルスでいろいろな影響を受けているので、商店街の方から言われるのは、いろいろな影響を受けているというところで、何か、どのような形でもいいから支援いただけないかというところで、私どもとしても、なかなか。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、自粛、休業によって、私が伺ったお声からも、廃業の危機に直面されている方もたくさんいらっしゃいますし、そういう危機が感じられるから、今回、融資要件の拡大にも踏み切られたと。私がつい最近伺った小売業の方も、客は３分の１、４分の１に減っているのだというおそばやさんから伺ったり、それから、クリーニング店でももう客が半分以下に減った。そういうふうに小出しにしないでほしいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"おくの委員","kind":"意見","question":"済みません。そういうふうに、安心して自粛、休業するためには、もう何遍も言っていますけれども、結局、そういうふうに利子の補給、あるいは信用料の補給というように、直接支援がどんどん必要になっているような、そういう段階だと思うのです。さらに、他方で、自粛、本当に行ってほしいと。戸越銀座にお住まいの高齢の方からも、かなり頼まれたのですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問・要望","question":"済みません。ですから、改めて、私はこの直接支援、あるいは補償、そういったものに踏み込む段階に来たということではないかと思うのですけれども、それを改めて求めたいと思いますけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、一方で、実際に区民の方が困ってらっしゃるというところがありますので、ただ、一方で、区のほうでも財源という部分でいろいろと厳しい、限られているところがありますので、区としてどのような支援ができるか。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"この５月から。５万円上限ですけれども、家賃の減額分の２分の１を、この４月から９月、半年が限度ですけれども、区独自に行い始めました。品川区で区独自に、こういう固定費の補助、そういうことを工夫していく余地はあるのではないでしょうか。区独自の制度を、品川区でまだ踏み出していないのはなぜなのか、その点をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"これによって、区のほうの負担も、大体５００万円ですと２０万円ぐらい、融資を受けた方への、いわゆる助成に近いような形になろうかと思います。そういった部分で、いろいろな支援の方法はあろうかと思いますので、いろいろ研究してまいりたいというふうに思います。","id":"exchange-027"},{"speaker":"おくの委員","kind":"質問","question":"すばらしいことを行われていると思います。これは直接に伺っているのです。先ほど言いましたけれども、戸越銀座にお住まいの高齢の方から、戸越銀座にこれだけ人が出てくるのを何とかしてほしいと言って、もう２度も３度も電話で伺っているのです。そのぐらいの危機ですよ、このコロナというのは、と思いますので、ぜひ、これだけの工夫をしてきたのですから、さらに工夫、ほんとうにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"雇用環境整備事業助成金、テレワーク導入というのがあるのですけれども、ハード面について言うと、国はハード面でパソコンなどは認めていない、東京都は認めていると、国と都でばらつきがあって、そういった中で、この品川区の推しと言いますか、ハード面でそろえているのが品川区の推しですであったり、社会保険労務士、このコンサルティングの費用を助成するのが雇用環境整備の推しであるという。","respondent":"遠藤商業・ものづくり課長","answer":"そこの部分について、うちのほうでは、上限２０万円という形でさせていただいているところですが、こちらと、あとは実際に専門家なども入れた部分の費用も、うちのほうで持たせていただくというところが、今。","id":"exchange-029"},{"speaker":"松澤委員","kind":"意見","question":"２０万円と、社労士のコンサルティングというのがメーンということはわかりました。その中で、雇用環境安定化事業助成金、社会保険労務士の助成とありますね。これは、先ほど１件でしたか。あったのは。１件ですね。","respondent":"遠藤商業・ものづくり課長","answer":"おっしゃったように、社会保険労務士、この手続き自体も社会保険労務士の専属の、あとは弁護士という形になろうかと思いますけれども、主に社会保険労務士が行われるような形になると思いますので、そうすると、確かに社会保険労務士。","id":"exchange-030"},{"speaker":"湯澤委員","kind":"質問","question":"仮にこの１００件というのを超える場合というのは、さらなる助成のような形も考えているのかどうかというところが１点と、それからもう１つが、商店街支援のほうなのですけれども、こちらの会員店ということだと思うのですが、賛助会員などの場合もそこに含まれるのかというのを教えていただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"現在１００件、今回要求させていただいて、もともと１００件いただいておりますので、２００件以上になった場合どうするかということなのですけれども、もちろん、増えた場合には補正等で、できるだけ多くの方に、申請があれば受け付けたいというふうには考えているところです。","id":"exchange-031"},{"speaker":"湯澤委員","kind":"質問・要望","question":"賛助会員の方もぜひ含めていただければと思いますし、本当に、このコロナのことで困っていらっしゃる方がたくさんいて、また、それに対して、区の皆さんもすごく真剣に、そして一生懸命取り組まれていることは本当にありがたいことだと思いますので、その上で、どうしても早く、早くとスピードを求められるところもあると思いますので、スピード感を持った対応をしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"２点伺いたいのですけれども、こちらの商店街の対策支援金のほうなのですけれども、先ほどおっしゃって、ご答弁なさっていた予算金額６，５６０万円、その内訳をもう一度伺いたいのですけれども、よろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"１００店舗以上のところが１００万円で１０商店街で１,０００万円、それから、５０店舗から９９店舗のところ、こちらが７５万円掛ける６０商店街で４,５００万円、それから、４９店舗以下のところが３７万５,０００円掛ける２８商店街で１,０５０万円、それから。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"それで、伺いたいのが、こちら、目的のところに、感染拡大防止に取り組む商店街を支援するということで明記されているのですけれども、伺いたいのが、こちらは申請をしたら、申請をした全ての商店街にこちらの協力金、支援金を出すのか、それとも、きちんと取り組んでいただける商店街に対してこちらの支援金を出すのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"申請の段階で、一定、こんなことをやりますというのを書いていただくような形で考えておりますので、そちらを書いていただければ、後で確認などはしないで、その場でもうすぐに支給するという形で考えております。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2866#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":26248,"voices":110}},{"id":"r02-20200512-7","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"厚生委員会","time":"午前１０時１１分～午後 ０時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"第３４号議案および第３６号議案の健康推進部が所管する「専決処分の承認を求めること」","agenda":"第３４号議案および第３６号議案の健康推進部が所管する「専決処分の承認を求めること」","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２番の対象者の３７０人という人数の出し方なのですが、先ほど区のコロナの感染のピーク時の見込数からというところで言われたのですけれども、その数と、品川でどれぐらいになって、それから、それに対しての国保の加入率、そこの中から給与所得者の割合とかという形で出していくと思うのですが、そこの数値を具体的に、何で３７０人というのが出てきたのかということで。","respondent":"池田国保医療年金課長","answer":"それと、周知についてですけれども、先ほどのパンフレット、「こんにちは国保です」ということで用意はしておりますが、その他に品川区の広報につきまして、こちらは私どもの国保の分と、これから予定しております後期高齢者の分というものがありますので。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、今回傷病手当ということで、３７０人の専決の補正ということになったのですが、これと同時に私は、厚労省と総務省から出されている通知で、コロナ感染症の影響により収入減少した場合の国保料減免の通知というのが出されていると思うのですけれども、それに対しての予算は組まなくていいのかなと思っているのですが、その点についてはいかがでしょうか。","respondent":"池田国保医療年金課長","answer":"もう一つのコロナウイルス感染症の拡大に伴っての保険料の減免ということにつきましても、ただいま私ども２３区課長会の中で減免のやり方について協議しているところでございまして、実際には６月の賦課計算に間に合うようにということで準備を進めているところですけれども。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国保も今は、加入者のうち３４％近くが給与所得者という状況に変化しているわけですから、この実態に合わせて、社会保険と同様にコロナだけでなく、病気やけがで仕事を休まざるを得ないという方にまで支給ができるような仕組みにするよう、区としてもぜひ取り組んでいただきたいと思うのですが、そのことについても一言あれば、お願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"今お話のございました健康保険上の通常の傷病手当金につきましては、委員がお話されたように、もともとの加入されている方が自営業の方であったり、農業をされている方ということで、健康保険とかが違った階層で入っているですので。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこで、まず確認させていただきたいのですけれども、この対象者が、感染した者または疑われる者というのは、ちょっと分かりにくい。ただ、検査というのがなかなか受けられない状況がずっと続いてきた中で、検査は受けていないけれども、例えば発熱があるとか、症状があるということで、自主的に休むなり、職場から当分休んでと言われた方というのは対象になるのでしょうか。確認です。","respondent":"池田国保医療年金課長","answer":"ただいまの点についてですけれども、陰性の方も当然、対象になるのですが、実際にコロナウイルス感染症の症状がおありになって、自宅でお休みになっていまして、ところが、ずっと長くお休みをされていたら、お医者さんに行かなくても治ってしまったという方につきましても。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"特に、お医者さんに行っていないのに傷病手当が受けられるということは、ぜひ強調してアナウンスをしていただきたいと思うのですけれども、なかなかホームページに書いただけでは、それを発見していただくというのは難しいと思います。やっていなければ、今日からでもやっていただきたいと思いますが、いかがですか。","respondent":"池田国保医療年金課長","answer":"こちらにつきましては、国保だけでなく、政府管掌とか組合健保等の保険についても、コロナウイルスについての傷病手当金ということで、既に取り組んでいるところですので、国保ということではなく、保険に加入されている方皆さんに、コロナウイルスに感染された方。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"問題は、検査を受けずに職場を症状ありでお休みだった方に、どう伝えるか。なので、国保料の減免制度がありますというアナウンスと一緒に併せて、お休みをされたら国保でも傷病手当がありますというのを書いていただくと、少しはプラスになるのではないかと思いますが、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"確かにＰＲというのは一番大事なことですので、これについては前向きに進めていきたいと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だけど診療所には来ないでくださいと言われて、それで診断書は出しますと言われたのだけれども、そういう場合は多分、対象になるのです。そういうところで、診断書を出しますというクリニックとか医師会とかに、こういう制度がありますのでお伝えいただけたらということをしていただけると、周知にもつながるのかなと思ったのですけれども、どうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ医師会にもよろしくお願いしたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"の順番を入れ替えまして、第３２号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の順番を入れ替えまして、第３２号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは基本的に自宅療養ということで、ホテルに隔離されているという方は品川区でもいらっしゃるのかなと思うのですけれども、その人数が分かったら教えていただきたいのと、ホテルで隔離されている方にも、パルスオキシメータが足りなくて測れないというのが新聞報道の中でも出されていたのですけれども、そういうところに対しては。","respondent":"鷹箸保健予防課長","answer":"ホテルで足りないといったことについては、我々では把握していないのと、ホテルに入られる方に区から対応するといったスキームは、現在のところではございません。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１台１万５,０００円で、何台購入するというのを教えていただけたら。","respondent":"鷹箸保健予防課長","answer":"おおむね５００台を想定しておりますけれども、今回購入分は１５０台を想定して、そこまでは買わずに済んだというところです。本当に全国で足りないという状況は聞いております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"時間もありますので、引き続いてＰＣＲ検査のほうも伺いたいのですけれども、これは５月１２日、今日から始まるということで、こういうＰＣＲ検査センターを作っていただきたいと、ずっと要望もさせていただいておりましたので、本当にできることになってよかったと考えています。","respondent":"鷹箸保健予防課長","answer":"帰国者・接触者外来ですけれども、品川区では今、３病院にお願いしている外来で本当に多くの患者を受け入れていただいておりまして、その点では、それほどお待たせしているとは我々としては認識していないところで、マックス１日５０人ぐらい診ていただけております。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５００台というのは、これから第２波、第３波、秋冬にかけて、またそういうのが来るのではないかということも言われている中で、これだけの体制をしっかりと取っておくというところは、すごく評価をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検査をすることで、医療崩壊を防いでいくのだというのが、今大きな世論になっていると思うのですけれども、その中でのＰＣＲ検査の考え方、対象者に対しての考え方というところでは、区としてどのように考えられているのかということについてお聞かせいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"ＰＣＲ検査の対象につきましては、区独自ということではなくて、あくまでも国が出した方針にのっとって対象としていくということの後は、３７度５分が４日以上、基礎疾患の方は２日以上ということがありましたけれども、それ以外の医師が必要と認めた場合というのは。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ただ、目安というのが大きく変えられることによって、多分、検査をされる対象というのは大きく広がると考えられるのではないかと思うのですけれども、その点はいかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"今、委員ご指摘のとおり、金曜日に変わりましたので、今後は、あくまでもかかりつけ医の先生が必要と判断された方が、予約という形になりますけれども、対象についてはかなり増えるのではないかというのは、当然想定しています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＰＣＲ検査はもう一つなのですけれども、実施件数が１日当たり２０件ということなのですが、この２０件という件数が出てきた根拠というのが、どこから出てきているのかということと、それから、予算額が６,５５９万円余ということなのですけれども、これの内訳が、人件費、検査費、もろもろということだったのですが、内訳が分かったら教えていただきたいと思います。","respondent":"舩木保健体制整備担当課長","answer":"あわせまして、初年度調弁を合わせた最初の一月のコストが大体２,７００万円と見込んでおりまして、これを６月以降８月というところまで、まずは当面を見越しまして、全体の費用を６,５００万円余として見込んでいるところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう形でホームページにも載せていただけたらいいのではないかと思っているのですがその点と、それから、これはドクターの判断で検査が必要だということになると思うのですけれども、そのドクターの判断というのは、例えば先ほど例として挙げたように、診察には来ないでくださいと言われて、電話で症状を聞いて、その電話で予約していただくという形もできるのでしょうかということが２点目。","respondent":"舩木保健体制整備担当課長、鷹箸保健予防課長","answer":"３点ございました質問のうち、２点ほど私からお答えいたします。陽性になった方への対応ですが、陽性になった方については、保健所がその方に結果をお伝えするというスキームになっておりまして、ＰＣＲ検査センターにいらした方は、検査をした時点で肺炎の有無ですとか。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"ＰＣＲ検査から伺っていきたいのですけれども、検査員の方々というのは輪番になっていくのでしょうか。慣れるまでという話があったように、毎回日替わりだとなかなか慣れが少ないのか、１人２人というか、どういう体制なのか、確認させてください。","respondent":"舩木保健体制整備担当課長、鷹箸保健予防課長","answer":"質問いただきました最初の２点について、私からご説明いたします。この間、報告方法に何度か変更とか変遷がございまして、その中で、私どもの自治体ではそういったことはなかったのですけれども、発生届がまず出ますと、そのデータに関しては別に、都に必ずファックスをするのですが。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"ＰＣＲ検査については、先行する他の自治体も、なかなかキャパシティーほどの検査数は行われていないと各自治体の議員からも聞いているところなのですけれども、お医者さんからの紹介ということが結果的にという話になるのでしょうか。何か背景なりを感ずるところ、あるいは、今後の１日２０件ぐらいを目安とするとして、実数として大体どのぐらいになりそうということは、想定はされているのでしょうか。","respondent":"舩木保健体制整備担当課長、鷹箸保健予防課長","answer":"例えば、１台だけ借り上げられたとして、この人は移送手段を確保してもらったけれども、同じ状況でこの人はというところが、非常に難しいところでございまして、引き続き検討といいますか、考えていきたいと考えています。それを考えますと、症状があろうとなかろうと、本来は入院なのですけれども、ただ、それがないので、施設もまだ決まっていなくて、その人たちに、４月に本当に増えたときに、自宅にいていただいてしまったというのが現状なのですが。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"先行諸外国などは、待機者と言ったらいいのでしょうか、疑いのある方向けのタクシーみたいなものをきちんと整備して、それを使ってくださいと。それとＰＣＲの検査なのですけれども、これはドクターからも以前は、なかなか医師が必要と判断しても検査してもらえないという声が上がっておりまして、私も聞きましたけれども、そういうことはさすがに今後はないと考えていいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"妊婦の育児パッケージについてもお伺いしたいと思います。はっきり分からないのですけれども、これは今年度の妊婦が対象ということなのですが、つまり、今年の４月１日時点で妊娠中であった方から、今年度いっぱいまでに妊娠届を出された方までが対象ということでよろしいですか。既に育児パッケージを受け取った方には、これは面談なしで追加で送るということでよろしいでしょうか。そこを教えてください。","respondent":"榎本荏原保健センター所長","answer":"３点のご質問で、まず期間ですけれども、本年度ということで、４月１日以降を基準日として、都のほうも示してありますが、先ほども説明いたしましたけれども、状況把握や簡単なご相談支援といったものを専門職が行うということも、対象者の要件にはなっております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"対象をもう少しだけ確認させてください。４月１日基準で妊娠をされていた方ということは、既に出産を終えている方も対象ということになるのでしょうか。今年度中に妊娠というのは、妊娠届を出した日が３月３１日までということでよろしいのでしょうか。","respondent":"榎本荏原保健センター所長","answer":"３月３１日に妊娠届を出された方まで対象になるということです。","id":"exchange-021"},{"speaker":"あべ委員","kind":"確認","question":"この件は妊婦の方がとても関心が強くて、自分が対象になるのか、いつもらえるのか、受け取れるのか、すごく関心が高い部分ですので、いつもらえるかというのも教えてください。もちろん、これから妊娠される方は、その後ということなのでしょうけれども、今妊娠中の方がいつ頃これを頂けるのかということを確認させてください。お願いします。","respondent":"榎本荏原保健センター所長","answer":"いつもらえるのかということですが、先ほどの電話をおかけしてという相談のアプローチの仕方がありまして、Ｑ＆Ａなどで都のほうも、アンケートとかという言い回しが出てきたりもしておりまして、どの手段を取ると一番早くお渡しできるかをこちらも検討して。","id":"exchange-022"},{"speaker":"あべ委員","kind":"意見","question":"最後にしますけれども、これは知事の会見ですごく取り上げられたこともあって、来るのは今か今かと先月来、待っていらっしゃる方が大勢いらっしゃるので、見通しも併せてアナウンスしていただくとともに、早急な配布をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問・要望","question":"簡潔に３点ほど。それぞれどのような予算の内訳になるか、お知らせいただきたいと思います。それから３の育児パッケージについては、郵送で基本は行われるということで、中には戻ってきてしまう方もいらっしゃるかなということで、そういう方への対応について確認をさせていただきたいと思います。これは検査を行って、結果が出るまで何日間かかるのか、お聞きしたいと思います。","respondent":"高山健康課長、榎本荏原保健センター所長、鷹箸保健予防課長","answer":"当面、５月から９月までの間で開設されます休日診療における医師および看護師の方々のための防護用品ということで、ゴーグルであるとか。妊娠届を出されるときに、ご自分でご住所をきちんと書かれて、通常は出しておられますので、ほとんどの方は届くとこの場合は考えておりますけれども。検査が出るまでの間は陽性に準じて、基本は外出をせずに自宅にいてください、またご家族のいる方については。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"今のＰＣＲ検査については、受けて、私がこれからその先、自宅で翌日結果が出て、陽性が出ればこうという、いわゆる入り口というのか出口というのか、そこら辺まで含めた、さっきフローチャートを今日アップされるということで、そこら辺まで示された内容になっているのか、そこだけ確認をさせていただきたいと思います。","respondent":"舩木保健体制整備担当課長","answer":"フローですけれども、検査結果の判定など、陰性になった場合にはかかりつけ医から、陰性でしたというアナウンスになりますが、陽性の方については、ホテルなどでの療養であったり、中等症、重症の場合には、病院に入院であることまでの流れをお示ししたフローになってあります。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問・要望","question":"説明ありがとうございました。１点、定額給付金のところで聞いていきますけれども、これは僕らも言われるのですが、品川区はまだですかという話で、マイナンバーカードを持っていなかったらというところで、でも、今の課長のご説明の中でも、一日でも早くと言っていただいたので、その一日でも早くを、もう一日でも早くやっていただきたいというのが私たちのお願いでございまして、そこは要望いたします。","respondent":"寺嶋特別定額給付金担当課長","answer":"銀行口座につきましては、口座のページの写しを必ずつけてもらいますので、これは書き損じであったり、読みづらい字であったりする部分につきましては、入力のときに通帳と確認はして、ある意味、通帳を優先して記載するということで。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問・要望","question":"介護・障害福祉サービスのところで伺います。その中で、支給の方法のところで、よくありがちなというか、これは品川区どうこうではなくて、きちんと該当される方に届く。それと、平均的な受給額。まさしくタイトルどおり、業務継続支援。これは特に感染リスクの点から、ここからまた従事者が離れてしまうと大変なことになるので、要望も含めて伺いますが、これを第１弾と考えたときに、次の手。","respondent":"宮尾高齢者福祉課長","answer":"今回のこちらの業務継続支援金の趣旨は、現場の第一線で従事していただいている皆様に、気持ち等をお示ししたいというところがありますので、まず支給は、資料に記載させていただきましたとおり、各事業所・施設に対してお支払いをするのですが。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問","question":"すみません、最後に簡単に。もう１点、今回は人への支援なのですが、感染リスクは今後も、いろいろな工夫もそうですし、業態も含めて、ハード面を含めて手を入れていかなければいけないと思うのです。その辺はこれと関連して、感染拡大という点から第２弾、第３弾と、大きく事業所に対する支援が必要かと思います。その辺の見立てを最後に伺って終わりにします。","respondent":"宮尾高齢者福祉課長","answer":"こういった物的な支援も含めて、様々なところからお声を頂きながら考えてまいりたいと思っているところです。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"給付金についてお伺いしたいのですけれども、今日も朝８時５０分にマイナンバー関係の受付は終了と出ていて、窓口の方も非常に大変な思いをされていると思うのですけれども、今、マイナンバーの申請関係が増えているというのは、給付金の関係が多いかなと思います。割り算していくと、郵送のほうがもはや早いのではないかと思いますが、いかがでしょうか。","respondent":"寺嶋特別定額給付金担当課長","answer":"７００件対２万１,０００件なので、それで全体の２３万世帯のうち、約１万件がおそらくオンラインになる。今、オンラインでの申請が９,０００件を超えているので、おそらく１万件ぐらいにはなるだろうと考えています。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"処理件数との見合いで、その時々でアナウンスをしていただければと思います。しかしながら、これも知らなければ、この制度も役に立たないということで、まず、現在もまだＤＶ被害者の方が追加で申出をすることが可能であるのか、いつ頃までそういう体制を取るのか、そして、どのような形で広報しているのかということを教えてください。","respondent":"寺嶋特別定額給付金担当課長","answer":"それからコールセンターでは、ご連絡があった場合については受付をしておりますので、ご相談くださいということで対応はしております。","id":"exchange-030"},{"speaker":"あべ委員","kind":"確認","question":"それから次の質問で、介護・障害福祉サービス。ありがたいです。事業運営も大変だと思うのですけれども、働く方にきちんと現金が届く仕組みになっているかどうかだけ確認をさせてください。品川区でのこれまでの新しい仕組みになってからの申請の件数とか、あるいは決定率と言ったらいいのでしょうか、条件に合ったら全て出していくのか、それともある程度絞られてしまうのか、その運用も教えてください。","respondent":"寺嶋特別定額給付金担当課長、宮尾高齢者福祉課長、櫻木生活福祉課長","answer":"総務省から日々何件も通知が来まして、情報がどんどん新しくなっているため、広報での周知はあまりそぐわない部分もあると認識しておりますので。業務継続支援金が、働いていただいている職員一人ひとりにきちんと行き渡る仕組みになっているかですが、まさに今回の支援金の目的が。要件が合致したら決定するのかというお問合せかと思いますが、基本的には要件に沿ったものについては、いろいろお話を伺った上ではありますが。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後の住宅確保給付金なのですけれども、対象が広がったということをご存じない方が非常に多いのではないかと思います。これを破綻する前に知っていただきたいという、非常に緊急性のあるものだと思いますので、引き続き周知方、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それでお聞きしたいのは、コールセンターは今、１６名から１８名でされているということなのですけれども、電話の台数と、これまでの相談件数がかなり多いのではないかと思うのですが、何件ぐらいあったのかということについてもお聞かせいただきたいと思います。","respondent":"寺嶋特別定額給付金担当課長、櫻木生活福祉課長","answer":"それから次のホームレス等々の関係ですけれども、これは生活福祉課でお願いして、あるいは連携して対応しているところで、例えば人数の把握とか、案内とか、チラシを持って直接ＰＲしてもらうとか。ネットカフェで都が用意したホテル等に宿泊されている方につきましては、こちらで人数は把握しておりまして、正確な数字ではございませんが、おおむね２０名前後です。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ホームレスの方のところに対しても、総務省でしたか、いろいろそういうところにも行くようにという通知が出ていると思うのですけれども、大体こういうところで生活されているというところを、多分、区も把握されていると思うのですが、そういうところに行ってチラシで案内をしているということで、区としては対応されるということでいいのでしょうか。","respondent":"寺嶋特別定額給付金担当課長、宮尾高齢者福祉課長、櫻木生活福祉課長","answer":"今、むしろ方向性としては、もちろん二重払いは防ぐという大前提はあるのですけれども、可能な限り、でき得る手を使って。そういったことを、まずは正しくしっかりと事業者にお伝えするとともに、これからも経営に対する影響をしっかりと把握していって。現在、もともと４名体制で実施していたところ、生活福祉課の課内の応援として、３名ほど暮らし・しごと応援センターで従事して、応援体制を取っております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"給付金のほうなのですけれども、例えばホームレスというか、住民票がなくて、知り合いの家を転々としているような方だったりとか、そういう方というのは、取りあえずは生活福祉課に相談に行けば、身分を証明するものが何もないという相談を受けたのですけれども、そこら辺のところは生活福祉課に相談に行って、手続きを取るという形になるのかという確認をお願いしたいと思います。","respondent":"寺嶋特別定額給付金担当課長","answer":"最終的には、先ほども言ったとおり二重払いをしないと、ここが一番の肝なので、そういう意味では、何らかの形で、まだその方にお支払いをしていなければ、支給が可能になる方法で何とかしたいと考えていますので、区役所を挙げて。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"ホームレスの方に対する給付金の扱いなのですけれども、ホームレスの方の中にも、居住実態がない、どこかの地方の自治体に住民票があって、だけれども、実際はずっとこちらにいるという方、それから、もう住民票が抹消されてしまっているという方もいらっしゃるかと思います。それぞれについて、どういう扱いをされているのか教えてください。","respondent":"櫻木生活福祉課長","answer":"住民票の件ですが、住民票をお持ちでない方がご相談にいらっしゃった場合は、お話とそれぞれのケースに応じて、もともとの住所地に問合せをするサポートをするとか、もしくは、住民票そのものがどこに行ったか分からないという方もいらっしゃいますので、そのような場合ですと。","id":"exchange-036"}]},{"id":"topic-03","title":"では次に、第３５号議案、専決処分の承認を求めること","agenda":"では次に、第３５号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう一つが、品川区はこの４段階とも、国基準よりも引き下げていると思うのです。これまでも取ってきたわけですけれども、今回もこの第１・第２・第４では０.０５、それから第３では０.２の引下げということになると思うのですが、これも今までを踏襲しているということで、確認をさせていただいてもいいでしょうかという、その３点をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"今回の条例改正の対象となります第１段階から第４段階の方の人数ですが、すみません、各段階ごとの人数というのは、今、手持ちがないのですが、全体として、第１段階から第４段階までを合わせまして、合計で約２万７,０００人の方が、この軽減の対象となると見込んでおります。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":47432,"voices":146}},{"id":"r02-20200512-9","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"文教委員会","time":"午前１０時１０分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","topics":[{"id":"topic-01","title":"第３２号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３２号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ですので、所得制限を設けるべきではないと思うのですが、そこの部分の区のお考えを伺いたいと思います。品川区としても、こうしたひとり親世帯への支援が必要になるのではないかと思うのですけれども、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"区はこの国の方針に従って実施しています。ひとり親世帯につきましては、練馬区の状況は委員ご指摘のとおりだと思いますけれども、品川区といたしましては、ひとり親世帯に関しては、現在のところは支給支援する予定はございません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"児童手当のほうは国がやっていることというのは分かっていますけれども、やはり区としても支援していくということも含め、あと、国にも対象を広げていくようにということで求めていくことが必要だと思いますけれども、いかがでしょうか。そういった形も含めて、ぜひ検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"児童扶養手当の追加の考え方ですけれども、こちらは児童扶養手当も国の法律に則っておりますので、区といたしましては方針として従っているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"児童扶養手当のほうは国だと。区でやっている児童育成手当というほうもひとり親家庭だと思ったのですけれども、そういったことも含めて区として考えていただきたいと思うのですが、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"様々な社会状況がありますので、今、この段階では、まずは臨時特別給付金の一時金を考えて対応しているところでございまして、社会状況を踏まえて、区といたしまして対応すべきときに、しかるべきときに対応していきたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、検討を進めていっていただきたいと思います。やはり新型コロナウイルス感染症の影響で立ち行かなくなって、再開後、認証保育所がなくなっているということは区としてもよくないことだと思いますので、家賃ですとか、人件費の固定費の補助をしていくべきではないかと思うのですが、いかがでしょうか。","respondent":"若生保育支援課長","answer":"対象期間がいつからかですが、実施期間に挙げさせていただいている登園自粛の働きかけを依頼している期間ということでございまして、具体的には、これは認可保育所も同様なのですけれども、３月分から登園自粛に伴っての保育料の返還ということで行っておりますので。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営費の補助は減らさないように国から指導されているというところもあって対応していくということでしたけれども、やはり今、新型コロナウイルス感染症の影響で、園への登録自体をやめてしまうという方も出てきているのかなと思うのです。ぜひやっていただきたいと思うのですが、改めてご答弁いただければと思います。","respondent":"若生保育支援課長","answer":"新型コロナウイルス感染症の影響等で在園の登録自体を外すといいますか、そういったことは事例としてお伺いはしていないところではあるのですけれども、基本的に認証保育所については、登録人数によって運営費等を算定していますので。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、固定費の補助ということを考えていただきたいと思います。次に、ベビーシッターの利用支援ですが、今回、補助の方法が２つあるということで、利用者にとっての違い、何が違うのか、利用する際にはどういう方がどちらのほうがいいのか、そういったところがよく分からなかったので伺いたいのと、都が認定したベビーシッターということで、何社ぐらいあるのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"そこで、今回、事業を開始するにあたって、４月にさかのぼって適用するという形になると、これまで仮に休園になってしまって、ベビーシッターを使用してしまって自己負担で全額支払ってしまった方についても補助の対象になってきますので、そういった場合には。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ利用者の方に分かりやすく周知をしていただけたらと思います。就学援助のほうなのですけれども、今回、これまで求めてきたものが実施されてよかったと考えています。これまで、難しいとおっしゃってこられましたけれども、どのように考え方を整理されたのか、伺いたいと思います。今回、１食５００円ということで考えた理由について伺いたいと思います。","respondent":"篠田学務課長、若生保育支援課長","answer":"１食５００円の考え方ですけれども、基本的には、いわゆる給食費相当分で考えますと食材費だけですので２４０円から３２０円と非常に低額で、なかなか１食分というのは難しいかなと。助成券方式、このベビーシッター事業者連携型というほうですけれども、こちらですと都が認定した事業者に限られますので、認定事業者として１５事業者となっております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"就学援助のほうで、考え方を整理されて実施されたということで、今回、４月、５月の２か月分ということですが、３月から休校されているので、ぜひ３月を入れていただきたいというふうに思うのですけれども、なぜ入れないのか、伺いたいと思います。今後、６月、まだちょっと分からない部分もありますが、今後の見通しも伺いたいと思います。","respondent":"篠田学務課長","answer":"こちらに関しましては、給食の再開は学校の再開に関わってくるということで、学校がいつから再開されるのか、また、どのような形で再開されていくのかによって、給食の提供等もいろいろ変わってきますので、そのときの状況を見ながら、必要に応じて。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"６月分というところでは、今後、学校がどう再開されていくかということもありましたけれども、ここがなかなか難しいところではあると思うのですが、休校の際にはぜひ広げていただきたいと思いますし、あと、開校に向けて、やはり今、子どもたちの学ぶ権利が脅かされているという状況になっていますので、なかなか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は関連していると思っているのですが、今、休校が長期化していて、宿題だけでいいのかというふうに思います。ぜひ今後の教育活動について、受験生もいらっしゃいますので、検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"就学援助の部分で昼食代、１食５００円。こちらは区の決断として、私も３月の委員会で言及させていただきましたし、会派としても４月に要望させていただいたところですけれども、これをやっていただいたということで大変に評価をしています。これは意見です。ベビーシッターが足らなくて、申し込んでもサービスを受けられないみたいな話になるような心配はないのかという点についてお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"これは区としてやっているところが、障害児ですとか、そういった集団保育が適さない場合の児童に対して１対１で保育をするというようなことで、ベビーシッターと似ている形ではあるのですが。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"特に新規の方のご利用が今回非常に増えてくるというところ、ニーズがあるというところで、都の支援も打ち出されてきたと思うので、新規の方へのご案内のあり方は非常にしっかりとやっていただきたいという思いがありますが、そこについての今の予定というか、どのように区内の子育て世帯の方にご利用をご案内していくのかというところで最後にお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"区市町村バウチャー型で届出している事業者の中に、当然、東京都で認定している１５事業者と重複している事業者もありますので、そこの中で先ほど言った１４０人の中にもそういった方は入ってくるというふうに認識しています。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"今、少しお話があったかもしれないのですけれども、ベビーシッターについてお伺いいたします。資料では、「保育所等が臨時休園等を行ったことにより、」「ベビーシッターの利用を余儀なくされた場合」と書いてありますけれども、今回はその利用の要件として、保育園に入所していた、預けていたという方のみが対象になるという理解なのか。“入所していた”という要件が必要なのでしょうか。","respondent":"若生保育支援課長","answer":"対象者ですけれども、これは保育所等に通う児童ということになりますので、認可ですとか認証、それから認可外、そういったものを含めて、やはり“保育園に在園している”というところが要件になっているものです。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"すみません、少し細かいところなのですが、確認させてください。もう１点、子育て世帯への臨時特別給付金についてのところ、こちらも確認だけなのですけれども、対象児童のところで、「上記のほか、同年３月分の児童手当の対象となっている児童であれば、４月から新高校１年生となっている場合も対象となります」とあるのですけれども、これはちょっと詳しく教えていただければと思います。","respondent":"若生保育支援課長、三ッ橋子育て応援課長","answer":"これは償還払い方式ですと、利用後に領収書ですとか証拠書類をご提出いただいて、その後、審査、支払いという形になりますので、通常ですと。すみません。交通費につきましては、現時点では対象とはしてございません。対象外です。したがいまして、３月分を含むという部分については、新高校１年生も含まれるということになっております。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"すみません、私の理解がちょっと悪くて申し訳ないのですが、先ほど、筒井委員が質問しましたベビーシッターの対象者ですけれども、医療従事者などの保護者の方に対しても保育所が開いていないところがあるということでよろしいのでしょうか。いまいちベビーシッターを利用する方がどのような方なのかが分からなくて。","respondent":"若生保育支援課長","answer":"基本的には、資料の事業概要に書かせていただいたとおり、新型コロナウイルス感染が発生して臨時休園してしまって、医療従事者等も含めて登園ができないような方がまずメインで対象になってくるだろうというようなことで考えております。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問","question":"新型コロナウイルスに感染している方が保育所で出たという場合の休園となると、そのほかの方は濃厚接触者にはならないのですか。","respondent":"若生保育支援課長","answer":"濃厚接触者と判定された園児ですとか保護者が家にいらっしゃる場合は、当然、ベビーシッターの利用は難しいかと考えていますが、それ以外で、自粛されていて、実際は登園していなかったり、あるいは。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問","question":"理解いたしました。１点だけ。子育て世帯への臨時特別給付金、児童手当の１万円の部分ですけれども、国からの全員に配られる１０万円の給付金にはあったのですけれども、ＤＶを受けて逃げていらっしゃる方に対しての周知について“こういう方法があります”ということがあったと思うのですけれども、児童手当の対象の方で、そういった対象の方はいらっしゃるのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"所得であったり、また、どちらが世帯主になるかとか、そういうものの中でＤＶについても、認定するにあたっては通常から取り組んでいるところですので、通常どおりということです。ホームページ上でも「ＤＶについては」という文言は載せる予定です。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは質問ではなくて要望するのですが、それぞれ都なりで対応して、いろいろこういった施策を行っていただいてありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":15596,"voices":66}},{"id":"r02-20200512-5","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"総務委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"私からは、民生費で、特別定額給付金の件でお聞きします。そういう中で、やはり支給がいつになるかという声をいろんな方からお聞きしました。ホームページで見ますと、申請書を送るのが今月の２２日だったと思いますが、それまでのことは事細かに書いているのですけれども、肝心要の給付の時期については特に記載がなかったものでしたので、まず、目安でも結構ですので、給付時期について教えてください。","respondent":"品川財政課長","answer":"特別定額給付金の支給についてです。５月１日よりコールセンター設置等をしまして、マイナンバーカードによるオンライン申請は５月１日から開始しております。支給ですけれども、オンライン申請については５月１８日頃を目途として出せればと考えています。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"６月ではなくて、とにかく一刻も早く、５月下旬にでも支給してもらいたいという声がありますので、区役所の方も本当に大変だと思いますけれども、ぜひよろしくお願いします。今日も朝８時５０分に受付を締め切ったという話を聞いています。そういう情報をホームページで見たのですけれども、これは１日に受付できるキャパシティー、数があるそうなのです。そこを教えてもらってもよろしいでしょうか。","respondent":"品川財政課長","answer":"オンライン申請の受付ですけれども、確かに１日の上限というのはあって、この間、いろいろマイナンバーカードに関する申請関係が多くなっております。１つは、マスコミ等でも最近言われております、暗証番号を忘れてしまったという件です。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"という感じの表示がされています。品川区でももう少し、人の流れというわけではないですけれども、申請をなるべく書類申請の方向に持っていくようにすれば、多分、朝、相当混雑されていると思うので、少しでも混雑解消、また３密の解消にもなると思うのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"この間、今回の補正予算にも出ておりますとおり、事務をなるべく郵送扱いという形で進めているところです。委員がおっしゃるとおり、こういったところについても、郵送受付を促していくような形で周知の努力をしていきたいと考えています。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"特別定額給付金の事務費のことなのですけれども、こちらは国庫支出金から出ていると思うのですけれども、これは前もって国から出された数字なのか、もしくは区から提示したものなのかを教えてもらえますでしょうか。","respondent":"品川財政課長","answer":"事務費につきましては、区で、委託費用、それからシステム等の改修費用を試算しまして計上しているものです。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"これは東京都でも似たようなものがあったと思うのですけれども、たしかこれは商店街の加盟店舗の数・規模によって、最大１００万円だったと思うのですけれども、１００店舗以上、５０店舗から１００店舗未満、５０店舗未満で分かれていたと思うのですけれども、それ以外に何か要件というのはあるのでしょうか。それと、これは申請方式なのかどうかを教えてもらいたいのですけれども。","respondent":"品川財政課長","answer":"商店街の奨励金につきましては、基本的には、１００店舗以上の商店街、５０店舗以上１００店舗未満の商店街、５０店舗未満の商店街という形で、金額は分けてやっていく予定です。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"さらなる対策の充実をしていただきたいという視点で幾つか絞って伺いたいと思います。初めに補償についてです。あわせて伺いますが、ＰＣＲ検査にかかわる費用なのですけれども、やはり全額、国庫負担を、区として求めるべきだと思っているのですけれども、それについても、いろいろ同時に聞いてしまって申し訳ないのですが、それぞれお答えいただきたいと思います。","respondent":"品川財政課長","answer":"そういう中で、国に求めたりというところは、区としては避けていきたいと考えております。今後、ＰＣＲ検査等といったところも、国で補助を考えるような動き等も出てくるかもしれませんので、そういった状況も見極めながら、状況に応じて対応していきたいと考えております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、直接支援や補償について、区独自で進めていただきたいと思いますが、やはり各自治体が一丸となって取り組むべきときだから国に求めないといった姿勢では、今回のコロナ危機から住民の命と暮らし、営業を守ることはできないと思います。区も実施を見送っていく。そうしたことの検討も必要ではないかと思いますけれども、そもそもの考え方と具体的なことと、それぞれお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"それを見込みまして、それに合った歳出の考え方というところは、令和３年度予算編成にあたって、実際に必要になってくるところではないかと思います。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の補正予算には、学生への支援は位置づけられておりませんが、なぜなのかということを伺いたいと思います。例えば、大学生を含めた区独自の給付型奨学金や、国や都に対して授業料を半減するなどの要請をぜひやっていただきたいと思いますけれども、いかがでしょうか。中止というのは、現状の海上ルートに戻すということを求めていただきたいと思いますけれども、最後にいかがでしょうか。","respondent":"品川財政課長","answer":"はこういった状況も見ながら、かつ区としてどういう対応をしていったらいいかというところも踏まえながら、検討していきたいと考えています。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"総合審査の説明についてなのですが、総務委員会で以前にもお話ししたのですけれど、結果だけでなく各委員会での議論の中身、経緯だったりも説明していただきたいですし、説明資料もより丁寧なものを求めたいと思います。要望ですが、何かお考えなどがあったら一言頂けたらと思います。これは要望です。こちらについて、区での検査結果の公表についてはどのようにお考えなのかということを伺いたいです。","respondent":"品川財政課長","answer":"ライフライン関係ですけれども、これについては、国等の動き、それから最近ではマスコミ等でもＮＨＫの料金など、いろいろ動きが出ているところですので、そういった状況も踏まえながら様子を見て、必要があれば対応していきたいと考えております。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ライフラインの確保について、国等の動きを見てというのもあったのですけれど、都のほうでも、水道料金やライフラインの４カ月間の何らかの支援があったと思うのです。そういったことがわかりやすくホームページなどで掲載されたらいいということを、苦しい方たち、生活が苦しくなってきた方たちにとにかく情報が届くように、細かく発信していただけたらと要望いたしますが、いかがでしょうか。","respondent":"品川財政課長","answer":"それは、必要に応じて、ホームページ等、周知は考えていきたいと思います。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"あまり中身に入りたくはないのですが、確認だけさせていただきたいところが多少あります。それから、ベビーシッター利用支援事業助成とあるのですけれど、これは具体的にどんなものとして助成されていくのかということを、まず確認したいです。今の計算上、多分、二、三カ月はかかるはずです。さっきの答弁はちょっと危険だと思ったので、それは所管のほうといろいろ確認していただきたいと考えています。","respondent":"品川財政課長","answer":"５月末で全体のどれぐらいが出せるのかというところはまだ未定ですけれども、あくまでも郵送による申請でお金を出せる時期というのが、５月末を目途にというところでの説明です。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"少し大きなくくりで質問したいのですけれども、今回、新型コロナウイルス感染症対策での予算づけで、国・都からの補助金というか、いろいろあるのですけれども、１０分の１０ではないものがありますよね。本来だったら１０分の１０あっていいのではないですか。それが２分の１であったりするので、それはどういう考え方で、区のほうからのお金を出そうという考え方なのか。いかがでしょうか。","respondent":"品川財政課長","answer":"この財政調整基金は、使い方としては非常に柔軟に使える基金ですので、先ほど委員のほうで、見直し、考え直し等が必要ではないかというところなのですが、基本的には財政調整基金の中で対応できるのではないかと考えております。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"例えばオリンピック・パラリンピックなど、延期になってしまったわけですから、それにかかわる経費というのは、来年度に回すという形もとれるわけであって、それはもう、今は集中して新型コロナウイルス感染症対策、あと経済を守っていくのだというところを区民の方にお願いして、「だから、ここの部分は我慢してください。生活を守っていくのだということを、ぜひ表明していただきたいと思います。","respondent":"品川財政課長","answer":"来年度予算につきましても、そういうところも踏まえて、とにかく区民が安心するような政策を積極的に打っていきたいと考えております。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"専決処分にして、一日でも早く皆さんの手元に案内を送る。これは、区でどうしてこんな対応をしてしまったのか、私は不思議でならない。やはり、こういうふうに閣議決定して、皆さんがテレビや新聞報道で見ているならば、即刻、送れるような体制を敷いて、例えば外注にするのではなくて職員を使ってでも、一日でも早く送るべきだったと私は思うのですが、その辺について１点だけお答えください。","respondent":"品川財政課長","answer":"非常に早急にという思いについては区としても全く同じです。ただ、マスコミ等で日程がいろいろと出ているさなか、内部の事務処理の方向、方針といったところは、なかなか区でも、マスコミで出ている内容と同期を合わせて動いているものではないというところが１つあります。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"中小・零細企業、２万件あったらどうやって区で対応できるのですか。品川区はやはりこれだけ繁栄して、これだけ多くの産業が根づいているまちですから、その火は絶やさないようにしていただきたいと私は思います。ですけれど、世帯ですから、親に行くわけですよね。であるなら、やはり人のためになるお金の使い方というのをやってほしいのですが、その点について総合的に見解だけお聞かせください。","respondent":"品川財政課長","answer":"この間、新型コロナウイルス感染症対策を進めている中で、委員のお話のとおり、制度としては、区としてしっかりと対応している動きでいるところなのですが、どうしても実際に具体的事務手続きのところで時間がかかるという部分については。","id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"さっき伺ったのですけれど、聞き逃してしまったかもしれないので、確認なのですけれど、新型コロナウイルス感染症の影響で生活が困窮してしまった方に対して、住居確保給付金以外に区としての支援は、今、検討中なのでしょうか。それともまだ特には検討などはないのか。その部分をお聞かせいただけますか。","respondent":"品川財政課長","answer":"また１つ、このジャンルについては国の政策等でも、事業所のほうの家賃だと思いますけれど、若干ずれている部分があるかとは思いますが、動きは出ているところです。そういったところも見ながら必要性について検討して、必要があれば動いていきたいと考えております。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"そういった、相談に来た方などからも、今、どういった支援が必要なのかと聞き取ることなどは可能だと思いますし、またほかにもいろいろ方法があると思うので、ぜひ少しでも、皆さんの状態がどんどん悪い方向に行かないような支援を、区として当事者の方たちの声を聞いて進めていってほしいと要望いたしますが、いかがでしょうか。","respondent":"品川財政課長","answer":"当然、区民の声、それから状況等も考えながら、必要な施策に対しては早急に打っていきたいという考えは常に持っておりますので、時機を見て、必要であれば対応していきたいとは考えてあります。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういったところで、窓口にかなり多くの方が来ているというところでは、行政が３密をつくるような体制を、何とか工夫して解消していっていただきたいという思いがありますので、ぜひその点は、今からでもできることをしていただければと思いますので、お考えをお聞かせいただければと思います。","respondent":"品川財政課長","answer":"区としても、本当にこの状況をできる限り早く解消していきたいと考えておりますので、どういう点を工夫すればそれがうまくできるのかというところも検討しながら、ぜひ利用者の方が本当に待つことがないような形でやっていきたいところもありますし。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"やはりマイナンバーカードを申請しに来てしまう方の印象としては、５月１日、マイナンバーカードがあればオンラインで申請できるというところの認識にあると思うので、そこを、先ほどのお話では、「郵送で受付けしていってください」という周知をされるということなのですが、今、マイナンバーカードを発行しても、かなり時間がかかるというところで、むしろ郵送のほうが早いのですというところも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"今、各委員の質疑で確認できたところもありますので、そういったところは除きます。それは、子育て世帯の臨時特別給付金についても、どういう封筒で送るのか、新しくつくるのか、この辺をまず教えてください。","respondent":"品川財政課長","answer":"封筒については、現在どのように動いているか、既存のものになるか、その辺は把握してございません。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"もし印刷を業者に委託するのだったら、そういうメッセージをちょっと添えて封筒に入れるなどということも、やはり区民全体で、そういう共通の価値観というか方向性を持って、みんなで乗り越えていこうというメッセージにもなるのではないかと思うので、当然、スピード感というのは大事なので、もしそんなのをやっている暇はないということだったら、当然必要ないのだけど、もし可能なのであれば。","respondent":"品川財政課長","answer":"なかなか全生徒に対してパソコンを配備してというような環境を整えるというのは、この間、各企業がテレワーク等動いている中で、やはりパソコンの台数などもなかなか確保できないという状況の中で、いかに今ある環境の中で。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"先ほど来あった、学生に対する支援も、これは既に公明党も自民党も、国のほうで困窮学生１人１０万円というのは政府に対して提言されて、これが答弁でも既に前向きな答弁が出ているわけですから、そういったことも含め、だけれども、そういったところになかなか支援の手が届かない、そうした区民に対する支援策を、やはり区も同時並行でしっかり考えていただくということも大事ではないかというのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"積極的な予算をさらにつけていただきたいということと、国に対してもしっかり意見を述べていただきたいと要望して賛成。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":28147,"voices":60}},{"id":"r02-20200512-10","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"議会運営委員会","time":"午後 ３時２５分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5360#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1186,"voices":8}},{"id":"r02-20200518-10","meetingId":"r02-cm05","date":"2020年5月18日","dateIso":"2020-05-18","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"資料Ｎｏ.２の常任委員会委員選出一覧表にかかわって一言申し上げたいと思うのですけれども、議会運営委員会委員長宛てに西本区議から意見が届けられていると思います。ご本人から、まだ返答がないということでした。返事をすべきではないかということが１つと、その意見も踏まえて再検討することも必要ではないかと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前回の議運で決定した事項ですので、全会一致ということでやっております。ですから、再検討は必要ないというのが自民党の判断です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"大倉委員","kind":"意見","question":"前回の決定どおりということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、その議運の後に、西本議員が、こういう文書を異議申し立て、再考を求めるということを書面に記して、もし委員長のお手元にも行っているならば、議運で云々ではなくて、委員長として西本議員に、こういうことで決まったからとか、こういう事情でこうなったとか、そういうご説明は少しでもされたらよかったのかなという、それだけ意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"各会派のご意見で見直す必要はないという意見が多数だったと思います。一言だけ意見を述べさせていただきたいと思いますが、やはり私も賛成しました前回の決定を受けて、西本議員から意見が上がり、そのご指摘をなるほどなと思うところがありました。提案のときに総合審査の話がありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5362#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":6484,"voices":24}},{"id":"r02-20200519-6","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"区民委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"の順番を入れ替えまして、２、その他","agenda":"の順番を入れ替えまして、２、その他","exchanges":[{"speaker":"こんの副委員長","kind":"意見","question":"今年度、昨年の５月から今日に至るまで、鈴木真澄委員長を中心に、委員の皆様、そして理事者の皆様にご協力いただきまして、無事滞りなくこの最後の委員会を迎えることになりまして、お世話になりました。思いもかけないこのコロナの問題で、全員の理事者の皆様にご挨拶できないのが残念ですが、両部長のほうから各課長にどうぞよろしくお伝えくださいませ。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"通知カード廃止に伴う事務の変更","agenda":"通知カード廃止に伴う事務の変更","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"１点伺いたいのですけれども、今、定額給付金の件でマイナンバーの担当課が非常に混乱しているということがニュースにもなっておりまして、その後、品川区で１日上限１００件というのはどのようになったかというのを１点伺いたいのと、こちらの件に関して、どれぐらい事務処理が発生して、今。","respondent":"木村戸籍住民課長","answer":"引き続き窓口では、なるべく早く受け取れるような形ということで、郵送、行き来の感染リスクを避けるということもありますので、そういう形をご案内してまいりたいと思っています。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"連日お疲れさまです。窓口に来た場合でも引き続き利用することは可能ということであるのですけれども、これは期間としてはいつぐらいまでとかというのは、ずっとできるのか、それとも何年までなのかとか、そういうことは決まっているのか、教えていただきたいです。","respondent":"木村戸籍住民課長","answer":"国では経過措置というような言い方をしているのですけれども、具体的にそれがいつまでかというのはまだ示されていない状況です。おっしゃるように、未来永劫ということではないとは思っています。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それからもう一つ、今のくにば委員と重複するようなことになるかもしれませんが、課長や部長が外で誘導されていたり、本当に連日ご努力はすごくされているなというので感謝申し上げたいところなのですが、やはり報道なんかでもとにかく行政のスピードがすごく求められる中で、国から急にこういうふうに各自治体でやってくれというところで。","respondent":"木村戸籍住民課長","answer":"特別定額給付金担当と連携いたしまして、これからどういうふうに出していくか、なかなか出し方は難しいところもあるのですけれども、郵送申請が２１日に発送して、これから郵送の処理が入り、大体それでどのぐらいの処理量でというところが出てくると思いますので。","id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問","question":"すいません、給付金の話になって申し訳ないですけれども、期間を例えばもう少しスピードを速めるために何ができるとか、そういったところはなかなか難しいところになってしまうものですか。人を増員するとか、そういったことというのは、なかなか扱うものが扱うものだけに難しいとか、そういうことになってくるところなのでしょうか。","respondent":"鈴木（真）委員長、木村戸籍住民課長","answer":"そこになってしまうと、部署も違ってくると思うので。答えられる範囲でよろしくお願いします。聞く話によれば、基本的には人海戦術しか今のところは、そういう仕組みというのですか、チェックしてというところは報道のとおりでございまして、そこの分量はどうしても縮められないところです。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"意見","question":"本当に連日一生懸命やられた成果で、今日なんかはすごく空いていたななんて思っておりますが、またこのようなときもあるかもしれませんので、ぜひ引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"こういう細かいことは、実はそのときになって、窓口に来て、分からなくてということが、より窓口の煩雑さが、余計に負担がかかってしまうと思われるので、そこをなるだけ事前に軽減できるような方策としては、周知でここに記載されていますけれども、カードを作っている人はもうカードを作ってしまっているので、まだ作っていない方々にこうしたことを事前に分かりやすく何か通知するなどするほうが。","respondent":"木村戸籍住民課長","answer":"ただ、お知らせを最低限しておかなければいけないと思いますので、そういう手続のご案内のところに、例えばホームページであったりチラシであったり、ご案内をするときの本人確認資料という記載のところに丁寧にうたうような形で考えていきたいと思います。","id":"exchange-007"},{"speaker":"こんの副委員長","kind":"意見","question":"ですので、ただでさえ、今、本当にコロナの関係で全庁的に対応してくださって大変な中なので、そうではない通常の業務のところを何とか軽減できる対策という形で申し上げましたが、今おっしゃった対応も考えてくださっているということですので、引き続きご面倒をおかけいたしますけれども、そうした対策などもできる限り頑張っていただければなというところで、意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"}]},{"id":"topic-03","title":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","agenda":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"今ご説明のあった無料相談窓口、最後の部分からお伺いしたいと思います。これはどのぐらいの、出張セミナーもありますけれども、無料相談窓口ということですが、どのぐらいの相談件数を予定なさっているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"国のほうでも徐々に、例えば今日、ホームページなんかを見た限りですと、五反田のＴＯＣとか青物横丁にも相談窓口を作るような内容を見たりしたので、それでかなりできてきているのかなとは思うのですけれども、かなり分かりづらいという話もあるので。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"日曜日、５月１７日付ですか、東京新聞の１面トップに、まさにこの２つの助成金、協力金をめぐって、法外な手数料を取るという記事が出ていて、そんなことはすべきではないという趣旨の記事なのですけれども、そういうのも出るぐらいに、自分で申請できるから自分で申請しなさいよとも書いているのですが、詳しい人はそれができるにしても、実態としては。","respondent":"遠藤商業・ものづくり課長","answer":"持続化給付金の代行というようなお話を頂きましたけれども、例えば国のほうで４００カ所以上のサポート窓口ができるというような話を聞いておりますので、基本的にこちらはパソコンでの申請ということで、インターネットでの申請と聞いておりますので。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問・要望","question":"ただ、実態としてはやはりありますもので、一応考えておいていただきたいとは思います。要望として出しておきます。それから、最初に戻ります。融資あっ旋の件数を教えていただきましたけれども、今のところ、あっ旋された件数は、さっきの話ですと５月７日現在１,６０３件、それから１５日現在で１,８２３件とお教えいただきました。実際に融資が実行された件数はどのぐらいになっているのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"５月１２日に条例改正等をお願いさせていただいたときに実行件数をご案内させていただきましたが、あそこから変化は、今のところ、私どもでは把握できていない状況です。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"たしか４００件弱ぐらいだったと思うのですが、では、どのぐらいあっ旋して、全て実行されるものなのですか、結果的に。","respondent":"遠藤商業・ものづくり課長","answer":"融資あっ旋の金額ですが、うちのほうで恐らく、当時５００万円だったところが多かったので、目いっぱい、まずはうちのほうでお話しされるようなことが多いと。","id":"exchange-012"},{"speaker":"おくの委員","kind":"意見","question":"倒産というか経営危機に陥らせないぞと。その効果を表すためにも、あっ旋した以上はやはり融資の方向へ、融資の方向へ、１００％というのは……、本当に１００％を目指して頑張らなければいけないというのが政治、行政のやるスタンスだと思うのですけれども、六、七割では足りないと思うのですが、その点、どうお考えになりますか。","respondent":"遠藤商業・ものづくり課長","answer":"六、七割とご案内させていただいたのは、私どもが融資あっ旋した部分についての大体何割ぐらいかですので、融資のメニューは、当然区が融資あっ旋する部分以外にも、都道府県でも同じような融資制度をやっておりますし、また、東京商工会議所でもやられていますので。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"あっ旋したうち、あっ旋して、それで、いや、相談が来たりもするのですが、あっ旋してもらったけれども信用保証協会からオーケーが出ないとか、それから結果として融資が受けられないというような相談も来たりするのですが、そういう実態をどのぐらいおつかみになっていますか。お伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"私どもで融資あっ旋した場合でも、その後、実際に貸す銀行あるいは保証協会がそれぞれ審査をやると聞いておりますので、当然その中では、国のほうでは随分、今回のコロナに対してはふだんと違うような対応をするようにという通知は出ているところではありますけれども。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"何で信用保証協会がオーケーを出さないのかとか、あるいは銀行が融資をしないのかとか、そこら辺、何が障害になっているのかというのを、せっかくあっ旋したのに何でそういうふうに結果として融資の実行に至らないのかというのを、私たちも、区側もつかんで、この融資あっ旋で枠をどんどん広げている、区内産業を本当に維持したいということでやっているわけではないですか。難しいとは思いますけれども。","respondent":"遠藤商業・ものづくり課長","answer":"実態を把握するということは大事かと考えていますので、ある程度終わってからになってしまうかもしれませんけれども、この辺の検証はしっかりしていきたいなと考えています。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問・要望","question":"絶対とか全部とか、私も言うつもりはないのです。私もここでうまいこと説明できないのですけれども、非常に専門的な理由で。終わってからではなくて、本当に今、倒産しそうなのだから、だからこそ広く融資が必要だしということだから、まさに同時進行的につかむように私たちは努力しなければいけないし、それを何とかできる限りやっていただきたいと思うのですけれども、いかがでしょう。","respondent":"遠藤商業・ものづくり課長","answer":"関係者からそれぞれ正式な回答という形ではないのですけれども、いろいろお話しする機会がありますので、その辺は捉えていきたいと思っています。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"前回の補正予算の審議は５月１２日でしたけれども、その２日後には江東区で家賃助成が始まりました。都の協力金の対象外の中小企業に対して家賃補助、条件はありますけれども、３０万円の給付というのが江東区の補正予算には盛り込まれました。品川区でもぜひこの方向を私は考えていただきたいと思います。固定費の助成ということに関して、今一度、どのようにお考えになるか、お願いいたしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"これまで私どもも様々な支援といいますか、融資の金額などを上げていただきまして、ほかの枠にないようなものを実施いただいたところです。今、家賃の助成ということがございました。","id":"exchange-017"},{"speaker":"松澤委員","kind":"確認","question":"融資の件で１つ、今、日本政策金融公庫などは民間の金融機関などと連携しまして、幅広く緩和をしましょうみたいな流れができていると確認しているのです。すいません、素人考えになってしまうかもしれないのですが、そういった融資保証の中で、品川区が後ろにつくといいますか、保証をする、保証人が品川区というのですか、何て言えばいいのか……。やめます。すいません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"いいですか。何て言ったらいいか。保証がうまくいかないからなかなかお金を借りられないという部分で、品川区が後ろに私たちがついているから大丈夫ですよみたいな形をとると、スムーズにお金が借りられるという。そんなイメージを持ったもので、そういうのがあると、スピード感を持ってお金を借りられるという部分で、いいのかなという。","respondent":"遠藤商業・ものづくり課長","answer":"私どもの融資あっ旋でできる部分につきましてはやらせていただいて、ほかのところの保証等につきましては、現在のところ、難しいかなと考えています。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"ではもう一つ、コロナでいろいろな部分で補償だ助成金だと一生懸命やって、本当に助かってありがたいのですけれども、終わりもあるわけですよね。終わりがあるという中で、これから先、今後を見据えて、では、これから産業で力を入れるにはどうすればいいのか。何かそういったコロナ収束後のビジョンというのですか、そういうのはまだ全然ないものなのですか。","respondent":"遠藤商業・ものづくり課長","answer":"コロナで大分落ち込んでいる部分がありますので、その後、各企業、商店街なども含めまして、いろいろな事業をやっていきたいという部分で、事態が治まればすぐにやりたいという部分があるかと思いますので、こちらとしてもできる限りの支援をやらせていただきたいということで。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、情報弱者を作ってもらいたくないという思いで質問させていただいているので、また今後、こういうようなことで何か作るのであれば、本当に丁寧に、同じことを何回も分かっているよというぐらい分かるようなパンフレットを作っていただきたいという思いが１点。もう１点は、この申込み方法で事前予約制は分かるのですが、株式会社キャンパスクリエイトというのは、今まで区と関係があった会社ですか。","respondent":"遠藤商業・ものづくり課長","answer":"最後に、中小企業診断士の窓口ですが、現行の融資等の相談につきましては現行のままの体制でやらせていただきまして、すいません、ご案内できませんで失礼しました、２つ、相談窓口を新たに設けするような形になりますけれども。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問・要望","question":"細かくて申し訳ないのですけれども、なぜここの会社だったか。それとも東京とか国からご紹介を受けたとか、過去に何か一緒に仕事をした関係があったとか、なぜここが出てきたのかということを知りたいのです。私が要望したのが書いてあればもっとよかったと思うのですけれども。だって、２５日、３日間あるわけですよね、２２日からやるわけですから。その辺についてお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"本来であれば、前回の補正予算にこちらも本当は乗っけてお金を頂戴するのが筋だろうなとは思っていたのですけれども、そのときまでに金額も間に合わなかったようなところがございまして、ただ、少しでも急ぐという部分がございまして、契約につきましても。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"よく分かりました。納得しました。とにかく課長、今回は、全体を網羅していただきたいと思います。ちょっと分からないとか、特に高齢者の方で、先ほども言いましたけれども、パソコンとかあまりという方においても、決められた時間内だと思うのですけれども、丁寧に説明してあげて、この制度を活用していただけるようになっていただくことを本当に心から望みますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"課長も先ほどおっしゃったように、国のほうでも相談窓口を、五反田ＴＯＣとか青物横丁とか、そういったところでも開設を予定するとお聞きしているのですが、今回のご説明の中で、相談ブースが２つで１日大体十五、六件ということだと思うのですが、協力金のときは５０万円です、２店舗以上は１００万円ですと金額が決まっていたので。","respondent":"遠藤商業・ものづくり課長","answer":"中小企業センター１階ロビーで、場所はありますので、あまりに集中するようであれば、中小企業診断士協会とも相談という形になりますけれども、そういう場面になりましたら、増やすことも考えていきたいと思います。","id":"exchange-024"},{"speaker":"こんの副委員長","kind":"確認","question":"先ほど藤原委員、そして湯澤委員からも同じような質問がありましたので、そこは重ならないようにお聞きしたいと思うのですが、１点、ちょっと重なってしまうかもしれませんけれども、確認ですが、中小企業診断士の相談窓口でやる相談請負業務というのでしょうか、どこまで相談に乗るかということ。細かいことで恐縮ですが、その辺をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"その辺をまず準備していただいて、それを持ってうちの相談窓口に来ていただいて、場合によっては計算などを一緒にさせていただいて、こうこうこうですから、これはこういう形になりますねというような話でサポートさせていただければという状況で今進めておりますので。","id":"exchange-025"},{"speaker":"こんの副委員長","kind":"質問","question":"分かりました。最初にそろえる書類について、自分で計算しなければいけないのを中小企業診断士と一緒に計算をして書き込む数字など書類を用意して、それを持ってサポート会場に行って入力のお手伝いをしてもらうという、こういう２段階で、品川区は申請を希望する人にきちんと給付金が行き渡るようなサポート、支援をするという理解でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回お見えになる方は、パソコンの操作も慣れていないでしょうし、そもそも申請自体やったことがないという方を想定しておりますので、できるだけ丁寧に、本人がちゃんと分かるような形で、場合によってはメモなども作りながらやっていきたいと考えています。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2868#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19367,"voices":66}},{"id":"r02-20200519-7","meetingId":"r02-cm05","date":"2020年5月19日","dateIso":"2020-05-19","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)を先に行います。 それでは、(4)新型コロナウイルス感染症の対応","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)を先に行います。 それでは、(4)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、その中で専門外来に紹介される方がどう変わっているのか、また件数についても、４月３０日までは２６６人ということで伺っているのですけれども、その確認と、どう件数が変わっているのかについてもお聞かせいただきたいと思います。ということになると、今、１８６人までの感染者が確認されているわけですけれども、併せて濃厚接触者の合計の人数が何人ぐらいになるのか。","respondent":"鷹箸保健予防課長","answer":"それから次の質問にも移ってしまうのですが、濃厚接触者も非常に、１８６人いればお１人、ご夫婦であればその同じ人数、家族が４人ならと、たくさん出るので、それを全部我々常勤だけではできませんので、それも派遣の看護師たちにかなりの数をお願いして対応しています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、クリニックのドクターから直接帰国者・接触者外来に紹介されるという件数もあると思うのですけれども、そこのところは把握がされていないということだったので、ちょっと分からなかったですが、品川区の相談センターに来た人数のうち、帰国者・接触者外来に行ったのは２６６人と４月末の段階で伺っていたので、それからさらに検査の件数は減るのかと私は思っていたのですけれども。","respondent":"鷹箸保健予防課長","answer":"先ほどの１,４７０件は保健所のほうの電話相談からご紹介した数以外に、医療機関が紹介した数を全部合わせたものが１,４７０件で、ものすごい数が区内の医療機関あるいは区外の医療機関も含めて帰国者・接触者外来に紹介をされて。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それから保健所の皆さんの頑張りも本当にあって、また医療機関の皆さんの頑張りや努力によって感染が随分少なくなってきたし、また季節的なものもあると思うのですけれども、そういう状況の中で、これから第二波、第三波が必ずやってくるだろうという中で、それに備えた対策を今、この少なくなった時点でやっていくことが必要なのではないかということが言われていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"保健所の件についてはいろいろ伺ったのですけれども、保健センターのほうの対応なのですが、乳幼児健診は元々ずっと密な感じでやっていたと思うのです。それに加えてこれまでちょっとお休みしていた部分だけ人数も増えていると思うのですけれども、具体的にどういう形でやっていくことを考えていらっしゃいますか。","respondent":"榎本荏原保健センター所長","answer":"その４か月児健診を進めながら、その後については１歳６か月児と３歳児健診も、１回の対象人数を減らしますとちょっと回数を増やさないと難しいというところはどうしても出てきますので、そこも工夫しながら全体のスケジュールをうまく組んでやっていきたいと考えています。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"前段のこれまでのところなのですけれども、電話相談あるいはアンケートの返ってきた割合はどのように数字で把握していますか。それから時間を区切ってというのは保健センター側から時間を区切って、あなたは例えばこの日の何時何分から何分の間みたいな形でやっていくのでしょうか。そうすると、何か逆に行けない方も増えてしまうのかなと思うのですが、そこら辺は何か工夫があるか教えてください。","respondent":"榎本荏原保健センター所長","answer":"アンケートの返信についてですけれども、センターによって違うと思いますが、８割から９割ぐらいは返信があって、返信がなかった方にお電話をして返信をいただいたとかというのも含めると、９割ぐらいは集まってきておりまして、アンケートに返信のなかった方にはお電話をして。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"すごく丁寧にやっていただいて、ありがたいと思います。それからお伺いしたいのが、今、コロナで（２）に関係してくるところでもあるのですけれども、いろいろな処方箋などが電話で取れるなどの緩和措置があって、これというのはこの緊急事態宣言ですが、この時期が終わってももう半永久的と言ったらいいのか、こうした体制は続いていくのでしょうか。これはもし分かれば教えていただきたいと思います。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"今回、確かにコロナ対応で特別な通知が出されているのですけれども、これまではオンライン診療は初回は必ず面談というか診察。オンライン診療は見直しを行うことになっています。それと新しい形で進めることになっているから、進める方向は変わらないと思います。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"初診についてはいろいろハードルもあるかと思うのですけれども、通院だと、逆にずっと長く療養されている方なんかの処方箋を電話、ファックスなどでできるというのも、しかも郵送で送ってもらうみたいなのもあったと思いますけれども、その点はどうでしょう。それももしご存じでしたら教えてください。","respondent":"鷹箸保健予防課長","answer":"処方はそのまま継続というのは今までもでしたし、今後も可能かと思います。今回、自宅療養の方に対しても、継続な処方が必要な方については……。","id":"exchange-007"},{"speaker":"若林委員","kind":"質問・要望","question":"ＰＣＲ検査センターを設置して３日間ということで、初動の対応だけお聞きしたいと思います。３日間で３５件ということで、まずこの３５件それぞれの医師会の所属の、いわゆるかかりつけ医等からのご紹介ということで、何軒のクリニックからのご紹介だったかを一つ確認させていただいて、分母として両医師会全体の先生、何百といらっしゃって、そのうちこういうことに参画されている方。教えてください。","respondent":"舩木保健体制整備担当課長","answer":"幾つかご質問をいただきましたが、先週３日間開設いたしましたところで、どのぐらいのかかりつけ医から来た結果の３５件であるとか、全体の医師会の会員の先生方でどのぐらいのご協力をというところにつきましては、実は定期的に医師会と私どもで情報交換といいますか。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと質問を忘れていたのですけれども、前回もお伺いしました妊婦パッケージ、保健センター。その後、どういう形で実施するか、検討を進められましたか。この間は検討中というお話だったと思いますけれども。","respondent":"榎本荏原保健センター所長","answer":"妊婦の追加パッケージの話で、多分、対象の方のさかのぼりというか、その辺りの話かと。検討中と、まだちょっと未確定というところで、都からは基準日が４月１日。その話でしょうか。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"都が言っているのは４月１日に妊娠状態であった方が対象で、その後生まれた方でもオーケーだよと。その後生まれたのはオーケーだけれども、４月１日以降に新たに妊娠された方はちょっとペンディングだけれども、区で何らか対象にしようと考えているという意味で受け取ってよろしいのでしょうか。それとスケジュール的なものも併せて教えていただけば。基準日というのはそういう意味ですね。","respondent":"榎本荏原保健センター所長","answer":"都からの通知の基準日というのは４月１日以降、今年度３月３１日までの時点で妊婦だった方を全て対象にするということなのですが、妊娠中に状況把握や相談をしたということが前提でありましたので。","id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"電話相談はもう始まって、電話での確認とかはもう始まっているということでよろしいのでしょうか。","respondent":"榎本荏原保健センター所長","answer":"電話での相談が始まっているかというご質問でしたけれども、基本的には電話ですと、お１人お１人というとかなり時間がかかってしまいますので、いろいろ検討して、アンケートのやりとりでという形をまずとって。","id":"exchange-011"}]},{"id":"topic-02","title":"立会川幹線雨水放流管工事（東京都下水道局施工）","agenda":"立会川幹線雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと確認させていただきたいのが、改めてなのですけれども、この月見橋の家というのは元々何の施設だったのか、たしかデイサービスはしていたような気がするのですが、どういう施設だったのかを改めて教えていただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"月見橋の家の仕様・構造の変更ですが、ここは、細かいところはまだ伺ってはいないのですが、ただ、当初予定していた元に戻ったとき、工事に入る前に３階建てだった建物といった構造の大きなところは変更はないと伺っております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここに仕様・構造の変更に伴う到達防護工の見直しによる補助工法の追加と書いてあるのでちょっと伺ったのですが、基本的には変わらないのに、そこがこういうふうに書いてあるのはどういうことなのかがちょっとよく分からないです。","respondent":"宮尾高齢者福祉課長","answer":"私が変わらないと申し上げたのは、基本的な施設の構成ですとか、広さですとか、当初予定をしておりました内容とか、そこはしっかりと担保をしてもらえるです。工事の詳しい工法については存じ上げておりませんが、そこはしっかりと担保してくれるということは確認をしています。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"この仮移転先というのは、何といってもプレハブ造りで、そこまで長年使うことを想定はしていなかたのではないかと思うのですが、一応の耐用年数とか契約年数、それからなかなか工事で６年間一気に延びるというのは珍しいと思うのですけれども、その間に例えば不具合が出てきたりとか、居住性が落ちていたりとか、何かこの仮移転先の改善みたいなことの必要性をどう受け止めて。","respondent":"宮尾高齢者福祉課長","answer":"仮移転先のプレハブですが、実は今回、工事の変更が決まるのが３回目なのです。","id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"やはりプレハブがかなり長期になっていて、恒久施設よりも居住性が劣るのは確かなので、不具合を直すというだけではなくて、ちょっと今の施設の基準に合わせたようなことを考えていただけるとありがたいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"西大井三丁目国家公務員宿舎","agenda":"西大井三丁目国家公務員宿舎","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの場所は防災機能ということで防災広場と障害者施設ということなのですけれども、おおよそ半々ぐらいの面積の割合ということになるのでしょうか。障害者グループホームや短期入所などの障害者施設の規模がどれぐらいになるのかが今の時点で決まっているようであれば、土地の面積ですとか延床面積、どれぐらいの障害者施設がつくられるのかというところを教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"２点目にグループホームと短期入所の人数ですけれども、この敷地内で最大の人数ということで今、想定しまして、１９人程度ということになっております。そのうち短期入所ですけれども、今のところ３名を予定しています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者のグループホームにしても、短期入所にしても、すごく障害者の皆さんから待ちに待たれている施設ですので、こういう形でできるのはすごく当事者また家族の皆さんにとってもすごく待ち望んだ施設ということになると思うのですけれども、そこの中で、例えば短期入所では医療的ケアの人とかも対象にするのかとか。","respondent":"松山障害者福祉課長","answer":"今後ですけれども、そういったお声は障害者福祉課あるいは今回の基礎調査等々の中から既に頂いております。現在のこちらの説明会は周辺住民に対する説明会ですので、そちらのお声も併せて頂きながら、区として検討を図ってまいりたいと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"地域の方に対しての説明会はもうされていますよね。障害者の当事者、家族の方、団体の皆さんですとか、そういう関係の方のところに対して、ここにこういう施設ができるという説明会みたいなのはいつ頃計画されているのかについて、最後にお聞かせください。","respondent":"松山障害者福祉課長","answer":"現段階では１９名程度の障害者のグループホームをこちらのほうに国の土地を取得して造りたいということで、案を住民説明会のほうに出させていただいたという時点ですので、もう少し固まりましたら、詳細については当事者に。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に一言。実際に当事者やご家族の方というのはいろいろな思いを持っていらっしゃいますので、また設計とかということに対してもいろいろなご要望とか何かもあると思いますので、ぜひ当事者、家族の方々の声を聞きながら進めていただくということでよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"確認","question":"これも多分指定管理で運営をされていくことになるのか、ちょっと先ほどのやりとりがよく分からなかったのですけれども、それを確認したいのと、施設の設計よりも前なのか後なのか、それはどんな感じの順番で考えていらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"それから設計については、運営事業者と設計事業者ということになろうかと思いますけれども、設計の後で運営をと今のところは考えております。","id":"exchange-020"},{"speaker":"あべ委員","kind":"意見","question":"まだ取得前なのでということですけれども、直営でやるということはなかなか考えづらいのかと思います。運営しやすい施設づくりという観点も必要だと思いますので、また取得後により良い方法を考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-04","title":"医療的ケア児地域生活支援促進事業","agenda":"医療的ケア児地域生活支援促進事業","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"医療的ケア児の施設をつくるということなんですけれども、そもそも医療的ケア児の人数が何人いるのかを教えていただきたいと思います。もう１つは医療的ケア児の方が通ってくる場合に、かなり様々準備をしたりとか大変な状況があると思うのですけれども、送迎はあるのかどうかについても教えてください。","respondent":"松山障害者福祉課長","answer":"それから全ての医療的ケア児が対象なのかというご質問ですけれども、人工呼吸器を付けている方を含めた全ての医療的ケアが必要なお子さんが対象と考えています。それから３点目、送迎についてですが、現段階では難しいと考えています。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それなので、この２５人というのはアンケートに答えた数であって、実際はもっと多いのではないかと思うのですけれども、そういう点でいえば、なぜこの２３人ということになるのかという思いがしているのですが、なかなかこの医療的ケアの方というのは障害福祉サービスを受けられていない方が多くて、医療のほうだけ使われているという方がすごく多かったりするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません。それともう１つなのですけれども、今回の地域生活支援促進事業というのは区の独自の事業ということでいいのでしょうか。地域生活支援事業として区が行うということでもないということで、丸々区の事業ということで捉えていいのか、その点についても伺いたいと思います。そのところをお願いします。","respondent":"松山障害者福祉課長","answer":"地域生活支援事業の枠組みに当てはまるのか、今後医療的ケアの国からの補助事業に当てはまるのかは、しばらく様子を見ながら事業の組み立てをしていきたいと考えています。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"医療的ケアの方を１人で乗せることがなかなか大変なので行動が制限されるとか、常に介護者と運転者の２人が必要だとか、感染に気を付けなければならないので移動手段に制限があるとか、とにかく酸素ボンベだったりとか呼吸器だったりとかということで、とにかく荷物も多いし、残量も気になるし、感染のリスクも考えなくてはいけないので。","respondent":"松山障害者福祉課長","answer":"ただ、戸越ルームという立地の状況です。今後、現段階ではまずは相談とつどいの場所、あるいは交流の場所、遊び場の提供から始めるですので、この状態から始めて、今後、医療的ケア児を支えるようなことのサービスにつながればと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あの中でせめて医療的ケアの方が出していただいたものを独自に集計して、そこの中からニーズを把握するということができるものなのかどうなのか、ちょっと検討していただきたいと思うのと、それから私は、改めてそれほど多い人数ではないので、医療的ケア児、これから協議会も立ち上げていくわけですから、医療的ケア児・者に対するニーズ調査を行い。","respondent":"松山障害者福祉課長","answer":"１点目ですけれども、確かに送迎については課題と認識しておりますし、医療的ケアのお子さんを抱える保護者の声を実際に生で聞ける貴重な場所だと感じておりますので、そういったご相談のお声を聞きながら今後の事業展開につなげていきたいと考えています。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問・要望","question":"もう１つが、実際に親御さんたちのいろいろなワークショップとか話し合いとかどういう形になるか分からないですけれども、同じ思いを共有したりしている時間だけでもお子さんを一時預かりしてくださったり、その時間だけでも見ていただいたり、そういった要望もありまして、世田谷区にあるもみじの家なんかは利用面談が３年待ちだそうで、それぐらいの人気の、皆さんに注目される施設になるといいなと思うと。","respondent":"松山障害者福祉課長","answer":"使いやすい施設にするためのやはり外出サポートというご提案を頂きましたので、検討していきたいと考えています。それから２点目ですけれども、事業内容の工夫、運営方法の中でお子さんを預かりしてという形になろうかと思います。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問・要望","question":"プロポーザルもまだこれからなのですけれども、こういった取組みをやるというような事業者にぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"区内の医療的ケア児はとりあえず２３人という数字が出ていたわけですけれども、これは１８歳以下の全てのお子さんと考えてよろしいでしょうか。この２３人の中で、送迎がなくても自力で、もちろんお子さん、もちろんと言っていいのか、ここに来られる方というのはどのぐらいの割合の方がいらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"自力でいらっしゃれるかどうかはちょっとこちらのほうではまだ把握はしておりませんが、何かしらのサポートでいらっしゃれる方が、人数的には明確にお答えはできませんけれども、全くいらっしゃれないという方はそれほど多くはないであろうと思います。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうした施設ができるのは大変ありがたいなと思いますし、必要な方皆さんに活用していただきたいと思うのです。なので人数が少ないわけですから、そこを１人１人潰していってほしい。ちょっとそれについてのお考えを伺いたいと思います。使い方として、予約制になっていくのでしょうか。相談は予約だと思うのですけれども、利用自体はどのようにお考えでしょうか。","respondent":"松山障害者福祉課長","answer":"それから２点目の予約制なのか、ふらっと行けるのかというところですけれども、確かにふらっとというのがなかなかもちろん厳しいところではありますけれども、ただできれば区といたしましては、兄弟のお子さんも一緒に連れて。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"そうするごとにそれぞれスタッフが必要になると思います。１,２００万円のほとんどが人件費だと思うのですけれども、この委託料の設定できちんと医療的ケアに対応できるスタッフの方が雇えるのかとちょっと疑問なのですが、委託料の中の人件費を幾らと見込んでいらっしゃるのでしょうか。それで十分とお考えになられるか教えてください。","respondent":"松山障害者福祉課長","answer":"委託料は委員のご指摘のとおり、ほぼ人件費です。人件費につきましては、１月から３月の間、３か月分を見込んでおりますので、こちらのほう、委託料につきましては、十分に可能なものと考えております。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと安心しました。この数字で年間なのはあまりにもどうするのだろうという感じだったので、それはちょっと安心いたしました。ただ、ここで看護師以外のスタッフが相当の経験を持った方でないとと思うのですけれども、そこが実施要領の中ではちょっと見当たらなかったものですから、それを加えたほうがいいのではないかと思うのですが、どのように思われるでしょうか。","respondent":"松山障害者福祉課長","answer":"やはり相談時に医療的なケアの相談が受けられるという体制をとるためには、一定程度の経験が必要なものと考えております。こちらの公募案につきましては、あくまでも案とさせていただいています。ちょっと入れる文言については検討していきたいと考えています。","id":"exchange-032"},{"speaker":"あべ委員","kind":"質問","question":"ぜひよろしくお願いします。この医療的ケアの施設なのですが、品川区としての医療的なケアの子どもたちに対する医療的ケアに関する政策とセットで動いていくと思うのですけれども、先ほどもちょっと出ましたが、協議会との関係、それから既に動いている地域自立支援協議会との関係というのは、この施設をどう捉えたらいいのでしょうか。","respondent":"松山障害者福祉課長","answer":"自立支援協議会は非常に課題の範囲が広うありますので、医療的ケアにつきましてはこちらの医療的ケアに特化した連絡会で意見交換、情報共有、連携強化を行ってまいりたいと考えております。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"それから本年度コロナで止まってしまっている部分があるのですけれども、見通しなり教えていただければと思います。","respondent":"松山障害者福祉課長","answer":"協議会の開催の仕方も、例えば東京都自立支援協議会ですと書面開催ですとかいったようなこともやってありますので、そういったことも含めまして考えていきたいと思っています。","id":"exchange-034"},{"speaker":"あべ委員","kind":"提案","question":"書面開催も結構いいと思いますし、今でしたら障害がある方、当事者も参加できるという意味ではオンライン開催なども含めて考えていっていただくといいかと思います。最後は提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"厚労省のほうが医療的ケア児・者の問題とかを話し合う協議の場をつくるようにということで、平成３０年度末までに各自治体でそういう協議の場をつくるようにという方針を出して、品川区の場合、１年ちょっと遅れてしまっているような状況で、でももう準備会はつくられて、コロナの問題がなければもう協議会も実際に動き出すというところまで来ていたと思うのですけれども、コロナの問題があって。","respondent":"松山障害者福祉課長","answer":"それから大人のほうに関しますと、ピッコロが始まっておりますので、そちらのメンバーになります。大体メンバーは２０人以内を想定しております。それから障害者団体です。２つの団体から出ていただいています。","id":"exchange-036"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"どうも１年間お疲れさまです。引き続き、区民の皆さんや施設の要望をお聞きいただいて応えていただけたらと思いますし、第二波、第三波というのも心配される中ですので、今後も見通して、区民の命と暮らしを守るために共に頑張っていけたらと思います。１年間、お疲れさまでした。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3566#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29627,"voices":114}}]);
